/**
 * Global Store
 * Captures HighLevel global sections, theme settings, and templates.
 * These comprise the design-system layer of a funnel — fonts, colors, shared
 * sections — that must be cloned alongside pages to reproduce a full funnel.
 */

// ── Storage keys ──────────────────────────────────────────────────────────────
export const GLOBAL_SECTIONS_KEY  = "clonelevel_global_sections";
export const THEME_SETTINGS_KEY   = "clonelevel_theme_settings";
export const TEMPLATES_KEY        = "clonelevel_templates";

const MAX_GLOBAL_SECTIONS = 100;
const MAX_THEME_RECORDS   = 30;
const MAX_TEMPLATES       = 100;

// ── Types ─────────────────────────────────────────────────────────────────────

export interface GlobalSectionRecord {
  sectionId:   string;
  snapshotId:  string;
  capturedAt:  string;
  url:         string;
  name?:       string;
  type?:       string;          // "header" | "footer" | "section" | "popup" | "sticky"
  layout:      unknown;         // parsed layout JSON
  assetUrls:   string[];        // image/video/font URLs found in this section
  raw:         string;          // full JSON, capped at 200 KB
}

export type ThemeVarType = "color" | "font" | "spacing" | "radius" | "other";

export interface ThemeVariable {
  name:   string;   // e.g. "--primary-color", "fontFamily", "headlineFont"
  value:  string;   // e.g. "#6366f1", "Inter, sans-serif"
  type:   ThemeVarType;
}

export interface ThemeSettingsRecord {
  themeId:    string;
  snapshotId: string;
  capturedAt: string;
  url:        string;
  source:     "funnel" | "page" | "global" | "unknown";
  sourceId?:  string;   // funnelId or pageId
  variables:  ThemeVariable[];
  raw:        string;
}

export interface TemplateRecord {
  templateId:  string;
  snapshotId:  string;
  capturedAt:  string;
  url:         string;
  name?:       string;
  category?:   string;
  tags?:       string[];
  pageCount?:  number;
  preview?:    string;   // thumbnail URL
  raw:         string;   // capped at 500 KB
}

// ── URL classification ─────────────────────────────────────────────────────────

export type GlobalTag = "GLOBAL_SECTION" | "THEME_SETTINGS" | "TEMPLATE" | null;

export interface GlobalClassification {
  tag:       GlobalTag;
  sectionId?: string;
  themeId?:   string;
  templateId?: string;
  sourceId?:  string;
  source?:    ThemeSettingsRecord["source"];
}

export function classifyGlobalUrl(url: string, method: string): GlobalClassification {
  const u = url.toLowerCase();
  const m = method.toUpperCase();

  // Only GET responses contain the data we want to capture
  if (m !== "GET") return { tag: null };

  // ── Global Sections ──────────────────────────────────────────────────────────
  // /funnels/global-sections, /global-sections, /funnel/{id}/global-sections
  if (
    u.includes("/global-sections") ||
    u.includes("/global-section") ||
    u.includes("/prebuilt-section") ||
    u.includes("/shared-sections") ||
    u.includes("/global-elements")
  ) {
    const sid = extractId(url, /\/global-sections?\/([^/?&#\s]+)/i) ??
                extractId(url, /\/global-elements?\/([^/?&#\s]+)/i);
    return { tag: "GLOBAL_SECTION", sectionId: sid };
  }

  // ── Theme / Style Settings ────────────────────────────────────────────────────
  if (
    u.includes("/themes") || u.includes("/theme") ||
    u.includes("/style-settings") || u.includes("/style/settings") ||
    u.includes("/funnel-theme") || u.includes("/fonts-settings") ||
    u.includes("/brand-settings") || u.includes("/brand/settings") ||
    u.includes("/custom-css") || u.includes("/global-styles") ||
    u.includes("/design-system") || u.includes("/color-palette")
  ) {
    const funnelMatch = url.match(/\/funnels?\/([^/?&#\s]+)/i);
    const pageMatch   = url.match(/\/pages?\/([^/?&#\s]+)/i);
    const sourceId    = funnelMatch?.[1] ?? pageMatch?.[1];
    const source: ThemeSettingsRecord["source"] = funnelMatch ? "funnel" : pageMatch ? "page" : "global";
    return { tag: "THEME_SETTINGS", themeId: extractId(url, /\/themes?\/([^/?&#\s]+)/i), sourceId, source };
  }

  // ── Templates ─────────────────────────────────────────────────────────────────
  if (
    u.includes("/templates") || u.includes("/template") ||
    u.includes("/marketplace") || u.includes("/builder-templates") ||
    u.includes("/funnel-templates") || u.includes("/page-templates") ||
    u.includes("/prebuilt-funnels") || u.includes("/snapshot")
  ) {
    const tid = extractId(url, /\/templates?\/([^/?&#\s]+)/i) ??
                extractId(url, /\/snapshots?\/([^/?&#\s]+)/i);
    return { tag: "TEMPLATE", templateId: tid };
  }

  return { tag: null };
}

function extractId(url: string, pattern: RegExp): string | undefined {
  const m = url.match(pattern);
  const candidate = m?.[1];
  // Filter out path-segment false positives
  if (!candidate || candidate === "fetch" || candidate === "list" || candidate === "all") return undefined;
  return candidate;
}

// ── CSS variable / theme variable extraction ───────────────────────────────────

const COLOR_KEYS = new Set([
  "primaryColor","primary_color","primary",
  "secondaryColor","secondary_color","secondary",
  "accentColor","accent_color","accent",
  "backgroundColor","bg","background",
  "textColor","text_color","text",
  "buttonColor","button_color",
  "headlineColor","headline_color",
  "linkColor","link_color",
  "borderColor","border_color",
  "--primary","--secondary","--accent","--background","--text","--bg",
  "--primary-color","--secondary-color","--accent-color",
  "--button-color","--headline-color","--link-color",
]);

const FONT_KEYS = new Set([
  "fontFamily","font_family","fontfamily",
  "headlineFont","headline_font","headlinefont",
  "contentFont","content_font","contentfont",
  "primaryFont","primary_font","primaryfont",
  "bodyFont","body_font","bodyfont",
  "h1Font","h2Font","h3Font",
  "--font-family","--headline-font","--body-font","--content-font","--primary-font",
]);

const SPACING_KEYS = new Set([
  "borderRadius","border_radius","radius",
  "padding","margin","gap","spacing",
  "--border-radius","--radius","--spacing","--gap",
]);

function isColorValue(v: string): boolean {
  return /^#[0-9a-f]{3,8}$/i.test(v) || /^rgb/.test(v) || /^hsl/.test(v);
}

function isFontValue(v: string): boolean {
  return v.length > 1 && v.length < 200 && /[a-zA-Z]/.test(v) && !v.startsWith("http");
}

function classifyVar(key: string, value: string): ThemeVarType {
  const k = key.toLowerCase().replace(/-/g, "").replace(/_/g, "");
  if (COLOR_KEYS.has(key) || isColorValue(value)) return "color";
  if (FONT_KEYS.has(key) || k.includes("font")) return "font";
  if (SPACING_KEYS.has(key) || k.includes("radius") || k.includes("spacing")) return "spacing";
  return "other";
}

export function extractThemeVariables(obj: unknown, depth = 0, vars: Map<string, ThemeVariable> = new Map(), seen = new WeakSet()): ThemeVariable[] {
  if (depth > 20 || obj === null || typeof obj !== "object") return [...vars.values()];
  if (seen.has(obj as object)) return [...vars.values()];
  seen.add(obj as object);

  const o = obj as Record<string, unknown>;

  for (const [k, v] of Object.entries(o)) {
    if (typeof v === "string" && v.length > 0 && v.length < 300) {
      const isColorK   = COLOR_KEYS.has(k);
      const isFontK    = FONT_KEYS.has(k);
      const isSpacingK = SPACING_KEYS.has(k);
      const isColorV   = isColorValue(v);
      if (isColorK || isFontK || isSpacingK || isColorV || k.startsWith("--")) {
        const type = classifyVar(k, v);
        if (!vars.has(k)) {
          vars.set(k, { name: k, value: v, type });
        }
      }
    }
    if (v && typeof v === "object" && !Array.isArray(v)) {
      extractThemeVariables(v, depth + 1, vars, seen);
    }
    if (Array.isArray(v)) {
      for (const item of v) {
        if (item && typeof item === "object") {
          extractThemeVariables(item, depth + 1, vars, seen);
        }
      }
    }
  }
  return [...vars.values()];
}

// ── Asset URL extraction (reused for global sections) ─────────────────────────

const URL_RE = /https?:\/\/[^\s"'<>`,)\\]{10,}/g;

function extractAssetUrlsFromJson(obj: unknown): string[] {
  const urls = new Set<string>();
  const IMAGE_EXTS = /\.(jpg|jpeg|png|gif|webp|svg|avif|mp4|webm|woff2?|ttf|otf)(\?|$)/i;
  const seen = new WeakSet();

  function walk(v: unknown, d: number) {
    if (d > 25 || v === null) return;
    if (typeof v === "string") {
      const raw = v.trim();
      if (raw.startsWith("http") && IMAGE_EXTS.test(raw)) urls.add(raw);
      else if (raw.includes("http")) {
        let m: RegExpExecArray | null;
        URL_RE.lastIndex = 0;
        while ((m = URL_RE.exec(raw)) !== null) {
          const u = m[0].replace(/[.,;:)}\]"']+$/, "");
          if (IMAGE_EXTS.test(u)) urls.add(u);
        }
      }
      return;
    }
    if (typeof v !== "object") return;
    if (seen.has(v as object)) return;
    seen.add(v as object);
    if (Array.isArray(v)) { v.forEach((i) => walk(i, d + 1)); }
    else { for (const val of Object.values(v as Record<string, unknown>)) walk(val, d + 1); }
  }

  walk(obj, 0);
  return [...urls];
}

// ── Storage helpers ────────────────────────────────────────────────────────────

export async function getGlobalSections(): Promise<GlobalSectionRecord[]> {
  const r = await chrome.storage.local.get(GLOBAL_SECTIONS_KEY);
  return Array.isArray(r[GLOBAL_SECTIONS_KEY]) ? r[GLOBAL_SECTIONS_KEY] : [];
}

export async function getThemeSettings(): Promise<ThemeSettingsRecord[]> {
  const r = await chrome.storage.local.get(THEME_SETTINGS_KEY);
  return Array.isArray(r[THEME_SETTINGS_KEY]) ? r[THEME_SETTINGS_KEY] : [];
}

export async function getTemplates(): Promise<TemplateRecord[]> {
  const r = await chrome.storage.local.get(TEMPLATES_KEY);
  return Array.isArray(r[TEMPLATES_KEY]) ? r[TEMPLATES_KEY] : [];
}

export async function clearGlobalSections(): Promise<void> { await chrome.storage.local.remove(GLOBAL_SECTIONS_KEY); }
export async function clearThemeSettings():  Promise<void> { await chrome.storage.local.remove(THEME_SETTINGS_KEY); }
export async function clearTemplates():      Promise<void> { await chrome.storage.local.remove(TEMPLATES_KEY); }
export async function clearGlobalStore():    Promise<void> {
  await chrome.storage.local.remove([GLOBAL_SECTIONS_KEY, THEME_SETTINGS_KEY, TEMPLATES_KEY]);
}

// ── Store writers ─────────────────────────────────────────────────────────────

function pluck(obj: unknown, ...keys: string[]): string | undefined {
  if (!obj || typeof obj !== "object") return undefined;
  const o = obj as Record<string, unknown>;
  for (const k of keys) {
    if (typeof o[k] === "string" && o[k]) return o[k] as string;
  }
  return undefined;
}

export async function storeGlobalSection(
  snapshotId: string, capturedAt: string, url: string, body: string,
  cls: GlobalClassification,
): Promise<void> {
  let parsed: unknown;
  try { parsed = JSON.parse(body); } catch { return; }

  // Handle both array responses (list of sections) and single-object responses
  const items: unknown[] = Array.isArray(parsed) ? parsed : [parsed];

  const existing = await getGlobalSections();
  const fresh: GlobalSectionRecord[] = [];

  for (const item of items) {
    const id = cls.sectionId ?? pluck(item, "id", "sectionId", "_id") ?? snapshotId;
    const name = pluck(item, "name", "title", "label");
    const type = pluck(item, "type", "sectionType", "elementType");
    const layout = (item as any)?.layout ?? (item as any)?.body ?? (item as any)?.content ?? item;
    const assetUrls = extractAssetUrlsFromJson(layout);
    const raw = JSON.stringify(item).slice(0, 200_000);

    const record: GlobalSectionRecord = {
      sectionId: id, snapshotId, capturedAt, url, name, type, layout, assetUrls, raw,
    };

    // Deduplicate by sectionId
    if (!existing.some((r) => r.sectionId === id)) fresh.push(record);
  }

  if (fresh.length === 0) return;
  const updated = [...fresh, ...existing].slice(0, MAX_GLOBAL_SECTIONS);
  await chrome.storage.local.set({ [GLOBAL_SECTIONS_KEY]: updated });
}

export async function storeThemeSettings(
  snapshotId: string, capturedAt: string, url: string, body: string,
  cls: GlobalClassification,
): Promise<void> {
  let parsed: unknown;
  try { parsed = JSON.parse(body); } catch { return; }

  const variables = extractThemeVariables(parsed);
  if (variables.length < 2) return;  // Skip if not theme-like

  const themeId = cls.themeId ?? pluck(parsed, "id", "themeId") ?? snapshotId;
  const raw = body.slice(0, 200_000);

  const record: ThemeSettingsRecord = {
    themeId, snapshotId, capturedAt, url,
    source: cls.source ?? "unknown",
    sourceId: cls.sourceId,
    variables, raw,
  };

  const existing = await getThemeSettings();
  // Update if themeId matches, otherwise prepend
  const filtered = existing.filter((r) => r.themeId !== themeId);
  const updated  = [record, ...filtered].slice(0, MAX_THEME_RECORDS);
  await chrome.storage.local.set({ [THEME_SETTINGS_KEY]: updated });
}

export async function storeTemplate(
  snapshotId: string, capturedAt: string, url: string, body: string,
  cls: GlobalClassification,
): Promise<void> {
  let parsed: unknown;
  try { parsed = JSON.parse(body); } catch { return; }

  const items: unknown[] = Array.isArray(parsed)
    ? parsed
    : ((parsed as any)?.templates ?? (parsed as any)?.data ?? [parsed]);

  const existing = await getTemplates();
  const fresh: TemplateRecord[] = [];

  for (const item of items) {
    const id = cls.templateId ?? pluck(item, "id", "templateId", "_id") ?? snapshotId;
    const name     = pluck(item, "name", "title", "templateName");
    const category = pluck(item, "category", "categoryName", "type");
    const preview  = pluck(item, "thumbnailUrl", "preview", "previewUrl", "coverImage");
    const tags     = Array.isArray((item as any)?.tags) ? (item as any).tags : undefined;
    const pageCount = typeof (item as any)?.pages === "number" ? (item as any).pages
      : Array.isArray((item as any)?.pages) ? (item as any).pages.length : undefined;
    const raw = JSON.stringify(item).slice(0, 500_000);

    if (!existing.some((r) => r.templateId === id)) {
      fresh.push({ templateId: id, snapshotId, capturedAt, url, name, category, tags, pageCount, preview, raw });
    }
  }

  if (fresh.length === 0) return;
  const updated = [...fresh, ...existing].slice(0, MAX_TEMPLATES);
  await chrome.storage.local.set({ [TEMPLATES_KEY]: updated });
}

// ── Main dispatch ─────────────────────────────────────────────────────────────

/**
 * Called from debugger-network after every snapshot capture.
 * Routes to the appropriate store writer based on URL classification.
 */
export async function classifyAndStoreGlobal(
  snapshotId: string, capturedAt: string, url: string, method: string, body: string,
): Promise<void> {
  if (!body || body.trim().length < 10) return;

  const cls = classifyGlobalUrl(url, method);
  if (!cls.tag) return;

  // Must look like JSON
  const trimmed = body.trimStart();
  if (!trimmed.startsWith("{") && !trimmed.startsWith("[")) return;

  switch (cls.tag) {
    case "GLOBAL_SECTION":
      await storeGlobalSection(snapshotId, capturedAt, url, body, cls);
      break;
    case "THEME_SETTINGS":
      await storeThemeSettings(snapshotId, capturedAt, url, body, cls);
      break;
    case "TEMPLATE":
      await storeTemplate(snapshotId, capturedAt, url, body, cls);
      break;
  }
}

// ── Also scan ANY response for theme variables if URL is a funnel/page fetch ──
// This extracts theme data from page/funnel schema responses as a bonus pass.

export async function tryExtractThemeFromAnyResponse(
  snapshotId: string, capturedAt: string, url: string, body: string,
): Promise<void> {
  if (!body || body.trim().length < 50) return;
  const u = url.toLowerCase();

  // Only scan likely HL endpoints, skip noise
  const isHlEndpoint = u.includes("gohighlevel.com") || u.includes("leadconnectorhq.com") || u.includes("/funnels/");
  if (!isHlEndpoint) return;

  let parsed: unknown;
  try { parsed = JSON.parse(body); } catch { return; }

  const variables = extractThemeVariables(parsed);
  if (variables.length < 3) return; // Require at least 3 theme vars to avoid false positives

  const themeId = snapshotId; // Use snapshot ID as deduplication key for inline theme data
  const raw = body.slice(0, 200_000);

  const funnelMatch = url.match(/\/funnels?\/([^/?&#\s]+)/i);
  const pageMatch   = url.match(/\/pages?\/([^/?&#\s]+)/i);
  const sourceId = funnelMatch?.[1] ?? pageMatch?.[1];
  const source: ThemeSettingsRecord["source"] = funnelMatch ? "funnel" : pageMatch ? "page" : "unknown";

  const record: ThemeSettingsRecord = {
    themeId, snapshotId, capturedAt, url,
    source, sourceId, variables, raw,
  };

  const existing = await getThemeSettings();
  // Avoid storing duplicate inline themes; only store if we have interesting new variables
  const alreadyKnownKeys = new Set(existing.flatMap((r) => r.variables.map((v) => v.name)));
  const newVars = variables.filter((v) => !alreadyKnownKeys.has(v.name));
  if (newVars.length < 2) return;

  const updated = [record, ...existing].slice(0, MAX_THEME_RECORDS);
  await chrome.storage.local.set({ [THEME_SETTINGS_KEY]: updated });
}

// ── Upgraded full clone package ────────────────────────────────────────────────

export interface FullClonePackage {
  formatVersion:   string;
  sourceType:      "funnel" | "page" | "template";
  exportedAt:      string;
  funnel?:         unknown;
  pages?:          unknown[];
  globalSections:  GlobalSectionRecord[];
  themeSettings:   ThemeVariable[];    // merged, deduplicated
  templates:       TemplateRecord[];
  assets:          unknown[];          // filled in by caller
  importOrder: string[];               // ordered import step descriptions
}

export async function buildFullClonePackage(funnelId?: string): Promise<FullClonePackage> {
  const [globalSections, themeRecords, templates] = await Promise.all([
    getGlobalSections(),
    getThemeSettings(),
    getTemplates(),
  ]);

  // Merge and deduplicate theme variables across all theme records, latest wins
  const mergedVars = new Map<string, ThemeVariable>();
  for (const rec of [...themeRecords].reverse()) {
    for (const v of rec.variables) mergedVars.set(v.name, v);
  }

  const importOrder = [
    "1. Upload & register asset files (images, videos, fonts)",
    "2. Apply theme settings (CSS variables, font families, colors)",
    "3. Create global sections and register IDs",
    "4. Create funnel shell (name, domain, steps)",
    "5. Create each page within funnel steps",
    "6. Apply page layouts (attach builder JSON)",
    "7. Replace global section references with imported IDs",
    "8. Publish funnel",
  ];

  return {
    formatVersion:  "2.0",
    sourceType:     "funnel",
    exportedAt:     new Date().toISOString(),
    globalSections,
    themeSettings:  [...mergedVars.values()],
    templates,
    assets:         [],  // filled by caller who imports from asset-store
    importOrder,
  };
}
