const TRACKING_PARAMS = new Set([
  "utm_source", "utm_medium", "utm_campaign", "utm_term", "utm_content",
  "fbclid", "gclid", "gclsrc", "dclid", "gbraid", "wbraid",
  "msclkid", "twclid", "li_fat_id",
  "mc_cid", "mc_eid",
  "s_kwcid", "ef_id",
  "_ga", "_gl", "_hsenc", "_hsmi", "__hstc", "__hsfp",
  "ref", "referrer",
  "click_id", "clickid",
  "trk", "trkCampaign", "trkInfo",
]);

export interface NormalizeOptions {
  stripQuery?: boolean;
  stripTracking?: boolean;
  sortParams?: boolean;
}

export function normalizeCrawlUrl(
  url: string,
  stripQueryOrOptions: boolean | NormalizeOptions = false
): string {
  const opts: NormalizeOptions =
    typeof stripQueryOrOptions === "boolean"
      ? { stripQuery: stripQueryOrOptions }
      : stripQueryOrOptions;

  try {
    const parsed = new URL(url);

    parsed.hash = "";

    parsed.hostname = parsed.hostname.toLowerCase();
    parsed.protocol = parsed.protocol.toLowerCase();

    if (
      (parsed.protocol === "http:" && parsed.port === "80") ||
      (parsed.protocol === "https:" && parsed.port === "443")
    ) {
      parsed.port = "";
    }

    let pathname = parsed.pathname;
    if (pathname.endsWith("/") && pathname.length > 1) {
      pathname = pathname.slice(0, -1);
    }
    pathname = pathname.replace(/\/+/g, "/");
    parsed.pathname = pathname;

    if (opts.stripQuery) {
      parsed.search = "";
    } else {
      if (opts.stripTracking !== false) {
        const params = new URLSearchParams(parsed.search);
        for (const key of Array.from(params.keys())) {
          if (TRACKING_PARAMS.has(key.toLowerCase())) {
            params.delete(key);
          }
        }
        parsed.search = params.toString();
      }

      if (opts.sortParams) {
        const params = new URLSearchParams(parsed.search);
        const sorted = new URLSearchParams();
        Array.from(params.keys())
          .sort()
          .forEach((key) => {
            const val = params.get(key);
            if (val !== null) sorted.set(key, val);
          });
        parsed.search = sorted.toString();
      }
    }

    return parsed.toString();
  } catch {
    return url;
  }
}

export function urlsMatch(
  a: string,
  b: string,
  stripQueryOrOptions: boolean | NormalizeOptions = false
): boolean {
  return (
    normalizeCrawlUrl(a, stripQueryOrOptions) ===
    normalizeCrawlUrl(b, stripQueryOrOptions)
  );
}

export function stripFragment(url: string): string {
  try {
    const parsed = new URL(url);
    parsed.hash = "";
    return parsed.toString();
  } catch {
    return url;
  }
}

export function extractDomainFromUrl(url: string): string {
  try {
    return new URL(url).hostname.toLowerCase();
  } catch {
    return "";
  }
}
