import type { BuilderFamilyType } from "../../types/builder-family";

export type SnapshotSource = "debugger-network" | "page-bridge";

export type RelevanceTag =
  | "likely-save"
  | "likely-load"
  | "likely-asset"
  | "likely-noise"
  | "unknown";

export type StructuredJsonType =
  | "none"
  | "json"
  | "structured-json"
  | "possible-builder-schema";

export type TargetKind = "FRAME" | "IFRAME" | "WORKER" | "SERVICE_WORKER" | "OTHER";

export interface PayloadSnapshot {
  id: string;
  timestamp: string;
  tabUrl: string;
  builderFamily: BuilderFamilyType;
  requestUrl: string;
  method: string;
  statusCode: number | null;
  payloadSize: number;
  looksLikeStructure: boolean;
  rawBody: string;
  contentType: string;
  label?: string;
  source?: SnapshotSource;
  requestHeaders?: Record<string, string>;
  responseHeaders?: Record<string, string>;
  requestBodyText?: string;
  relevanceScore?: number;
  tags?: RelevanceTag[];
  nearSaveMark?: boolean;
  // ── Multi-target fields ─────────────────────────────────────────────────────
  targetKind?: TargetKind;   // FRAME | IFRAME | WORKER | SERVICE_WORKER
  targetId?: string;         // CDP targetId for sub-targets
  targetUrl?: string;        // URL of the target that made the request
  // ── Schema classification ─────────────────────────────────────────────────
  schemaTag?: "PAGE_SCHEMA" | "FUNNEL_SCHEMA" | "SAVE_EVENT";
  pageId?:    string;        // extracted from URL e.g. /funnels/page/{pageId}
  funnelId?:  string;        // extracted from URL e.g. /funnels/funnel/fetch/{funnelId}
}

export interface SnapshotDiffResult {
  snapshotAId: string;
  snapshotBId: string;
  addedKeys: string[];
  removedKeys: string[];
  changedKeys: string[];
  unchangedKeys: string[];
  parseError: string | null;
}

