export type DiagnosticSeverity = "info" | "warning" | "error";

export interface DiagnosticEntry {
  severity: DiagnosticSeverity;
  code: string;
  message: string;
  context?: string;
  timestamp: string;
}

export interface DiagnosticsReport {
  entries: DiagnosticEntry[];
  summary: {
    totalInfo: number;
    totalWarnings: number;
    totalErrors: number;
  };
  generatedAt: string;
}

export function createDiagnosticsReport(
  entries: DiagnosticEntry[]
): DiagnosticsReport {
  return {
    entries,
    summary: {
      totalInfo: entries.filter((e) => e.severity === "info").length,
      totalWarnings: entries.filter((e) => e.severity === "warning").length,
      totalErrors: entries.filter((e) => e.severity === "error").length,
    },
    generatedAt: new Date().toISOString(),
  };
}

export function createDiagnosticEntry(
  severity: DiagnosticSeverity,
  code: string,
  message: string,
  context?: string
): DiagnosticEntry {
  return {
    severity,
    code,
    message,
    context,
    timestamp: new Date().toISOString(),
  };
}
