import { handleMessage, updateHeaderBuffer } from "./message-router";
import { removeTabContext } from "./tab-state";
import { registerInspectorPort } from "./inspector-ports";
import { handleDebuggerEvent, detachDebugger } from "./debugger-network";
import { logger } from "../core/logger";
import { updateRealTab } from "./real-tab-tracker";

logger.info("service-worker", "CloneLevel service worker started");

chrome.runtime.onMessage.addListener((message, sender, sendResponse) => {
  const keepOpen = handleMessage(message, sender, sendResponse);
  return keepOpen;
});

chrome.runtime.onConnect.addListener((port) => {
  if (port.name === "cl-inspector") {
    registerInspectorPort(port);
    logger.info("service-worker", "Inspector panel connected");
  }
});

// ── chrome.debugger events ────────────────────────────────────────────────
chrome.debugger.onEvent.addListener((source, method, params) => {
  handleDebuggerEvent(source, method, params).catch((err) => {
    logger.warn("service-worker", `debugger event error (${method}): ${String(err)}`);
  });
});

// Auto-detach when the debugged tab closes or navigates away
chrome.debugger.onDetach.addListener((_source, reason) => {
  logger.info("service-worker", `Debugger detached: ${reason}`);
  detachDebugger().catch(() => {});
});

chrome.tabs.onRemoved.addListener((tabId) => {
  removeTabContext(tabId);
});

chrome.tabs.onUpdated.addListener((tabId, changeInfo, tab) => {
  if (changeInfo.status === "loading") {
    removeTabContext(tabId);
  }
  if (changeInfo.status === "complete" && tab.url) {
    updateRealTab(tab);
  }
});

// Track which real (non-extension) tab the user is on
chrome.tabs.onActivated.addListener(async (activeInfo) => {
  try {
    const tab = await chrome.tabs.get(activeInfo.tabId);
    updateRealTab(tab);
  } catch { /* tab may have closed */ }
});

chrome.runtime.onInstalled.addListener((details) => {
  logger.info("service-worker", `CloneLevel installed: ${details.reason}`);
});

// ── webRequest header buffer ──────────────────────────────────────────────────
// Captures the full request headers Chrome sends for every HighLevel API call.
// This runs at the network layer, so it always sees auth tokens, session IDs,
// and CSRF headers — even when HL sets them via service workers or credential
// stores outside of the fetch() init object (which the MAIN-world JS watcher
// can't observe).
//
// These headers are buffered in-memory (message-router.ts _headerBuffer) and
// looked up during Learn Import Path finalize() to enrich watcher candidates
// that had empty requestHeaders.
//
// Note: in MV3, webRequest listeners are non-blocking (no "blocking" in extraInfoSpec).
// We only observe, never modify.
if (chrome.webRequest?.onBeforeSendHeaders) {
  chrome.webRequest.onBeforeSendHeaders.addListener(
    (details) => {
      if (details.requestHeaders && details.url && details.method) {
        updateHeaderBuffer(details.url, details.method, details.requestHeaders);
      }
    },
    {
      urls: [
        "*://backend.leadconnectorhq.com/*",
        "*://services.leadconnectorhq.com/*",
        "*://*.gohighlevel.com/*",
        "*://*.msgsndr.com/*",
        "*://*.app.ghl.io/*",
      ],
    },
    ["requestHeaders"],
  );
  logger.info("service-worker", "webRequest.onBeforeSendHeaders registered for HL domains");
} else {
  logger.warn("service-worker", "webRequest.onBeforeSendHeaders not available — header buffer disabled");
}
