import { RelationshipType, PageTypeHint } from "../schema/funnel-map";
import { containsAny, normalizeText } from "../normalize-text";

export interface DetectedRelationship {
  type: RelationshipType;
  confidence: number;
}

const PRIMARY_CTA_TEXT = [
  "buy now", "get started", "get access", "sign up", "join", "enroll",
  "start", "order now", "yes", "add to cart", "i want this",
  "get it now", "claim", "grab", "unlock", "try free", "purchase",
  "register now", "subscribe now", "start free", "start trial",
  "begin now", "take action", "let's go", "go now", "proceed",
];

const CHECKOUT_CTA_TEXT = [
  "checkout", "complete order", "place order", "pay now",
  "submit payment", "complete purchase", "finalize order", "buy",
];

const BOOKING_CTA_TEXT = [
  "book now", "schedule", "reserve", "book a call", "book a demo",
  "pick a time", "book appointment", "schedule a call", "choose a slot",
  "confirm booking", "request consultation",
];

const UPSELL_CTA_TEXT = [
  "yes, add this", "upgrade", "add to order", "yes! give me",
  "add this now", "one click add", "yes upgrade", "i want this too",
  "include this", "add to my order", "yes, upgrade me",
];

const DOWNSELL_CTA_TEXT = [
  "no thanks", "skip", "decline", "no, i don't want",
  "maybe later", "continue without", "not interested", "pass",
  "skip this offer", "i'll pass",
];

const SECONDARY_TEXT = [
  "learn more", "read more", "view", "details", "see", "explore",
  "find out", "discover", "more info", "about", "features",
  "how it works", "faq",
];

const NAV_TEXT = [
  "home", "about", "contact", "blog", "resources", "support",
  "terms", "privacy", "legal", "sitemap", "help",
];

const CHECKOUT_URL_SIGNALS = ["checkout", "order", "payment", "billing", "cart", "purchase"];
const UPSELL_URL_SIGNALS = ["upsell", "oto", "upgrade", "one-time-offer", "bump", "special"];
const DOWNSELL_URL_SIGNALS = ["downsell", "downgrade", "last-chance"];
const THANKYOU_URL_SIGNALS = ["thank", "thanks", "thankyou", "success", "welcome"];
const BOOKING_URL_SIGNALS = ["book", "schedule", "calendar", "appointment", "consult", "demo"];
const CONFIRMATION_URL_SIGNALS = ["confirmation", "confirmed", "receipt", "verify"];

export function detectRelationship(
  linkText: string,
  sourceElement: string,
  targetUrl: string,
  targetPageType?: PageTypeHint,
  targetHasForm?: boolean,
  targetButtonTexts?: string[]
): DetectedRelationship {
  const text = normalizeText(linkText);
  const url = targetUrl.toLowerCase();

  let best: DetectedRelationship = { type: "unknown", confidence: 0.2 };

  function candidate(type: RelationshipType, confidence: number) {
    if (confidence > best.confidence) {
      best = { type, confidence: Math.min(confidence, 1) };
    }
  }

  if (sourceElement === "a.cta" && containsAny(text, PRIMARY_CTA_TEXT)) {
    candidate("primary-cta", 0.9);
  } else if (containsAny(text, PRIMARY_CTA_TEXT)) {
    candidate("primary-cta", 0.75);
  }

  if (containsAny(text, CHECKOUT_CTA_TEXT) || containsAny(url, CHECKOUT_URL_SIGNALS)) {
    const base = containsAny(text, CHECKOUT_CTA_TEXT) ? 0.7 : 0.5;
    const boost = containsAny(url, CHECKOUT_URL_SIGNALS) ? 0.15 : 0;
    const typeBoost = targetPageType === "checkout" ? 0.15 : 0;
    candidate("checkout-next", base + boost + typeBoost);
  }

  if (containsAny(text, UPSELL_CTA_TEXT) || containsAny(url, UPSELL_URL_SIGNALS)) {
    const base = containsAny(text, UPSELL_CTA_TEXT) ? 0.7 : 0.5;
    const boost = containsAny(url, UPSELL_URL_SIGNALS) ? 0.15 : 0;
    const typeBoost = targetPageType === "upsell" ? 0.15 : 0;
    candidate("upsell-next", base + boost + typeBoost);
  }

  if (containsAny(text, DOWNSELL_CTA_TEXT) || containsAny(url, DOWNSELL_URL_SIGNALS)) {
    const base = containsAny(text, DOWNSELL_CTA_TEXT) ? 0.7 : 0.5;
    const boost = containsAny(url, DOWNSELL_URL_SIGNALS) ? 0.15 : 0;
    const typeBoost = targetPageType === "downsell" ? 0.15 : 0;
    candidate("downsell-next", base + boost + typeBoost);
  }

  if (containsAny(url, THANKYOU_URL_SIGNALS)) {
    const typeBoost = targetPageType === "thank-you" ? 0.15 : 0;
    candidate("thank-you-next", 0.6 + typeBoost);
  }

  if (containsAny(text, BOOKING_CTA_TEXT) || containsAny(url, BOOKING_URL_SIGNALS)) {
    const base = containsAny(text, BOOKING_CTA_TEXT) ? 0.7 : 0.5;
    const boost = containsAny(url, BOOKING_URL_SIGNALS) ? 0.15 : 0;
    const typeBoost = targetPageType === "booking" ? 0.15 : 0;
    candidate("booking-next", base + boost + typeBoost);
  }

  if (containsAny(url, CONFIRMATION_URL_SIGNALS)) {
    const typeBoost = targetPageType === "confirmation" ? 0.15 : 0;
    candidate("confirmation-next", 0.6 + typeBoost);
  }

  if (sourceElement === "form") {
    if (best.confidence < 0.6) {
      candidate("form-action", 0.65);
    }
  }

  if (containsAny(text, SECONDARY_TEXT)) {
    if (best.confidence < 0.4) {
      candidate("secondary-link", 0.45);
    }
  }

  if (containsAny(text, NAV_TEXT)) {
    if (best.confidence < 0.35) {
      candidate("navigation", 0.35);
    }
  }

  return best;
}
