import { addSnapshot } from "../storage/inspector-repo";
import { looksLikePageStructure, scoreRelevance } from "../core/inspector/payload-schema";
import type { PayloadSnapshot, TargetKind } from "../core/inspector/payload-schema";
import { classifyAndStore, classifyUrl } from "./schema-store";
import { classifyForImport } from "./import-store";
import { classifyAndStoreGlobal, tryExtractThemeFromAnyResponse } from "./global-store";

// ── Storage keys ──────────────────────────────────────────────────────────────
const SAVE_MARK_KEY      = "clonelevel_save_mark_ts";
const DEBUGGER_STATUS_KEY = "clonelevel_debugger_status";

// ── In-memory state ───────────────────────────────────────────────────────────

let _attachedTabId:    number | null = null;
let _networkEnabled:   boolean       = false;
let _autoAttachEnabled: boolean      = false;

interface AttachedTarget {
  targetId: string;
  kind: TargetKind;
  url: string;
  parentTabId: number;
}

/** Map from CDP targetId → metadata for sub-targets we directly attached to */
const _targetMap = new Map<string, AttachedTarget>();

interface PendingRequest {
  url: string;
  method: string;
  requestHeaders: Record<string, string>;
  requestBodyText?: string;
  timestamp: string;
  tabUrl: string;
  targetKind: TargetKind;
  targetId?: string;
  targetUrl?: string;
  /** The debuggee to use for Network.getResponseBody */
  debuggee: chrome.debugger.Debuggee;
}

/**
 * Keyed by `${sourceKey}:${requestId}`.
 * sourceKey = "tab:{tabId}" for the main frame
 *           = "tgt:{targetId}" for sub-targets
 */
const pendingRequests = new Map<string, PendingRequest>();

// ── Helpers ───────────────────────────────────────────────────────────────────

function cdpKind(type: string): TargetKind {
  const t = (type ?? "").toLowerCase();
  if (t === "page")           return "FRAME";
  if (t === "iframe")         return "IFRAME";
  if (t === "worker")         return "WORKER";
  if (t === "shared_worker")  return "WORKER";
  if (t === "service_worker") return "SERVICE_WORKER";
  return "OTHER";
}

function sourceKey(source: chrome.debugger.Debuggee): string {
  if (source.targetId) return `tgt:${source.targetId}`;
  if (source.tabId)    return `tab:${source.tabId}`;
  return "unknown";
}

function reqKey(src: chrome.debugger.Debuggee, requestId: string): string {
  return `${sourceKey(src)}:${requestId}`;
}

// ── Status persistence ────────────────────────────────────────────────────────

export type TargetCounts = Partial<Record<TargetKind, number>>;

interface DebuggerStatusPayload {
  attached:          boolean;
  networkEnabled:    boolean;
  autoAttachEnabled: boolean;
  tabId:             number | null;
  tabUrl:            string;
  updatedAt:         string;
  targets:           TargetCounts;
  totalTargets:      number;
}

async function persistStatus(
  attached: boolean,
  tabId: number | null,
  tabUrl: string,
  targets: TargetCounts = {},
): Promise<void> {
  const payload: DebuggerStatusPayload = {
    attached,
    networkEnabled:    _networkEnabled,
    autoAttachEnabled: _autoAttachEnabled,
    tabId,
    tabUrl,
    updatedAt: new Date().toISOString(),
    targets,
    totalTargets: Object.values(targets).reduce((a, b) => a + (b ?? 0), 0),
  };
  await chrome.storage.local.set({ [DEBUGGER_STATUS_KEY]: payload });
}

function currentTargetCounts(): TargetCounts {
  const counts: TargetCounts = {};
  if (_attachedTabId !== null) counts["FRAME"] = (counts["FRAME"] ?? 0) + 1;
  for (const t of _targetMap.values()) {
    counts[t.kind] = (counts[t.kind] ?? 0) + 1;
  }
  return counts;
}

// ── Public status API ─────────────────────────────────────────────────────────

export function getAttachedTabId(): number | null { return _attachedTabId; }

export async function getSaveMarkTs(): Promise<number | null> {
  const res = await chrome.storage.local.get(SAVE_MARK_KEY);
  const v = res[SAVE_MARK_KEY];
  return typeof v === "number" ? v : null;
}

export async function setSaveMarkNow(): Promise<number> {
  const ts = Date.now();
  await chrome.storage.local.set({ [SAVE_MARK_KEY]: ts });
  return ts;
}

export async function clearSaveMark(): Promise<void> {
  await chrome.storage.local.remove(SAVE_MARK_KEY);
}

export async function getDebuggerStatus(): Promise<DebuggerStatusPayload> {
  const res = await chrome.storage.local.get(DEBUGGER_STATUS_KEY);
  return (
    res[DEBUGGER_STATUS_KEY] ?? {
      attached: false, networkEnabled: false, autoAttachEnabled: false,
      tabId: null, tabUrl: "", updatedAt: "", targets: {}, totalTargets: 0,
    }
  );
}

// ── Sub-target attach ─────────────────────────────────────────────────────────

async function attachToSubTarget(
  targetId: string,
  targetType: string,
  targetUrl: string,
  parentTabId: number,
): Promise<void> {
  if (_targetMap.has(targetId)) return;

  const kind    = cdpKind(targetType);
  const debuggee: chrome.debugger.Debuggee = { targetId };

  try { await chrome.debugger.attach(debuggee, "1.3"); } catch {
    // May already be attached by Chrome — that's fine
  }

  try {
    await chrome.debugger.sendCommand(debuggee, "Network.enable", {
      maxTotalBufferSize: 10_000_000,
      maxResourceBufferSize: 5_000_000,
    });
  } catch (err) {
    console.warn(`[CL] Failed to enable Network for sub-target ${targetId}:`, err);
    return; // Don't register this target if Network.enable fails
  }

  _targetMap.set(targetId, { targetId, kind, url: targetUrl, parentTabId });
  console.info(`[CL] Sub-target attached: ${kind} ${targetUrl}`);

  await persistStatus(true, parentTabId, "", currentTargetCounts());
}

// ── Attach / Detach ───────────────────────────────────────────────────────────

export async function attachDebugger(
  tabId: number,
): Promise<{ ok: boolean; error?: string }> {
  // ── Detach previous session if it was a different tab ───────────────────────
  if (_attachedTabId !== null && _attachedTabId !== tabId) {
    await detachDebugger();
  }

  // ── Step 1: Attach to the tab ────────────────────────────────────────────────
  try {
    await chrome.debugger.attach({ tabId }, "1.3");
  } catch (err) {
    // Might already be attached — check
    const already = await verifyAttachment();
    if (!already) {
      await persistStatus(false, null, "");
      return { ok: false, error: `attach failed: ${String(err)}` };
    }
    // Already attached to this tab from a previous SW run — continue
  }

  // ── Step 2: Enable Network (MUST succeed — this is the core capability) ──────
  try {
    await chrome.debugger.sendCommand({ tabId }, "Network.enable", {
      maxTotalBufferSize: 10_000_000,
      maxResourceBufferSize: 5_000_000,
    });
    _networkEnabled = true;
  } catch (err) {
    // Network.enable failed — no point continuing
    try { await chrome.debugger.detach({ tabId }); } catch {}
    _networkEnabled = false;
    _autoAttachEnabled = false;
    await persistStatus(false, null, "");
    return { ok: false, error: `Network.enable failed: ${String(err)}` };
  }

  // ── SUCCESS: Network is live. Record state immediately ───────────────────────
  _attachedTabId = tabId;
  let tabUrl = "";
  try { const t = await chrome.tabs.get(tabId); tabUrl = t.url ?? ""; } catch {}
  await persistStatus(true, tabId, tabUrl, { FRAME: 1 });

  // ── Step 3: Try to enable Target domain (optional — -32601 is OK) ────────────
  try {
    await chrome.debugger.sendCommand({ tabId }, "Target.enable", {});
  } catch (err) {
    console.warn("[CL] Target.enable not supported — multi-target capture unavailable:", String(err));
  }

  // ── Step 4: Try auto-attach for iframes/workers (optional) ───────────────────
  try {
    await chrome.debugger.sendCommand({ tabId }, "Target.setAutoAttach", {
      autoAttach: true,
      waitForDebuggerOnStart: false,
      flatten: true,
    });
    _autoAttachEnabled = true;
    console.info("[CL] Target.setAutoAttach enabled — capturing all sub-targets");
  } catch (err) {
    _autoAttachEnabled = false;
    console.warn("[CL] Target.setAutoAttach not supported (-32601 is expected in some Chrome versions) — continuing with tab-only capture:", String(err));
  }

  // Persist final status after optional steps
  await persistStatus(true, tabId, tabUrl, currentTargetCounts());

  // ── Step 5: Scan already-open sub-targets ────────────────────────────────────
  await _scanExistingTargets(tabId);

  return { ok: true };
}

/** Enumerate chrome.debugger targets, attach to any unattached iframes/workers */
async function _scanExistingTargets(parentTabId: number): Promise<void> {
  if (!_autoAttachEnabled) return; // Only scan if auto-attach worked
  try {
    const targets = await chrome.debugger.getTargets();
    for (const t of targets) {
      if (!t.targetId || _targetMap.has(t.targetId)) continue;
      if (t.attached) continue;
      const type = (t.type ?? "").toLowerCase();
      if (type === "page" && t.tabId === parentTabId) continue;
      if (type === "browser" || type === "webview" || type === "page") continue;
      if (["iframe","worker","shared_worker","service_worker"].includes(type)) {
        await attachToSubTarget(t.targetId, t.type ?? "other", t.url ?? "", parentTabId);
      }
    }
  } catch (err) {
    console.warn("[CL] Error scanning existing targets:", err);
  }
}

async function _doDetachTarget(targetId: string): Promise<void> {
  try { await chrome.debugger.detach({ targetId }); } catch {}
}

export async function detachDebugger(): Promise<{ ok: boolean; error?: string }> {
  const tabId = _attachedTabId;
  _attachedTabId     = null;
  _networkEnabled    = false;
  _autoAttachEnabled = false;

  for (const [targetId] of _targetMap) {
    await _doDetachTarget(targetId);
  }
  _targetMap.clear();
  pendingRequests.clear();
  await persistStatus(false, null, "");

  if (tabId !== null) {
    try { await chrome.debugger.detach({ tabId }); } catch {}
  }
  return { ok: true };
}

export async function verifyAttachment(): Promise<boolean> {
  if (_attachedTabId === null) return false;
  try {
    const targets = await chrome.debugger.getTargets();
    return targets.some((t) => t.tabId === _attachedTabId && t.attached);
  } catch { return false; }
}

// ── Event handler (called from service-worker.ts) ─────────────────────────────

export async function handleDebuggerEvent(
  source: chrome.debugger.Debuggee,
  method: string,
  params: unknown,
): Promise<void> {
  // Route only events from our tab or registered sub-targets
  const isOurTab    = source.tabId === _attachedTabId;
  const isSubTarget = source.targetId ? _targetMap.has(source.targetId) : false;
  if (!isOurTab && !isSubTarget) return;

  const tabId = _attachedTabId!;

  // ── Target.attachedToTarget ──────────────────────────────────────────────────
  if (method === "Target.attachedToTarget" && isOurTab) {
    const p = params as {
      sessionId: string;
      targetInfo: { targetId: string; type: string; url: string };
      waitingForDebugger: boolean;
    };
    await attachToSubTarget(p.targetInfo.targetId, p.targetInfo.type, p.targetInfo.url, tabId);
    return;
  }

  // ── Target.detachedFromTarget ────────────────────────────────────────────────
  if (method === "Target.detachedFromTarget" && isOurTab) {
    const p = params as { sessionId: string; targetId?: string };
    if (p.targetId) {
      _targetMap.delete(p.targetId);
      await persistStatus(true, tabId, "", currentTargetCounts());
    }
    return;
  }

  // ── Network.requestWillBeSent ────────────────────────────────────────────────
  if (method === "Network.requestWillBeSent") {
    const p = params as {
      requestId: string;
      request: { url: string; method: string; headers: Record<string, string>; postData?: string };
    };

    if (!p.request.url.startsWith("http")) return;

    let tabUrl = "";
    try { const t = await chrome.tabs.get(tabId); tabUrl = t.url ?? ""; } catch {}

    let targetKind: TargetKind = "FRAME";
    let targetIdStr: string | undefined;
    let targetUrl: string | undefined;

    if (source.targetId && _targetMap.has(source.targetId)) {
      const t = _targetMap.get(source.targetId)!;
      targetKind  = t.kind;
      targetIdStr = t.targetId;
      targetUrl   = t.url;
    }

    pendingRequests.set(reqKey(source, p.requestId), {
      url:            p.request.url,
      method:         p.request.method,
      requestHeaders: p.request.headers ?? {},
      requestBodyText: p.request.postData,
      timestamp:      new Date().toISOString(),
      tabUrl,
      targetKind,
      targetId:  targetIdStr,
      targetUrl,
      debuggee:  source,
    });
    return;
  }

  // ── Network.responseReceived ─────────────────────────────────────────────────
  if (method === "Network.responseReceived") {
    const p = params as {
      requestId: string;
      response: { url: string; status: number; headers: Record<string, string>; mimeType: string };
    };

    const key     = reqKey(source, p.requestId);
    const pending = pendingRequests.get(key);
    if (!pending) return;

    let responseBody = "";
    try {
      const bodyRes = (await chrome.debugger.sendCommand(
        pending.debuggee, "Network.getResponseBody", { requestId: p.requestId },
      )) as { body: string; base64Encoded: boolean };
      responseBody = bodyRes.base64Encoded ? atob(bodyRes.body) : bodyRes.body;
    } catch {
      // No body available (image, redirect, binary) — that's fine
    }

    const snapshot = await buildSnapshot({
      pending, status: p.response.status,
      responseHeaders: p.response.headers ?? {},
      mimeType: p.response.mimeType ?? "",
      responseBody,
    });

    await addSnapshot(snapshot);
    // Classify and store to schema-store (PAGE_SCHEMA, FUNNEL_SCHEMA, SAVE_EVENT)
    await classifyAndStore(snapshot).catch(() => {});
    // Classify for import discovery (CREATE_CANDIDATE, UPDATE_CANDIDATE, etc.)
    await classifyForImport(snapshot).catch(() => {});
    // Classify for global store (GLOBAL_SECTION, THEME_SETTINGS, TEMPLATE)
    await classifyAndStoreGlobal(
      snapshot.id, snapshot.timestamp, snapshot.requestUrl,
      snapshot.method, snapshot.rawBody ?? "",
    ).catch(() => {});
    // Bonus: try to extract theme variables from any HL endpoint response
    await tryExtractThemeFromAnyResponse(
      snapshot.id, snapshot.timestamp, snapshot.requestUrl, snapshot.rawBody ?? "",
    ).catch(() => {});
    pendingRequests.delete(key);
    return;
  }

  // ── Network.loadingFailed / loadingFinished ──────────────────────────────────
  if (method === "Network.loadingFailed" || method === "Network.loadingFinished") {
    const key = reqKey(source, (params as { requestId: string }).requestId);
    pendingRequests.delete(key);
  }
}

// ── Snapshot builder ──────────────────────────────────────────────────────────

async function buildSnapshot(opts: {
  pending: PendingRequest;
  status: number;
  responseHeaders: Record<string, string>;
  mimeType: string;
  responseBody: string;
}): Promise<PayloadSnapshot> {
  const { pending, status, responseHeaders, mimeType, responseBody } = opts;

  const { score, tags } = scoreRelevance(
    pending.url, pending.method, responseBody, mimeType,
  );

  const saveMarkTs = await getSaveMarkTs();
  const reqTime    = new Date(pending.timestamp).getTime();
  const nearSaveMark =
    saveMarkTs !== null && reqTime >= saveMarkTs && reqTime <= saveMarkTs + 30_000;

  const { tag: schemaTag, pageId, funnelId } = classifyUrl(pending.url);

  return {
    id: crypto.randomUUID(),
    timestamp:          pending.timestamp,
    tabUrl:             pending.tabUrl,
    builderFamily:      "unknown" as any,
    requestUrl:         pending.url,
    method:             pending.method,
    statusCode:         status,
    payloadSize:        responseBody.length,
    looksLikeStructure: looksLikePageStructure(responseBody),
    rawBody:            responseBody,
    contentType:        mimeType,
    source:             "debugger-network",
    requestHeaders:     pending.requestHeaders,
    responseHeaders,
    requestBodyText:    pending.requestBodyText,
    relevanceScore:     score,
    tags,
    nearSaveMark,
    targetKind: pending.targetKind,
    targetId:   pending.targetId,
    targetUrl:  pending.targetUrl,
    ...(schemaTag && { schemaTag: schemaTag as any }),
    ...(pageId    && { pageId }),
    ...(funnelId  && { funnelId }),
  };
}
