/**
 * builder-runtime-probe.ts
 *
 * Three self-contained functions injected into the HL builder's MAIN world via
 * chrome.scripting.executeScript({ world: "MAIN", func: ... }).
 *
 * CRITICAL: Each function must be ENTIRELY self-contained — no closures, no
 * references to outer-scope variables, no imports.  Chrome serialises the
 * function body and re-evaluates it in a separate JS context.
 *
 * Storage contract (all written to window.__cl_runtime):
 *   spyActive      boolean   — dispatch spy successfully wrapped
 *   storeType      string    — how the store was found
 *   storeKey       string|null — window property name (if found via global scan)
 *   _storeRef      any       — live reference to the Redux store object
 *   _origDispatch  fn        — original (un-wrapped) dispatch for safe re-dispatch
 *   dispatched     Array     — captured action log {type, payload, ts}
 *   apolloFound    boolean
 *   errors         string[]
 */

export interface RuntimeProbeResult {
  spyActive:   boolean;
  storeType:   string;
  storeKey:    string | null;
  apolloFound: boolean;
  errors:      string[];
}

export interface RuntimeCapture {
  type:    string;
  payload: string;  // JSON-serialised, capped at 3 KB
  ts:      number;
  score:   number;
}

export interface RuntimeCaptureResult {
  active:        boolean;
  storeFound:    boolean;
  storeType:     string;
  storeKey:      string | null;
  apolloFound:   boolean;
  dispatched:    RuntimeCapture[];  // scored, top 30
  allDispatched: RuntimeCapture[];  // last 50 raw
  totalCaptured: number;
  statePreview:  string | null;     // JSON of current store state, capped 4 KB
  errors:        string[];
}

export interface DispatchInsertResult {
  ok:         boolean;
  actionType?: string;
  error?:     string;
  results:    string[];
}

// ── 1. Probe ──────────────────────────────────────────────────────────────────
// Discovers the Redux store via four escalating methods, then wraps dispatch
// so every action dispatched while the spy is active is recorded.
// Returns a short diagnostic string.
export function _builderRuntimeProbeFunc(): string {
  const w = window as any;
  if (w.__cl_runtime?.spyActive) return "already_active";

  w.__cl_runtime = {
    spyActive:     false,
    storeType:     "none",
    storeKey:      null,
    _storeRef:     null,
    _origDispatch: null,
    dispatched:    [],
    apolloFound:   false,
    errors:        [] as string[],
  };

  let store: any = null;

  // ── Method 1: React DevTools Global Hook ──────────────────────────────────
  // React registers __REACT_DEVTOOLS_GLOBAL_HOOK__ on window.  The hook stores
  // the fiber renderer(s), each of which exposes the root fiber.  Walking the
  // fiber tree from the root finds the React-Redux <Provider> whose
  // memoizedProps.store IS the Redux store.
  try {
    const hook = (w as any).__REACT_DEVTOOLS_GLOBAL_HOOK__;
    if (hook) {
      function findStoreInFiber(fiber: any, depth: number): any {
        if (!fiber || depth > 150) return null;
        const mp = fiber.memoizedProps;
        if (mp) {
          if (mp.store?.dispatch && typeof mp.store.getState === "function") return mp.store;
          if (mp.value?.store?.dispatch) return mp.value.store;
          if (mp.value?.dispatch && typeof mp.value.getState === "function") return mp.value;
        }
        const ms = fiber.memoizedState;
        if (ms?.element?.props?.store?.dispatch) return ms.element.props.store;
        return findStoreInFiber(fiber.child, depth + 1) || findStoreInFiber(fiber.sibling, depth + 1);
      }

      // renderers is a Map<id, renderer>; each renderer exposes getFiberRoots()
      if (hook.renderers) {
        for (const [, renderer] of hook.renderers) {
          try {
            const roots: Set<any> = typeof renderer.getFiberRoots === "function"
              ? renderer.getFiberRoots()
              : new Set();
            for (const root of roots) {
              if (root?.current) {
                const s = findStoreInFiber(root.current, 0);
                if (s) { store = s; w.__cl_runtime.storeType = "devtools-fiber"; break; }
              }
            }
          } catch { /* renderer might be sealed */ }
          if (store) break;
        }
      }
      // Fallback: hook._roots (older React versions)
      if (!store && hook._roots) {
        for (const root of hook._roots) {
          if (root?.current) {
            const s = findStoreInFiber(root.current, 0);
            if (s) { store = s; w.__cl_runtime.storeType = "devtools-fiber-_roots"; break; }
          }
        }
      }
    }
  } catch (e) {
    w.__cl_runtime.errors.push("devtools:" + String(e).slice(0, 60));
  }

  // ── Method 2: Known window global names ────────────────────────────────────
  if (!store) {
    const STORE_KEYS = [
      "store", "__store", "__redux_store", "pageStore", "builderStore",
      "funnelStore", "appStore", "rootStore", "__builderStore", "__pageStore",
      "editorStore", "__editorStore", "__appStore", "__rootStore",
      "_store", "mainStore", "hlStore", "__hlStore",
    ];
    for (const k of STORE_KEYS) {
      try {
        const s = w[k];
        if (s?.dispatch && typeof s.dispatch === "function" && typeof s.getState === "function") {
          store = s;
          w.__cl_runtime.storeType = "window-global";
          w.__cl_runtime.storeKey  = k;
          break;
        }
      } catch { /* property access might throw */ }
    }
  }

  // ── Method 3: Full window property scan ────────────────────────────────────
  // Enumerate ALL window properties and look for Redux-like objects whose state
  // contains builder-relevant keys (sections, pages, funnel, editor, elements).
  if (!store) {
    try {
      const propNames = Object.getOwnPropertyNames(w).slice(0, 1000);
      for (const k of propNames) {
        if (/^(__cl_|on|webkit|moz|ms|css|SVG|HTML|document|window|navigator|screen|history|location|performance|crypto|indexedDB|caches|console|Math|JSON|Array|Object|Function|String|Number|Boolean|Symbol|BigInt|Promise|Set|Map|WeakSet|WeakMap|Error|RegExp|Date|Intl|Reflect|Proxy|globalThis|undefined|NaN|Infinity)/.test(k)) continue;
        try {
          const v = w[k];
          if (!v || typeof v !== "object" || Array.isArray(v)) continue;
          if (typeof v.dispatch !== "function" || typeof v.getState !== "function") continue;
          try {
            const st = v.getState();
            if (st && typeof st === "object") {
              const stKeys = Object.keys(st as object).join(",").toLowerCase();
              if (/section|page|funnel|builder|editor|element|step|row|block/.test(stKeys)) {
                store = v;
                w.__cl_runtime.storeType = "window-scan";
                w.__cl_runtime.storeKey  = k;
                break;
              }
            }
          } catch { /* getState might throw */ }
        } catch { /* property access might throw */ }
      }
    } catch (e) {
      w.__cl_runtime.errors.push("scan:" + String(e).slice(0, 60));
    }
  }

  // ── Method 4: iframe contentWindow scan ────────────────────────────────────
  // HL builder often runs inside a cross-origin iframe on leadconnectorhq.com.
  // We can access same-origin iframes and check their window globals.
  if (!store) {
    try {
      const iframes = document.querySelectorAll("iframe");
      for (let i = 0; i < Math.min(iframes.length, 10) && !store; i++) {
        try {
          const fw = (iframes[i] as HTMLIFrameElement).contentWindow as any;
          if (!fw) continue;
          for (const k of ["store", "__store", "__redux_store", "builderStore", "pageStore", "editorStore", "appStore"]) {
            try {
              const s = fw[k];
              if (s?.dispatch && typeof s.getState === "function") {
                store = s;
                w.__cl_runtime.storeType = "iframe-window";
                w.__cl_runtime.storeKey  = `iframe[${i}].${k}`;
                break;
              }
            } catch { /* cross-origin or sealed */ }
          }
        } catch { /* cross-origin — expected for HL iframes */ }
      }
    } catch { /* */ }
  }

  // ── Apollo / GraphQL detection ─────────────────────────────────────────────
  try {
    if (w.__APOLLO_CLIENT__ || w.apolloClient || w.__APOLLO_STATE__ || w.__APOLLO__) {
      w.__cl_runtime.apolloFound = true;
    }
  } catch { /* */ }

  // ── Wrap dispatch to spy on every action ───────────────────────────────────
  if (store) {
    try {
      w.__cl_runtime._storeRef     = store;
      w.__cl_runtime._origDispatch = store.dispatch;

      const rt = w.__cl_runtime;
      const origDispatch = store.dispatch;

      store.dispatch = function clSpyDispatch(action: any) {
        try {
          if (action && typeof action === "object") {
            rt.dispatched.push({
              type:    String(action.type ?? "@@unknown"),
              payload: JSON.stringify(action).slice(0, 3000),
              ts:      Date.now(),
            });
            // Rolling window — keep last 300 actions
            if (rt.dispatched.length > 300) rt.dispatched.shift();
          }
        } catch { /* */ }
        return origDispatch.call(this, action);
      };

      w.__cl_runtime.spyActive = true;
    } catch (e) {
      w.__cl_runtime.errors.push("spy:" + String(e).slice(0, 60));
    }
  }

  const rt = w.__cl_runtime;
  if (rt.spyActive)    return `store:${rt.storeType}:key=${rt.storeKey ?? "?"}:spy=ACTIVE`;
  if (rt._storeRef)    return `store:${rt.storeType}:spy=WRAP_FAILED`;
  return `no_store:apollo=${rt.apolloFound}:errors=${rt.errors.length}`;
}

// ── 2. Pull Captures ──────────────────────────────────────────────────────────
// Reads window.__cl_runtime.dispatched, scores each action for relevance to
// "add section" operations, and returns the top candidates plus raw state.
export function _pullRuntimeCapturesFunc(): RuntimeCaptureResult {
  const w  = window as any;
  const rt = w.__cl_runtime;

  const empty: RuntimeCaptureResult = {
    active: false, storeFound: false, storeType: "none", storeKey: null,
    apolloFound: false, dispatched: [], allDispatched: [],
    totalCaptured: 0, statePreview: null, errors: [],
  };

  if (!rt) return empty;

  const SECTION_ADD  = ["add", "insert", "create", "append", "paste", "import",
                         "duplicate", "copy", "clone", "template", "apply", "inject", "load"];
  const SECTION_NOUN = ["section", "element", "row", "block", "component",
                         "widget", "module", "node", "step", "column"];
  const REMOVE_KW    = ["delete", "remove", "destroy", "clear", "reset", "undo", "pop", "splice"];

  function scoreAction(type: string): number {
    const t = type.toLowerCase().replace(/[/_\-\.]/g, " ");
    const hasRemove = REMOVE_KW.some((k) => t.includes(k));
    if (hasRemove) return -10;
    const addHits  = SECTION_ADD.filter((k)  => t.includes(k)).length;
    const nounHits = SECTION_NOUN.filter((k) => t.includes(k)).length;
    return addHits * 8 + nounHits * 12;
  }

  const allDispatched: RuntimeCapture[] = (rt.dispatched ?? []).slice(-50).map((d: any) => ({
    type:    d.type ?? "unknown",
    payload: d.payload ?? "",
    ts:      d.ts ?? 0,
    score:   scoreAction(d.type ?? ""),
  }));

  const scored = [...allDispatched]
    .filter((d) => d.score > 0)
    .sort((a, b) => b.score - a.score || b.ts - a.ts)
    .slice(0, 30);

  let statePreview: string | null = null;
  try {
    if (rt._storeRef?.getState) {
      statePreview = JSON.stringify(rt._storeRef.getState()).slice(0, 4000);
    }
  } catch { /* */ }

  return {
    active:        rt.spyActive ?? false,
    storeFound:    !!rt._storeRef,
    storeType:     rt.storeType ?? "none",
    storeKey:      rt.storeKey  ?? null,
    apolloFound:   rt.apolloFound ?? false,
    dispatched:    scored,
    allDispatched,
    totalCaptured: (rt.dispatched ?? []).length,
    statePreview,
    errors:        rt.errors ?? [],
  };
}

// ── 3. State-Introspect & Test Insert ─────────────────────────────────────────
// Reads the live Redux state to discover the exact section schema HL uses,
// clones the first section, then tries 15+ action types while validating
// success by re-reading state after each dispatch.
// Returns a JSON string (must serialise — this runs via executeScript).
export function _insertTestSectionFunc(): string {
  const w  = window as any;
  const rt = w.__cl_runtime;

  if (!rt?._storeRef) {
    return JSON.stringify({ ok: false, error: "no_store_ref — run probe first", stateKeys: [] });
  }

  let state: any;
  try { state = rt._storeRef.getState(); }
  catch (e) { return JSON.stringify({ ok: false, error: "getState_threw: " + String(e).slice(0, 80) }); }

  // Recursive search for a sections-like array in the state tree
  function findSectionsInState(obj: any, depth: number, path: string): { path: string; arr: any[] } | null {
    if (!obj || typeof obj !== "object" || depth > 7) return null;
    if (Array.isArray(obj)) {
      if (obj.length > 0 && typeof obj[0] === "object" &&
          (obj[0].rows != null || obj[0].elements != null || obj[0].type === "section" || obj[0].type === "row")) {
        return { path, arr: obj };
      }
      return null;
    }
    for (const k of ["sections", "rows", "elements", "blocks", "steps", "content", "nodes"]) {
      if (Array.isArray(obj[k]) && obj[k].length > 0 && typeof obj[k][0] === "object") {
        return { path: path + "." + k, arr: obj[k] };
      }
    }
    for (const k of Object.keys(obj)) {
      if (typeof obj[k] === "object") {
        const r = findSectionsInState(obj[k], depth + 1, path + "." + k);
        if (r) return r;
      }
    }
    return null;
  }

  const found = findSectionsInState(state, 0, "state");
  if (!found) {
    return JSON.stringify({ ok: false, error: "no_sections_array_in_state", stateKeys: Object.keys(state ?? {}) });
  }

  // Clone the first section and modify it minimally
  let testSection: any;
  try {
    testSection = JSON.parse(JSON.stringify(found.arr[0]));
    const newId = "cl_test_" + Date.now();
    testSection.id    = newId;
    testSection.label = "CloneLevel Test Insert";
    // Attempt to set visible text in common element shapes
    function patchText(node: any, remaining: number): void {
      if (!node || typeof node !== "object" || remaining <= 0) return;
      if (node.content != null && typeof node.content === "string") { node.content = "CloneLevel Test Insert"; return; }
      if (node.text    != null && typeof node.text    === "string") { node.text    = "CloneLevel Test Insert"; return; }
      if (node.value   != null && typeof node.value   === "string") { node.value   = "CloneLevel Test Insert"; return; }
      for (const k of ["children", "elements", "rows", "cols", "columns"]) {
        if (Array.isArray(node[k])) { for (const child of node[k]) patchText(child, remaining - 1); }
      }
    }
    patchText(testSection, 4);
  } catch (e) {
    testSection = { id: "cl_test_" + Date.now(), type: "section", label: "CloneLevel Test Insert", rows: [] };
  }

  const countBefore = found.arr.length;

  const dispatchFn = (a: any) =>
    typeof rt._origDispatch === "function"
      ? rt._origDispatch.call(rt._storeRef, a)
      : rt._storeRef.dispatch(a);

  // Try captured action types first (scored ones), then hardcoded candidates
  const capturedTypes: string[] = (rt.dispatched ?? [])
    .filter((d: any) => {
      const t = (d.type ?? "").toLowerCase().replace(/[/_\-\.]/g, " ");
      return ["add", "insert", "paste", "import", "create", "append"].some((v) => t.includes(v)) &&
             ["section", "element", "row", "block", "component"].some((v) => t.includes(v));
    })
    .map((d: any) => d.type as string);

  const STATIC_TYPES = [
    "ADD_SECTION", "INSERT_SECTION", "PASTE_SECTION", "IMPORT_SECTION",
    "CREATE_SECTION", "APPEND_SECTION",
    "builder/ADD_SECTION", "builder/INSERT_SECTION", "builder/PASTE_SECTION",
    "page/ADD_SECTION", "page/INSERT_SECTION",
    "funnel/ADD_SECTION", "sections/add", "sections/insert",
    "SECTION_ADDED", "BUILDER_ADD_SECTION", "FUNNEL_ADD_SECTION",
  ];

  const allTypes = [...new Set([...capturedTypes, ...STATIC_TYPES])];
  const results: string[] = [];

  for (const actionType of allTypes) {
    try {
      dispatchFn({ type: actionType, section: testSection, payload: testSection,
                   sections: [testSection], data: testSection });
      // Validate: re-read state and check if sections array grew
      try {
        const newState  = rt._storeRef.getState();
        const newFound  = findSectionsInState(newState, 0, "state");
        if (newFound && newFound.arr.length > countBefore) {
          return JSON.stringify({
            ok: true, actionType, path: found.path,
            countBefore, countAfter: newFound.arr.length,
            results, fromCaptured: capturedTypes.includes(actionType),
          });
        }
      } catch { /* */ }
      results.push("dispatched:" + actionType);
    } catch (e) {
      results.push("err:" + actionType + ":" + String(e).slice(0, 40));
    }
  }

  return JSON.stringify({
    ok: false,
    error:          "no_action_type_changed_state",
    path:           found.path,
    countBefore,
    capturedTypes:  capturedTypes.slice(0, 8),
    tried:          allTypes.length,
    results:        results.slice(0, 15),
    templateShape:  Object.keys(found.arr[0] ?? {}).join(","),
  });
}

// ── 4. Dispatch Section Insert ────────────────────────────────────────────────
// Uses the store reference left by the probe to dispatch a section-add action
// with the exact action type observed during Learn Import Path.
// Uses _origDispatch to bypass the spy (avoids self-recording the paste action).
export function _dispatchSectionInsertFunc(
  actionType:       string,
  sectionsJson:     string,
  origPayloadJson:  string,
): DispatchInsertResult {
  const w  = window as any;
  const rt = w.__cl_runtime;

  if (!rt?._storeRef) {
    return { ok: false, error: "No store ref — run probe first or probe failed to find store.", results: [] };
  }

  const dispatchFn: ((a: any) => any) | null =
    (typeof rt._origDispatch === "function")
      ? (a: any) => rt._origDispatch.call(rt._storeRef, a)
      : (typeof rt._storeRef.dispatch === "function")
        ? (a: any) => rt._storeRef.dispatch(a)
        : null;

  if (!dispatchFn) {
    return { ok: false, error: "No dispatch function available on store", results: [] };
  }

  let ourSections: any[];
  let origPayload: any;

  try { ourSections = JSON.parse(sectionsJson); }
  catch { return { ok: false, error: "Could not parse sectionsJson", results: [] }; }

  try { origPayload = JSON.parse(origPayloadJson || "null"); }
  catch { origPayload = null; }

  const section = ourSections[0] ?? { id: `cl_${Date.now()}`, type: "section", rows: [] };
  const results: string[] = [];

  // Attempt matrix: try several payload shapes — HL might expect any of these.
  // We try the most specific (original payload merged) first, then progressively
  // simpler shapes.
  const attempts: any[] = [
    ...(origPayload ? [
      // Exact original payload with section data replaced
      { type: actionType, payload: { ...origPayload, ...section }, ...origPayload, ...section },
      { type: actionType, payload: { ...origPayload, section },    section },
      { type: actionType, payload: section },
    ] : []),
    // Generic shapes — HL builder action creators use various conventions
    { type: actionType, payload: section },
    { type: actionType, section, payload: { section } },
    { type: actionType, sections: ourSections, payload: { sections: ourSections } },
    { type: actionType, payload: ourSections },
    { type: actionType, data: section, payload: { data: section } },
    // Thunk-style: payload is the first section directly
    { type: actionType, ...section },
  ];

  for (const action of attempts) {
    try {
      dispatchFn(action);
      results.push(`dispatched:${actionType}:shape=${JSON.stringify(Object.keys(action))}`);
      return { ok: true, actionType, results };
    } catch (e) {
      results.push(`err:${String(e).slice(0, 80)}`);
    }
  }

  return { ok: false, error: `All ${attempts.length} dispatch attempts threw`, results };
}

// ── 5. React Fiber State Injection ────────────────────────────────────────────
// When Redux is absent, HL builder state lives in React component state.
// This function:
//   1. Detects the JS framework (React / Angular / Vue)
//   2. Finds all React fiber roots via DevTools hook + DOM scan
//   3. Walks the fiber tree for a component holding a sections-like array
//   4. Clones the first section and injects via setState (class) or
//      the hook updater dispatch (function components)
//   5. Returns a JSON string with full diagnostics
// Self-contained — no imports, no outer-scope references.
export function _fiberInjectTestFunc(): string {
  const w = window as any;

  // ── Framework detection — exhaustive ──────────────────────────────────────
  // Collects all evidence before making a framework determination.

  // Collect notable globals for diagnostics (skip known browser/DOM names)
  const SKIP_GLOBAL = /^(window|document|navigator|location|history|screen|performance|crypto|console|Math|JSON|Array|Object|Function|String|Number|Boolean|Symbol|Promise|Set|Map|Proxy|Reflect|globalThis|undefined|NaN|Infinity|on|webkit|moz|ms)/;
  const notableGlobals: string[] = [];
  try {
    for (const k of Object.getOwnPropertyNames(w).slice(0, 500)) {
      if (SKIP_GLOBAL.test(k)) continue;
      try { const v = (w as any)[k]; if (v !== null && v !== undefined) notableGlobals.push(k); } catch { /* */ }
    }
  } catch { /* */ }

  // React detection
  const hasReactHook   = !!w.__REACT_DEVTOOLS_GLOBAL_HOOK__;
  const hasReactGlobal = !!w.React;
  // Broad DOM fiber scan: check body, documentElement, then first 200 elements
  // Uses getOwnPropertyNames (catches non-enumerable) not Object.keys
  let reactFiberEl: Element | null = null;
  try {
    const primaries: (Element | Document)[] = [document.body, document.documentElement];
    for (const el of primaries) {
      if (!el) continue;
      if (Object.getOwnPropertyNames(el).some((k) =>
          k.startsWith("__reactFiber") || k.startsWith("__reactContainer") || k.startsWith("__reactInternals"))) {
        reactFiberEl = el as Element;
        break;
      }
    }
    if (!reactFiberEl) {
      const allEls = document.querySelectorAll("*");
      for (let i = 0; i < Math.min(allEls.length, 200) && !reactFiberEl; i++) {
        const el = allEls[i];
        if (Object.getOwnPropertyNames(el).some((k) =>
            k.startsWith("__reactFiber") || k.startsWith("__reactContainer") || k.startsWith("__reactInternals"))) {
          reactFiberEl = el;
        }
      }
    }
  } catch { /* */ }
  const hasReactDom = !!reactFiberEl;
  const hasReact    = hasReactHook || hasReactGlobal || hasReactDom;

  // Angular detection — standard + Ivy
  const hasAngularGlobal  = !!(w.ng || w.getAllAngularRootElements);
  const hasAngularVersion = !!document.querySelector("[ng-version]");
  // Angular Ivy attaches __ngContext to component host elements
  let ngContextEl: Element | null = null;
  try {
    const candidates = document.querySelectorAll("*");
    for (let i = 0; i < Math.min(candidates.length, 200) && !ngContextEl; i++) {
      const el = candidates[i];
      if (Object.getOwnPropertyNames(el).some((k) =>
          k === "__ngContext" || k === "__ngHost" || k.startsWith("__ngContext"))) {
        ngContextEl = el;
      }
    }
  } catch { /* */ }
  const hasAngularIvy = !!ngContextEl;
  const hasAngular    = hasAngularGlobal || hasAngularVersion || hasAngularIvy;

  // Vue / Nuxt detection — check Nuxt first (HL builder is Nuxt.js)
  const hasNuxt = !!(w.useNuxtApp || (w.app && Object.values(w.app ?? {}).some((ai: any) => ai?.appContext)));
  const hasVue  = !!(w.Vue || w.__vue_app__ || w.__VUE_DEVTOOLS_GLOBAL_HOOK__ || hasNuxt);

  // Final determination — Nuxt wins over plain Vue, React wins if detected, then Angular
  const framework = hasNuxt ? "nuxt" : hasReact ? "react" : hasAngular ? "angular" : hasVue ? "vue" : "unknown";

  // ── Angular Ivy injection path ─────────────────────────────────────────────
  if (!hasReact && hasAngular) {
    // Try ng.getComponent() on the element that has __ngContext
    const targetEl = ngContextEl ?? document.querySelector("[ng-version]") ?? document.body;

    try {
      // Angular Ivy exposes ng.getComponent, ng.getOwningComponent, ng.applyChanges
      const ngRuntime = (w as any).ng ?? {};
      const comp = typeof ngRuntime.getComponent === "function"
        ? ngRuntime.getComponent(targetEl)
        : typeof ngRuntime.getOwningComponent === "function"
          ? ngRuntime.getOwningComponent(targetEl)
          : null;

      if (!comp) {
        return JSON.stringify({
          ok: false, error: "angular_no_component", framework: "angular",
          hasAngularGlobal, hasAngularIvy, notableGlobals: notableGlobals.slice(0, 30),
        });
      }

      // Find sections array in the component
      const sectKeys = ["sections","rows","elements","blocks","steps","content","nodes"];
      let sectKey = "";
      for (const k of sectKeys) {
        if (Array.isArray((comp as any)[k]) && (comp as any)[k].length > 0) {
          sectKey = k; break;
        }
      }
      if (!sectKey) {
        return JSON.stringify({
          ok: false, error: "angular_no_sections_on_component", framework: "angular",
          componentKeys: Object.keys(comp as object).slice(0, 30),
          notableGlobals: notableGlobals.slice(0, 20),
        });
      }

      const existing = (comp as any)[sectKey] as any[];
      let testSection: any;
      try {
        testSection = JSON.parse(JSON.stringify(existing[0]));
        testSection.id    = "cl_test_" + Date.now();
        testSection.label = "CloneLevel Test Insert";
      } catch {
        testSection = { id: "cl_test_" + Date.now(), type: "section", label: "CloneLevel Test Insert", rows: [] };
      }
      (comp as any)[sectKey] = [...existing, testSection];

      // Apply changes
      if (typeof ngRuntime.applyChanges === "function") {
        ngRuntime.applyChanges(comp);
      }

      return JSON.stringify({
        ok: true, method: "angular_ng_component",
        sectionsKey: sectKey,
        countBefore: existing.length,
        countAfter:  existing.length + 1,
        framework:   "angular",
      });
    } catch (e) {
      return JSON.stringify({
        ok: false, error: "angular_inject_threw: " + String(e).slice(0, 100),
        framework: "angular", notableGlobals: notableGlobals.slice(0, 30),
      });
    }
  }

  // ── Nuxt.js injection path (HL builder confirmed as Nuxt) ─────────────────
  if (!hasReact && hasNuxt) {
    // Check revexBackendService
    let revexFound = false;
    let globalPropsKeys: string[] = [];
    let payloadKeys: string[] = [];
    try {
      for (const ai of Object.values(w.app ?? {}) as any[]) {
        const gp = ai?.appContext?.config?.globalProperties ?? {};
        globalPropsKeys = Object.keys(gp).slice(0, 30);
        const r = gp.revexBackendService;
        if (r && (typeof r.get === "function" || typeof r.post === "function")) { revexFound = true; break; }
      }
      if (w.useNuxtApp) {
        const na = w.useNuxtApp();
        payloadKeys = Object.keys(na?.payload?.data ?? {}).slice(0, 20);
      }
    } catch { /**/ }

    return JSON.stringify({
      ok: revexFound,
      framework: "nuxt",
      method: revexFound ? "nuxt_revex_ready" : "nuxt_no_revex",
      error: revexFound ? undefined : "revexBackendService_not_found — use Copy/Paste buttons",
      revexFound,
      globalPropsKeys,
      payloadKeys,
      notableGlobals: notableGlobals.slice(0, 20),
    });
  }

  if (!hasReact) {
    return JSON.stringify({
      ok: false,
      error: "no_react_detected",
      framework,
      hasAngular, hasAngularGlobal, hasAngularVersion, hasAngularIvy,
      hasNuxt, hasVue,
      hasReactHook, hasReactGlobal, hasReactDom,
      notableGlobals: notableGlobals.slice(0, 40),
    });
  }

  // ── Collect React fiber root nodes ─────────────────────────────────────────
  const roots: any[] = [];

  // Method A: DevTools hook renderers
  try {
    const hook = w.__REACT_DEVTOOLS_GLOBAL_HOOK__;
    if (hook?.renderers) {
      for (const [, renderer] of hook.renderers) {
        try {
          const rootSet: Set<any> = typeof renderer.getFiberRoots === "function"
            ? renderer.getFiberRoots() : new Set();
          for (const root of rootSet) { if (root?.current) roots.push(root.current); }
        } catch { /* sealed renderer */ }
      }
    }
    if (hook?._roots) {
      for (const root of hook._roots) { if (root?.current) roots.push(root.current); }
    }
  } catch { /* */ }

  // Method B: DOM fiber key scan — checks getOwnPropertyNames and first 200 elements
  try {
    const scanTargets: (Element | Document)[] = [document.body, document.documentElement];
    const allEls = document.querySelectorAll("*");
    for (let i = 0; i < Math.min(allEls.length, 200); i++) scanTargets.push(allEls[i]);

    for (const el of scanTargets) {
      if (!el) continue;
      const fk = Object.getOwnPropertyNames(el).find((k) =>
        k.startsWith("__reactFiber") || k.startsWith("__reactContainer") || k.startsWith("__reactInternals"));
      if (fk) {
        const f = (el as any)[fk];
        if (f) roots.push(f.child ?? f.stateNode ?? f);
      }
    }
  } catch { /* */ }

  if (roots.length === 0) {
    return JSON.stringify({
      ok: false, error: "no_fiber_roots_found", framework,
      hasReactHook, hasReactGlobal, hasReactDom,
      notableGlobals: notableGlobals.slice(0, 40),
    });
  }

  // ── Walk fiber tree for sections state ─────────────────────────────────────
  const SECTION_KEYS = ["sections", "rows", "elements", "blocks", "steps", "content", "nodes"];

  interface SectionsTarget {
    stateType:   "class" | "hook";
    fiber:       any;
    sectionsKey?: string;   // class component key
    hookNode?:   any;       // function component hook node
    sections:    any[];
  }

  function looksLikeSections(arr: any[]): boolean {
    if (!arr.length || typeof arr[0] !== "object") return false;
    const item = arr[0];
    return !!(item.rows != null || item.elements != null || item.cols != null ||
              item.type === "section" || item.type === "row" ||
              (item.id && (item.type || item.label || item.name)));
  }

  function walkFiber(fiber: any, depth: number): SectionsTarget | null {
    if (!fiber || depth > 120) return null;

    // ── Class component ──────────────────────────────────────────────────────
    if (fiber.stateNode?.setState && fiber.stateNode?.state &&
        typeof fiber.stateNode.state === "object" && !Array.isArray(fiber.stateNode.state)) {
      const s = fiber.stateNode.state;
      for (const k of SECTION_KEYS) {
        if (Array.isArray(s[k]) && looksLikeSections(s[k])) {
          return { stateType: "class", fiber, sectionsKey: k, sections: s[k] };
        }
      }
    }

    // ── Function component hooks (useState linked list) ─────────────────────
    if (fiber.memoizedState) {
      let hook = fiber.memoizedState;
      while (hook) {
        const ms = hook.memoizedState;
        if (Array.isArray(ms) && looksLikeSections(ms)) {
          return { stateType: "hook", fiber, hookNode: hook, sections: ms };
        }
        // Also check if memoizedState is an object with section keys (useReducer)
        if (ms && typeof ms === "object" && !Array.isArray(ms)) {
          for (const k of SECTION_KEYS) {
            if (Array.isArray(ms[k]) && looksLikeSections(ms[k])) {
              return { stateType: "hook", fiber, hookNode: hook, sections: ms[k] };
            }
          }
        }
        hook = hook.next;
      }
    }

    return walkFiber(fiber.child, depth + 1) || walkFiber(fiber.sibling, depth + 1);
  }

  let target: SectionsTarget | null = null;
  for (const root of roots) {
    target = walkFiber(root, 0);
    if (target) break;
  }

  if (!target) {
    // Extra: collect first-level state keys from root components for diagnostics
    const stateSnapshot: string[] = [];
    function collectStateKeys(fiber: any, depth: number): void {
      if (!fiber || depth > 4) return;
      if (fiber.stateNode?.state && typeof fiber.stateNode.state === "object") {
        stateSnapshot.push("class:" + Object.keys(fiber.stateNode.state).join(","));
      }
      if (fiber.memoizedState) {
        const types: string[] = [];
        let h = fiber.memoizedState;
        while (h) { types.push(typeof h.memoizedState + (Array.isArray(h.memoizedState) ? "[" + (h.memoizedState as any[]).length + "]" : "")); h = h.next; }
        if (types.length) stateSnapshot.push("hooks:" + types.join("|"));
      }
      collectStateKeys(fiber.child, depth + 1);
      collectStateKeys(fiber.sibling, depth + 1);
    }
    for (const root of roots.slice(0, 2)) collectStateKeys(root, 0);
    return JSON.stringify({
      ok: false, error: "no_sections_in_fiber_state", framework,
      rootsFound: roots.length, stateSnapshot: stateSnapshot.slice(0, 10),
    });
  }

  // ── Clone first section as test payload ────────────────────────────────────
  let testSection: any;
  try {
    testSection = JSON.parse(JSON.stringify(target.sections[0]));
    testSection.id    = "cl_test_" + Date.now();
    testSection.label = "CloneLevel Test Insert";
    function patchNodeText(node: any, ttl: number): void {
      if (!node || typeof node !== "object" || ttl <= 0) return;
      if (typeof node.content === "string") { node.content = "CloneLevel Test"; return; }
      if (typeof node.text    === "string") { node.text    = "CloneLevel Test"; return; }
      if (typeof node.value   === "string") { node.value   = "CloneLevel Test"; return; }
      for (const k of ["children","elements","rows","cols","columns"]) {
        if (Array.isArray(node[k])) node[k].forEach((c: any) => patchNodeText(c, ttl - 1));
      }
    }
    patchNodeText(testSection, 4);
  } catch {
    testSection = { id: "cl_test_" + Date.now(), type: "section", label: "CloneLevel Test Insert", rows: [] };
  }

  const newSections = [...target.sections, testSection];

  // ── Attempt injection ──────────────────────────────────────────────────────
  if (target.stateType === "class") {
    try {
      target.fiber.stateNode.setState({ [target.sectionsKey!]: newSections });
      // Force update in case shouldComponentUpdate blocks it
      try { target.fiber.stateNode.forceUpdate?.(); } catch { /* */ }
      return JSON.stringify({
        ok: true, method: "fiber_class_setState",
        sectionsKey: target.sectionsKey,
        countBefore: target.sections.length,
        countAfter:  newSections.length,
        framework,
      });
    } catch (e) {
      return JSON.stringify({
        ok: false, error: "class_setState_threw: " + String(e).slice(0, 100),
        method: "fiber_class_setState", framework,
      });
    }
  }

  // Hook path — prefer queue.dispatch (useState setter), fall back to queue.dispatchSetState
  const hookNode = target.hookNode!;
  const dispatch: ((v: any) => void) | null =
    typeof hookNode?.queue?.dispatch === "function"         ? hookNode.queue.dispatch :
    typeof hookNode?.queue?.dispatchSetState === "function" ? hookNode.queue.dispatchSetState :
    null;

  if (!dispatch) {
    // Last resort: locate the fiber's alternate and mutate memoizedState directly,
    // then schedule a re-render via React internals
    try {
      hookNode.memoizedState        = newSections;
      if (hookNode.baseState !== undefined) hookNode.baseState = newSections;
      // Schedule update on the fiber
      const ReactDOM = w.ReactDOM ?? w.__reactDom;
      if (typeof ReactDOM?.flushSync === "function") {
        ReactDOM.flushSync(() => { /* triggers pending state updates */ });
      }
      return JSON.stringify({
        ok: "maybe", method: "fiber_hook_memoizedState_mutate", framework,
        countBefore: target.sections.length, countAfter: newSections.length,
        warning: "no_dispatch_fn — mutated memoizedState directly, render not guaranteed",
      });
    } catch (e) {
      return JSON.stringify({
        ok: false, error: "no_hook_dispatch: " + String(e).slice(0, 80),
        hookQueueKeys: Object.keys(hookNode?.queue ?? {}).join(","), framework,
      });
    }
  }

  try {
    dispatch(newSections);
    return JSON.stringify({
      ok: true, method: "fiber_hook_dispatch",
      countBefore: target.sections.length, countAfter: newSections.length, framework,
    });
  } catch (e) {
    return JSON.stringify({
      ok: false, error: "hook_dispatch_threw: " + String(e).slice(0, 100),
      method: "fiber_hook_dispatch", framework,
    });
  }
}

// ─────────────────────────────────────────────────────────────────────────────
// NUXT / REVEX PATH  (discovered by reverse-engineering GHL Cloner)
//
// HL builder is a Nuxt.js (Vue) app.  The app exposes:
//   window.useNuxtApp()              — reads Nuxt payload / store
//   window.app                       — Nuxt app instance(s)
//   app.appContext.config.globalProperties.revexBackendService
//                                    — HL's own pre-authenticated HTTP client
//
// All four functions below are COMPLETELY SELF-CONTAINED (no imports/closures).
// ─────────────────────────────────────────────────────────────────────────────

/** Step 1 — Read funnel + page identity from any HL page that loaded Nuxt. */
export function _nuxtGetFunnelInfoFunc(): string {
  const w = window as any;
  try {
    if (!w.useNuxtApp) {
      // Fallback: scan window.app (Nuxt sometimes registers under a different key)
      const appEntry = Object.values(w.app ?? {})[0] as any;
      if (!appEntry?.appContext) {
        return JSON.stringify({ ok: false, error: "not_nuxt", hasApp: !!w.app });
      }
    }
    const nuxtApp = w.useNuxtApp ? w.useNuxtApp() : null;
    if (!nuxtApp) return JSON.stringify({ ok: false, error: "useNuxtApp_returned_null" });

    // payload.data is an object keyed by query key — find first entry with funnelId
    const payloadData = nuxtApp?.payload?.data ?? nuxtApp?._data ?? {};
    const keys = Object.keys(payloadData);
    let data: any = null;
    for (const k of keys) {
      const v = payloadData[k];
      if (v && typeof v === "object" && (v.funnelId || v.funnel_id)) { data = v; break; }
    }

    if (!data) {
      return JSON.stringify({
        ok: false, error: "no_funnel_in_payload",
        payloadKeys: keys.slice(0, 20),
      });
    }

    return JSON.stringify({
      ok: true,
      funnelId:   data.funnelId   ?? data.funnel_id,
      funnelName: data.funnelName ?? data.funnel_name ?? "",
      locationId: data.locationId ?? data.location_id ?? "",
      pageId:     data.pageId     ?? data.page_id     ?? "",
      stepId:     data.stepId     ?? data.step_id     ?? "",
      pageName:   data.pageName   ?? data.page_name   ?? "",
      pageUrl:    data.pageUrl    ?? data.page_url    ?? "",
    });
  } catch (e) {
    return JSON.stringify({ ok: false, error: "nuxtGetFunnelInfo_threw: " + String(e).slice(0, 120) });
  }
}

/**
 * Step 2 (destination) — read funnelId + stepId of the currently open builder page.
 * Args[0] = pageBuilderOrFunnelId (extracted from the URL path segment after /page-builder/)
 */
export async function _revexGetBuilderInfoFunc(builderId: string): Promise<string> {
  const w = window as any;
  try {
    // Inline the revex getter (must be self-contained)
    const appMap = w.app ?? {};
    let revex: any = null;
    for (const ai of Object.values(appMap) as any[]) {
      const r = ai?.appContext?.config?.globalProperties?.revexBackendService;
      if (r && (typeof r.get === "function" || typeof r.post === "function")) { revex = r; break; }
    }
    if (!revex) {
      return JSON.stringify({
        ok: false, error: "revexBackendService_not_found",
        appKeys: Object.keys(appMap),
      });
    }

    const resp = await revex.get(`https://backend.leadconnectorhq.com/funnels/page/${builderId}`);
    const data = resp?.data ?? resp;

    return JSON.stringify({
      ok: true,
      funnelId:   data?.funnelId   ?? data?.funnel_id,
      stepId:     data?.stepId     ?? data?.step_id,
      locationId: data?.locationId ?? data?.location_id,
      pageId:     data?.pageId     ?? data?.page_id,
      raw:        JSON.stringify(data).slice(0, 400),
    });
  } catch (e) {
    return JSON.stringify({ ok: false, error: "_revexGetBuilderInfo_threw: " + String(e).slice(0, 140) });
  }
}

/**
 * Step 3 — Perform the actual clone.
 * Args[0] = req object: { sourceFunnelId, sourceStepId, destFunnelId, destStepId, locationId }
 */
export async function _revexCloneFunnelStepFunc(req: {
  sourceFunnelId: string; sourceStepId: string;
  destFunnelId: string;   destStepId:   string;
  locationId: string;
}): Promise<string> {
  const w = window as any;
  try {
    // ── SmartCloner's exact revex getter: l() ───────────────────────────────
    const appEl = document.querySelector("#app") as any;
    const revex = appEl?.__vue_app__?.config?.globalProperties?.revexBackendService ?? null;
    if (!revex) {
      return JSON.stringify({ ok: false, error: "revexBackendService_not_found — open the HL page builder tab" });
    }

    // ── Get userId via AppUtils (SmartCloner's f()) ──────────────────────────
    let userId = "";
    try {
      if (typeof w.AppUtils !== "undefined" && w.AppUtils?.Utilities?.getCurrentUser) {
        const u = await w.AppUtils.Utilities.getCurrentUser();
        userId = u?.id ?? u?.userId ?? "";
      }
    } catch (_) {}

    // ── Build payload exactly as SmartCloner's p() does ─────────────────────
    // SmartCloner: { funnelId: dest, funnelIdToImport: src, funnels: [dest],
    //               locationId, pageIndexToImport: "0", pageIndexToImportInto: "0",
    //               stepId: src, stepIdToImportInto: dest, userId }
    const payload: Record<string, any> = {
      funnelId:              req.destFunnelId,
      funnelIdToImport:      req.sourceFunnelId,
      funnels:               [req.destFunnelId],
      locationId:            req.locationId,
      pageIndexToImport:     "0",
      pageIndexToImportInto: "0",
      stepId:                req.sourceStepId,
      stepIdToImportInto:    req.destStepId,
    };
    if (userId) payload.userId = userId;

    const response = await revex.post(
      "https://backend.leadconnectorhq.com/funnels/funnel/clone-funnel-step/",
      payload,
    );
    const data = response?.data ?? response;
    const status = typeof response?.status === "number" ? response.status
                 : typeof data?.status === "number"     ? data.status
                 : 0;

    if (status >= 400) {
      return JSON.stringify({
        ok: false, error: `HTTP ${status}: ` + (data?.message ?? data?.response ?? "server error"),
        raw: JSON.stringify(data).slice(0, 300),
        payload: JSON.stringify(payload).slice(0, 300),
      });
    }

    const ok = !data?.status || data?.status === "ok" || status < 300;
    return JSON.stringify({ ok, status, raw: JSON.stringify(data).slice(0, 400) });
  } catch (e) {
    return JSON.stringify({ ok: false, error: "_revexCloneFunnelStep_threw: " + String(e).slice(0, 140) });
  }
}

/** Step 4 — Refresh the builder iframe so the newly cloned page renders. */
export function _refreshBuilderIframeFunc(): string {
  try {
    const iframe = document.querySelector('iframe[name="funnel-builder"]') as HTMLIFrameElement | null;
    if (!iframe) return JSON.stringify({ ok: false, error: "no_iframe_name_funnel-builder" });
    iframe.src = iframe.src;
    return JSON.stringify({ ok: true, src: iframe.src.slice(0, 80) });
  } catch (e) {
    return JSON.stringify({ ok: false, error: String(e).slice(0, 100) });
  }
}

/**
 * GET-then-PUT paste via revexBackendService.
 *
 * The correct way to inject sections into an HL builder page:
 *   1. GET the page's current data from /funnels/page/{pageId}
 *   2. Append our sections to the sections array inside the pageData
 *   3. PUT the full modified page back — this is the same save the builder uses
 *
 * We do NOT use the prebuilt-section/sync/changes endpoint — that is for HL's own
 * template library, not arbitrary content injection.
 *
 * Running in MAIN world gives us access to revexBackendService (pre-authenticated
 * axios) and avoids all CORS issues.
 */
export async function _getPageDataAndPasteFunc(
  pageId:        string,
  locationId:    string,
  sectionsToAdd: any[],
): Promise<string> {
  const w = window as any;

  // ── Find revexBackendService ─────────────────────────────────────────────────
  let revex: any = null;
  for (const ai of Object.values(w.app ?? {}) as any[]) {
    const r = ai?.appContext?.config?.globalProperties?.revexBackendService;
    if (r && typeof r.put === "function") { revex = r; break; }
  }
  if (!revex) return JSON.stringify({ ok: false, error: "revexBackendService_not_found" });

  const PAGE_BASE = `https://backend.leadconnectorhq.com/funnels/page/${pageId}`;

  // ── Step 1: GET current page data ───────────────────────────────────────────
  let pageData: any = null;
  try {
    const resp = await revex.get(PAGE_BASE);
    pageData = resp?.data ?? resp;
  } catch (e: any) {
    const s = e?.response?.status;
    const d = e?.response?.data;
    return JSON.stringify({ ok: false, error: `GET failed HTTP ${s ?? "?"}: ${d?.message ?? String(e).slice(0, 100)}`, strategy: "get" });
  }
  if (!pageData || typeof pageData !== "object") {
    return JSON.stringify({ ok: false, error: "GET returned empty/non-object", strategy: "get" });
  }

  // ── Step 2: Locate the sections array and grab a sample for format logging ───
  const pageDataKeys  = Object.keys(pageData).join(",");
  const bodyKeys      = pageData.body ? Object.keys(pageData.body).join(",") : "";

  // HL pages store sections in various places depending on version:
  //   pageData.body.sections  (most common in Nuxt builder)
  //   pageData.body.children
  //   pageData.sections
  //   pageData.children
  let sectionsPath = "";
  let existingSections: any[] = [];

  if (Array.isArray(pageData.body?.sections))  { existingSections = pageData.body.sections;  sectionsPath = "body.sections"; }
  else if (Array.isArray(pageData.body?.children)) { existingSections = pageData.body.children; sectionsPath = "body.children"; }
  else if (Array.isArray(pageData.sections))   { existingSections = pageData.sections;       sectionsPath = "sections"; }
  else if (Array.isArray(pageData.children))   { existingSections = pageData.children;       sectionsPath = "children"; }

  const sampleSection = JSON.stringify(existingSections[0] ?? null).slice(0, 600);

  // ── Step 3: Convert captured HTML into HL section objects ───────────────────
  // If sectionsToAdd are already HL objects (have .type or ._id), use them verbatim.
  // Otherwise wrap each one as a customCode element inside a section > row > col tree.
  function htmlToHlSection(html: string, idx: number): any {
    const ts = `${Date.now()}_${idx}`;
    return {
      _id:   `cl_sec_${ts}`,
      type:  "section",
      children: [{
        _id:   `cl_row_${ts}`,
        type:  "row",
        children: [{
          _id:   `cl_col_${ts}`,
          type:  "col",
          children: [{
            _id:   `cl_code_${ts}`,
            type:  "customCode",
            value: html,
            tag:   "div",
            style: {},
          }],
          style: {},
        }],
        style: {},
      }],
      style: {},
    };
  }

  const newSections = sectionsToAdd.map((sec: any, i: number) => {
    if (sec && typeof sec === "object" && (sec.type || sec._id || sec.children)) return sec;
    const html = typeof sec === "string" ? sec
      : (sec.outerHTML ?? sec.html ?? sec.body ?? JSON.stringify(sec));
    return htmlToHlSection(html, i);
  });

  // ── Step 4: Merge new sections into the correct place in pageData ────────────
  let updatedPageData: any = JSON.parse(JSON.stringify(pageData)); // deep clone
  if (sectionsPath === "body.sections")  updatedPageData.body.sections  = [...existingSections, ...newSections];
  else if (sectionsPath === "body.children") updatedPageData.body.children = [...existingSections, ...newSections];
  else if (sectionsPath === "sections")  updatedPageData.sections  = [...existingSections, ...newSections];
  else if (sectionsPath === "children")  updatedPageData.children  = [...existingSections, ...newSections];
  else {
    // No known sections field — try injecting under body.sections
    updatedPageData.body = updatedPageData.body ?? {};
    updatedPageData.body.sections = [...newSections];
    sectionsPath = "body.sections (created)";
  }

  // ── Step 5: Try every plausible save pattern ────────────────────────────────
  // Pull IDs that might form alternate endpoint paths
  const funnelId = pageData.funnelId ?? pageData.funnel_id ?? "";
  const stepId   = pageData.stepId   ?? pageData.step_id   ?? "";

  // Body variants: full page data vs. partial (just the changed body field)
  const partialBody = updatedPageData.body
    ? { body: updatedPageData.body, locationId: locationId || pageData.locationId || "" }
    : null;

  type Attempt = { method: string; url: string; body: any };
  const attempts_plan: Attempt[] = [
    // Standard REST patterns — full page data
    { method: "put",   url: PAGE_BASE,           body: updatedPageData },
    { method: "patch", url: PAGE_BASE,           body: updatedPageData },
    // Builder-specific endpoints
    { method: "put",   url: `https://backend.leadconnectorhq.com/funnels/builder/page/${pageId}`, body: updatedPageData },
    { method: "patch", url: `https://backend.leadconnectorhq.com/funnels/builder/page/${pageId}`, body: updatedPageData },
    // Partial update (just body field) — avoids readonly-field validation errors
    ...(partialBody ? [
      { method: "patch", url: PAGE_BASE, body: partialBody },
      { method: "put",   url: PAGE_BASE, body: partialBody },
    ] : []),
    // Step-based endpoints (if stepId was in the page data)
    ...(stepId ? [
      { method: "put",   url: `https://backend.leadconnectorhq.com/funnels/funnel-step/${stepId}`,           body: updatedPageData },
      { method: "patch", url: `https://backend.leadconnectorhq.com/funnels/funnel-step/${stepId}`,           body: updatedPageData },
      { method: "patch", url: `https://backend.leadconnectorhq.com/funnels/funnel-step/${stepId}`,           body: partialBody ?? updatedPageData },
    ] : []),
    // POST to save / update variants
    { method: "post",  url: `https://backend.leadconnectorhq.com/funnels/page/${pageId}/save`,   body: updatedPageData },
    { method: "post",  url: `https://backend.leadconnectorhq.com/funnels/page/save`,             body: { ...updatedPageData, id: pageId } },
  ];

  const attempts: any[] = [];
  for (const plan of attempts_plan) {
    try {
      const fn     = (revex as any)[plan.method] as Function;
      if (typeof fn !== "function") continue;
      const resp   = await fn.call(revex, plan.url, plan.body);
      const status = resp?.status ?? 0;
      const data   = resp?.data ?? resp;
      if (status < 400) {
        return JSON.stringify({
          ok:               true,
          status,
          saveUrl:          plan.url,
          saveMethod:       plan.method,
          sectionsPath,
          addedSections:    newSections.length,
          existingSections: existingSections.length,
          pageDataKeys,
          bodyKeys,
          sampleSection,
          funnelId,
          stepId,
          strategy:         "get-save",
        });
      }
      attempts.push({ method: plan.method, url: plan.url.split("/").slice(-2).join("/"), status, msg: JSON.stringify(data?.message ?? data).slice(0, 80) });
    } catch (e: any) {
      const status = e?.response?.status;
      const data   = e?.response?.data;
      attempts.push({ method: plan.method, url: plan.url.split("/").slice(-2).join("/"), status, msg: (data?.message ?? String(e)).slice(0, 60) });
    }
    // Note: we intentionally try all endpoints (no early break) to get a full picture.
  }

  // Summarise what was tried for the error message shown in the popup
  const summary = attempts.map((a) => `${a.method.toUpperCase()} …/${a.url}→${a.status ?? "?"}:${a.msg}`).join(" | ");

  return JSON.stringify({
    ok:          false,
    error:       summary || "All save endpoints returned errors",
    attempts,
    sectionsPath,
    pageDataKeys,
    bodyKeys,
    sampleSection,
    funnelId,
    stepId,
    strategy:    "get-save",
  });
}

/**
 * Runs in the HL BUILDER tab (MAIN world, has revex).
 * Given a source page domain + path, searches the GHL backend for a matching
 * funnel page — the "CRM detection" path for pages that don't expose Nuxt globals.
 *
 * Flow:
 *   1. GET /funnels/funnel/ (list all funnels for this location)
 *   2. Filter by domain
 *   3. GET /funnels/funnel/fetch/{funnelId} → steps
 *   4. Match step by URL path (fallback: first step)
 *
 * Returns JSON: { ok, funnelId?, stepId?, locationId?, stepName?, error? }
 */

/**
 * Detects the CMS/platform of the current page by inspecting well-known
 * global objects, meta tags, and DOM attributes.
 *
 * Returns a short human-readable platform name string, e.g.:
 *   "HighLevel" | "Nuxt.js" | "Next.js" | "WordPress" | "Shopify" |
 *   "Webflow" | "Squarespace" | "Wix" | "Framer" | "HubSpot" | "Web"
 *
 * Runs in the page's MAIN world (injected via executeScript).
 */
export function _detectCmsFunc(): string {
  const w = window as any;

  // Helper: check meta generator tag
  function metaGen(): string {
    const el = document.querySelector('meta[name="generator"]') as HTMLMetaElement | null;
    return (el?.content ?? "").toLowerCase();
  }

  // HighLevel (GHL) — check window.attribution first (published pages)
  if (w.attribution?.locationId) return "HighLevel";

  // HighLevel builder
  if (/page-builder\.leadconnectorhq\.com/.test(location.hostname)) return "HighLevel";

  // WordPress
  if (w.wp?.blocks || w.wpApiSettings || metaGen().includes("wordpress")) return "WordPress";

  // Shopify
  if (w.Shopify?.shop || typeof w.Shopify === "object") return "Shopify";

  // Webflow
  if (w.Webflow || metaGen().includes("webflow") || document.body?.hasAttribute?.("data-wf-site")) return "Webflow";

  // Squarespace
  if (w.Y?.config?.squarespace || document.querySelector("[data-config-node='squarespace']") ||
      metaGen().includes("squarespace")) return "Squarespace";

  // Wix
  if (w.wixBiSession || document.querySelector('meta[name="generator"][content*="Wix"]') ||
      metaGen().includes("wix")) return "Wix";

  // Framer
  if (w.__framerIsBrowser || metaGen().includes("framer")) return "Framer";

  // HubSpot
  if (w._hsq || document.querySelector('.hs-form')) return "HubSpot";

  // Nuxt.js (GHL and other Nuxt sites — check after GHL attribution check)
  if (typeof w.useNuxtApp === "function" || w.__NUXT__) return "Nuxt.js";

  // Next.js
  if (w.__NEXT_DATA__) return "Next.js";

  // Ghost
  if (metaGen().includes("ghost")) return "Ghost";

  // Drupal
  if (w.Drupal || metaGen().includes("drupal")) return "Drupal";

  return "Web";
}

/**
 * Fetches all steps of a GHL funnel via revexBackendService.
 * Returns JSON: { ok, funnelId, funnelName, steps: [{ id, name, url, sequence, stepType, splitUrl?, splitName? }] }
 *
 * Runs in the BUILDER tab's MAIN world (has revex access).
 */
export async function _fetchGhlFunnelStepsFunc(funnelId: string): Promise<string> {
  const w   = window as any;
  const BASE = "https://backend.leadconnectorhq.com";

  function getRevex() {
    return (
      w.document?.querySelector?.("#app")?.__vue_app__?.config.globalProperties?.revexBackendService ??
      w.Object?.values?.(w.app ?? {})?.[0]?.appContext?.config?.globalProperties?.revexBackendService ??
      null
    );
  }

  try {
    const revex = getRevex();
    if (!revex) return JSON.stringify({ ok: false, error: "no-revex" });

    const res  = await revex.get(`${BASE}/funnels/funnel/fetch/${funnelId}`);
    const body = res?.data?.data ?? res?.data ?? {};

    // HL wraps the funnel in body.funnel; fallback to body itself
    const funnel = body.funnel ?? body;
    const rawSteps: any[] = Array.isArray(funnel.steps) ? funnel.steps
                          : Array.isArray(body.steps)   ? body.steps
                          : [];

    const steps = rawSteps
      .sort((a: any, b: any) => (a.sequence ?? a.index ?? a.order ?? 0) - (b.sequence ?? b.index ?? b.order ?? 0))
      .map((s: any, i: number) => ({
        id:         s.id   ?? s._id    ?? `step-${i}`,
        name:       s.name ?? s.stepName ?? `Step ${i + 1}`,
        url:        s.url  ?? s.path   ?? "",
        sequence:   s.sequence ?? s.index ?? s.order ?? i,
        stepType:   s.stepType ?? s.type ?? "",
        products:   (s.products ?? []).length,
        splitUrl:   s.splitUrl  ?? "",
        splitName:  s.splitName ?? "",
      }));

    return JSON.stringify({
      ok:         true,
      funnelId,
      funnelName: funnel.name ?? funnel.funnelName ?? "Funnel",
      domain:     funnel.domain ?? funnel.customDomain ?? "",
      steps,
    });
  } catch (err) {
    return JSON.stringify({ ok: false, error: String(err).slice(0, 200) });
  }
}

export function _lookupGhlPageByDomainFunc(sourceDomain: string, sourcePath: string): Promise<string> {
  return (async () => {
    const w     = window as any;
    const BASE  = "https://backend.leadconnectorhq.com";
    const log: string[] = [];

    function getRevex() {
      return (
        w.document?.querySelector?.("#app")?.__vue_app__?.config.globalProperties?.revexBackendService ??
        w.Object?.values?.(w.app ?? {})?.[0]?.appContext?.config?.globalProperties?.revexBackendService ??
        null
      );
    }

    try {
      const revex = getRevex();
      if (!revex) return JSON.stringify({ ok: false, error: "no-revex" });

      // Extract locationId from current builder URL
      const locMatch = window.location.href.match(/\/location(?:s)?\/([A-Za-z0-9_-]{6,})/i);
      const locationId = locMatch?.[1] ?? "";
      log.push(`locationId=${locationId || "(none)"}`);
      if (!locationId) return JSON.stringify({ ok: false, error: "no-locationId" });

      // Normalise a URL string for comparison
      const normalise = (s: string) => (s ?? "").replace(/^https?:\/\//, "").replace(/\/$/, "").toLowerCase();
      const needle = normalise(sourceDomain);

      // Extract all candidate domain strings from a funnel object (GHL uses many schemas)
      function domainCandidates(f: any): string[] {
        const vals: string[] = [];
        for (const key of ["domain","customDomain","domainName","funnelUrl","url","siteUrl","subdomain","hostname"]) {
          const v = f[key];
          if (!v) continue;
          if (typeof v === "string") vals.push(v);
          // some versions nest: { domain: "x" } or { domainName: "x" }
          else if (typeof v === "object") {
            for (const sub of ["domain","domainName","hostname","url","name"]) {
              if (typeof v[sub] === "string") vals.push(v[sub]);
            }
          }
        }
        return vals;
      }

      function extractFunnelId(f: any): string | undefined {
        return f._id ?? f.id ?? f.funnelId ?? f.fid ?? undefined;
      }

      function extractList(body: any): any[] {
        if (Array.isArray(body)) return body;
        // Try every common wrapping pattern GHL uses
        const candidates = [
          body?.data?.funnels, body?.data?.data?.funnels,
          body?.data?.list,    body?.data,
          body?.funnels,       body?.list,
          body?.items,
        ];
        for (const c of candidates) { if (Array.isArray(c) && c.length > 0) return c; }
        return [];
      }

      // Try multiple list endpoints
      const listEndpoints = [
        `${BASE}/funnels/funnel/?locationId=${locationId}&domain=${encodeURIComponent(sourceDomain)}&limit=20`,
        `${BASE}/funnels/funnel/?locationId=${locationId}&limit=100`,
        `${BASE}/funnels/funnel/list?locationId=${locationId}&limit=100`,
        `${BASE}/funnels/?locationId=${locationId}&limit=100`,
      ];

      for (const endpoint of listEndpoints) {
        try {
          const res = await revex.get(endpoint);
          log.push(`${endpoint.split("?")[0]} → status=${res?.status}`);
          if (res?.status !== 200) continue;

          const list = extractList(res.data ?? {});
          if (!list.length) { log.push("empty list"); continue; }

          // Log first item keys for diagnostics
          const firstKeys = Object.keys(list[0] ?? {}).join(",");
          log.push(`keys=${firstKeys.slice(0, 80)}`);

          // Primary match: any domain field equals needle
          let matched = list.find((f: any) => {
            return domainCandidates(f).some(v => normalise(v) === needle || normalise(v).includes(needle));
          });

          // Fallback: needle appears in funnel name (useful when domain field absent)
          if (!matched) {
            const domainRoot = needle.replace(/^www\./, "").split(".")[0];
            matched = list.find((f: any) =>
              (f.name ?? f.funnelName ?? "").toLowerCase().includes(domainRoot)
            );
            if (matched) log.push(`name-fallback matched: ${matched.name ?? matched.funnelName}`);
          }

          if (!matched) {
            const firstDomains = domainCandidates(list[0]).join("|") || "(none)";
            log.push(`no match in ${list.length} funnels — first domains: ${firstDomains}`);
            continue;
          }

          const funnelId = extractFunnelId(matched);
          log.push(`matched funnel id=${funnelId} name=${matched.name ?? matched.funnelName}`);

          // Fetch steps for this funnel
          const fetchRes = await revex.get(`${BASE}/funnels/funnel/fetch/${funnelId}`);
          const fetchBody = fetchRes?.data?.data ?? fetchRes?.data ?? {};
          const steps: any[] = fetchBody.steps ?? [];

          if (!steps.length) return JSON.stringify({ ok: false, error: "no-steps", log: log.join("|") });

          // Match step by URL path, fallback to first
          const normPath = (sourcePath || "/").replace(/\/$/, "").toLowerCase() || "/";
          let step = steps.find((s: any) => {
            const su = (s.url ?? "").replace(/\/$/, "").toLowerCase();
            return su && (normPath.includes(su) || su.includes(normPath));
          }) ?? steps[0];

          return JSON.stringify({
            ok:         true,
            funnelId,
            stepId:     step.id,
            stepName:   step.name,
            locationId,
            log:        log.join("|"),
          });
        } catch (err) {
          log.push(`${endpoint.split("?")[0]} threw: ${String(err).slice(0, 60)}`);
        }
      }

      return JSON.stringify({ ok: false, error: "not-found", domain: sourceDomain, log: log.join("|") });
    } catch (outerErr) {
      return JSON.stringify({ ok: false, error: String(outerErr).slice(0, 100), log: log.join("|") });
    }
  })();
}

/**
 * Runs on ANY page (MAIN world) to detect GHL/HL page metadata.
 * Called during Library capture — if the source is a published GHL page we can
 * clone it via the API (clone-funnel-step) instead of injecting scraped HTML.
 *
 * Tries every known location where GHL embeds funnelId + stepId:
 *   1. useNuxtApp().payload.data  — SmartCloner's primary method
 *   2. window.__NUXT__            — Nuxt 2 / some Nuxt 3 configs
 *   3. script#__NUXT_DATA__       — SSR-embedded JSON in the DOM
 *   4. ALL inline <script> tags   — brute-force scan for "funnelId"
 *   5. window.pageData / window.funnel / etc
 *
 * Returns a JSON string including debugLog so the SW can log what it tried.
 */
export function _extractGhlMetadataFunc(): string {
  const w = window as any;
  const log: string[] = [];

  // Helper: scan a JSON string for funnelId + stepId
  function extractIds(str: string, source: string): string | null {
    const fm = str.match(/"funnelId"\s*:\s*"([A-Za-z0-9_\-]{8,40})"/);
    const sm = str.match(/"stepId"\s*:\s*"([A-Za-z0-9_\-]{8,40})"/);
    if (fm && sm) {
      const lm = str.match(/"locationId"\s*:\s*"([A-Za-z0-9_\-]{8,40})"/);
      return JSON.stringify({
        isGhlPage:  true,
        funnelId:   fm[1],
        stepId:     sm[1],
        locationId: lm?.[1] ?? w.attribution?.locationId ?? "",
        source,
        debugLog:   log.join(" | "),
      });
    }
    return null;
  }

  try {
    const locationId = w.attribution?.locationId ?? "";
    log.push(`attr.locationId=${locationId || "(none)"}`);

    // ── 1. useNuxtApp() — SmartCloner's primary method ────────────────────────
    if (typeof w.useNuxtApp === "function") {
      log.push("useNuxtApp=available");
      try {
        const nuxt = w.useNuxtApp();
        const payload = nuxt?.payload?.data;
        if (payload) {
          // Try direct pageData key
          const pd = payload.pageData ?? payload.page ?? payload;
          if (pd?.funnelId && pd?.stepId) {
            log.push("found via useNuxtApp.payload.data.pageData");
            return JSON.stringify({
              isGhlPage:  true,
              funnelId:   pd.funnelId,
              stepId:     pd.stepId,
              locationId: locationId || pd.locationId || "",
              source:     "useNuxtApp-pageData",
              debugLog:   log.join(" | "),
            });
          }
          // Scan every key of payload for an object with funnelId+stepId
          for (const key of Object.keys(payload)) {
            const val = payload[key];
            if (val && typeof val === "object" && val.funnelId && val.stepId) {
              log.push(`found via useNuxtApp.payload.data.${key}`);
              return JSON.stringify({
                isGhlPage:  true,
                funnelId:   val.funnelId,
                stepId:     val.stepId,
                locationId: locationId || val.locationId || "",
                source:     `useNuxtApp-data.${key}`,
                debugLog:   log.join(" | "),
              });
            }
          }
          // Last resort: stringify the whole payload and regex search
          const hit = extractIds(JSON.stringify(payload), "useNuxtApp-serialized");
          if (hit) return hit;
        } else {
          log.push(`useNuxtApp payload.data=${payload}`);
        }
      } catch (e) {
        log.push(`useNuxtApp threw: ${String(e).slice(0, 60)}`);
      }
    } else {
      log.push("useNuxtApp=not-global");
    }

    // ── 2. window.__NUXT__ (Nuxt 2 / older Nuxt 3) ────────────────────────────
    if (w.__NUXT__) {
      log.push("__NUXT__=found");
      const hit = extractIds(JSON.stringify(w.__NUXT__), "__NUXT__");
      if (hit) return hit;
    }

    // ── 3. window.__NUXT_DATA__ object ────────────────────────────────────────
    if (w.__NUXT_DATA__) {
      log.push("__NUXT_DATA__=found");
      const hit = extractIds(JSON.stringify(w.__NUXT_DATA__), "__NUXT_DATA__-obj");
      if (hit) return hit;
    }

    // ── 4. Scan all <script> DOM elements for "funnelId" ─────────────────────
    // This covers both script#__NUXT_DATA__ and any inline JSON blobs HL injects.
    const inlineScripts = Array.from(document.querySelectorAll("script:not([src])")) as HTMLScriptElement[];
    log.push(`inline-scripts=${inlineScripts.length}`);
    for (const el of inlineScripts) {
      const content = el.textContent ?? "";
      if (!content.includes("funnelId")) continue;
      log.push(`script[id=${el.id || "(no-id)"}] contains funnelId`);
      const hit = extractIds(content, `dom-script[id=${el.id || "?"}]`);
      if (hit) return hit;
    }

    // ── 5. Known window globals GHL might set ────────────────────────────────
    const candidates = ["pageData", "funnel", "funnelData", "pageInfo", "stepData",
                        "__GHL__", "__HL__", "ghlPage", "attribution"];
    for (const key of candidates) {
      const val = w[key];
      if (!val || typeof val !== "object") continue;
      if (val.funnelId && val.stepId) {
        log.push(`found in window.${key}`);
        return JSON.stringify({
          isGhlPage:  true,
          funnelId:   val.funnelId,
          stepId:     val.stepId,
          locationId: locationId || val.locationId || "",
          source:     `window.${key}`,
          debugLog:   log.join(" | "),
        });
      }
      // One level deeper
      if (typeof val === "object") {
        const hit = extractIds(JSON.stringify(val), `window.${key}-deep`);
        if (hit) return hit;
      }
    }

  } catch (outerErr) {
    log.push(`outer-error: ${String(outerErr).slice(0, 80)}`);
  }

  return JSON.stringify({ isGhlPage: false, debugLog: log.join(" | ") });
}

/**
 * Uses revexBackendService.post(clone-funnel-step) to clone a GHL page via the
 * official API — the same method SmartCloner uses.
 *
 * Runs in the BUILDER tab's MAIN world (has revex + AppUtils access).
 *
 * @param sourceFunnelId  — funnelId of the page that was captured
 * @param sourceStepId    — stepId of the page that was captured
 * @param destPageId      — builder page ID extracted from the current tab URL
 * @param destLocationId  — locationId from the current builder URL
 */
export async function _cloneFromGhlCaptureFunc(
  sourceFunnelId:  string,
  sourceStepId:    string,
  destPageId:      string,
  destLocationId:  string,
): Promise<string> {
  const w = window as any;
  const BASE = "https://backend.leadconnectorhq.com";

  // ── Find revexBackendService — SmartCloner's exact l() method ────────────────
  // SmartCloner: document.querySelector("#app")?.__vue_app__?.config.globalProperties.revexBackendService
  const appEl = document.querySelector("#app") as any;
  const revex = appEl?.__vue_app__?.config?.globalProperties?.revexBackendService ?? null;
  if (!revex) return JSON.stringify({ ok: false, error: "revexBackendService_not_found — is this the HL builder tab?" });

  // ── Step 1: GET destination page info (destFunnelId + destStepId) ─────────
  let destData: any = null;
  try {
    const r = await revex.get(`${BASE}/funnels/page/${destPageId}`);
    destData = r?.data ?? r;
  } catch (e: any) {
    return JSON.stringify({ ok: false, error: `GET dest page failed: ${e?.response?.status ?? String(e).slice(0, 80)}` });
  }
  const destFunnelId = destData?.funnelId ?? destData?.funnel_id ?? "";
  const destStepId   = destData?.stepId   ?? destData?.step_id   ?? "";
  const resolvedLoc  = destLocationId || destData?.locationId || destData?.location_id || "";

  if (!destFunnelId || !destStepId) {
    return JSON.stringify({ ok: false, error: `Could not resolve dest funnelId/stepId from pageData. Keys: ${Object.keys(destData ?? {}).join(",")}` });
  }

  // ── Step 2: GET userId via AppUtils (same as SmartCloner) ────────────────────
  let userId = "";
  try {
    if (typeof w.AppUtils !== "undefined" && w.AppUtils?.Utilities?.getCurrentUser) {
      const u = await w.AppUtils.Utilities.getCurrentUser();
      userId = u?.id ?? u?.userId ?? "";
    }
  } catch (_) {}

  // ── Step 3: POST clone-funnel-step ──────────────────────────────────────────
  const payload: Record<string, any> = {
    funnelId:             destFunnelId,
    funnelIdToImport:     sourceFunnelId,
    funnels:              [destFunnelId],
    locationId:           resolvedLoc,
    pageIndexToImport:    "0",
    pageIndexToImportInto: "0",
    stepId:               sourceStepId,
    stepIdToImportInto:   destStepId,
  };
  if (userId) payload.userId = userId;

  try {
    const resp   = await revex.post(`${BASE}/funnels/funnel/clone-funnel-step/`, payload);
    const status = resp?.status ?? 0;
    const data   = resp?.data ?? resp;
    return JSON.stringify({
      ok:           status < 400,
      status,
      data:         JSON.stringify(data).slice(0, 200),
      destFunnelId,
      destStepId,
      userId:       userId || "(none)",
      strategy:     "clone-funnel-step",
    });
  } catch (e: any) {
    const status = e?.response?.status;
    const data   = e?.response?.data;
    return JSON.stringify({
      ok:     false,
      status,
      error:  `clone-funnel-step HTTP ${status ?? "?"}: ${data?.message ?? String(e).slice(0, 100)}`,
      payload: JSON.stringify(payload).slice(0, 300),
      strategy: "clone-funnel-step",
    });
  }
}

/**
 * Diagnostic — reads revexBackendService presence + app globals to confirm Nuxt.
 * Used by the TEST_INJECT path's "NUXT" branch.
 */
export function _nuxtDiagFunc(): string {
  const w = window as any;
  try {
    const hasUseNuxtApp = typeof w.useNuxtApp === "function";
    const appKeys = Object.keys(w.app ?? {});
    let revexFound = false;
    let globalPropsKeys: string[] = [];
    for (const ai of Object.values(w.app ?? {}) as any[]) {
      const gp = ai?.appContext?.config?.globalProperties ?? {};
      globalPropsKeys = Object.keys(gp).slice(0, 30);
      const r = gp.revexBackendService;
      if (r && (typeof r.get === "function" || typeof r.post === "function")) { revexFound = true; break; }
    }

    // Also check nuxtApp payload keys
    let payloadKeys: string[] = [];
    if (hasUseNuxtApp) {
      try {
        const na = w.useNuxtApp();
        payloadKeys = Object.keys(na?.payload?.data ?? {}).slice(0, 20);
      } catch { /**/ }
    }

    return JSON.stringify({
      ok: true,
      hasUseNuxtApp,
      appKeys,
      revexFound,
      globalPropsKeys,
      payloadKeys,
    });
  } catch (e) {
    return JSON.stringify({ ok: false, error: "_nuxtDiag_threw: " + String(e).slice(0, 100) });
  }
}
