import { DiagnosticEntry } from "../core/schema/diagnostics";

const SESSION_KEY = "clonelevel_session";
const DIAGNOSTICS_KEY = "clonelevel_diagnostics";
const PAYLOAD_SNAPSHOTS_KEY = "clonelevel_payload_snapshots";

export interface SessionData {
  activeTabId?: number;
  activeUrl?: string;
  lastAction?: string;
  lastActionAt?: string;
}

export async function getSession(): Promise<SessionData> {
  const result = await chrome.storage.local.get(SESSION_KEY);
  return (result[SESSION_KEY] as SessionData) || {};
}

export async function updateSession(data: Partial<SessionData>): Promise<void> {
  const current = await getSession();
  await chrome.storage.local.set({ [SESSION_KEY]: { ...current, ...data } });
}

export async function clearSession(): Promise<void> {
  await chrome.storage.local.remove([
    SESSION_KEY,
    DIAGNOSTICS_KEY,
    PAYLOAD_SNAPSHOTS_KEY,
  ]);
}

export async function getDiagnostics(): Promise<DiagnosticEntry[]> {
  const result = await chrome.storage.local.get(DIAGNOSTICS_KEY);
  return (result[DIAGNOSTICS_KEY] as DiagnosticEntry[]) || [];
}

export async function addDiagnostic(entry: DiagnosticEntry): Promise<void> {
  const entries = await getDiagnostics();
  entries.push(entry);
  if (entries.length > 200) entries.splice(0, entries.length - 200);
  await chrome.storage.local.set({ [DIAGNOSTICS_KEY]: entries });
}

export async function savePayloadSnapshot(key: string, payload: unknown): Promise<void> {
  const snapshots = await getPayloadSnapshots();
  snapshots[key] = {
    payload,
    savedAt: new Date().toISOString(),
  };
  await chrome.storage.local.set({ [PAYLOAD_SNAPSHOTS_KEY]: snapshots });
}

type SnapshotMap = Record<string, { payload: unknown; savedAt: string }>;

export async function getPayloadSnapshots(): Promise<SnapshotMap> {
  const result = await chrome.storage.local.get(PAYLOAD_SNAPSHOTS_KEY);
  return (result[PAYLOAD_SNAPSHOTS_KEY] as SnapshotMap) || {};
}
