import { FunnelPage, PageTypeHint } from "../schema/funnel-map";
import { logger } from "../logger";

export interface ThumbnailPlan {
  pages: Array<{
    pageId: string;
    url: string;
    priority: number;
    strategy: "tab-capture" | "placeholder";
  }>;
}

export interface ThumbnailResult {
  pageId: string;
  dataUrl: string;
  method: "captured" | "placeholder";
  width: number;
  height: number;
}

