export interface BaseMessage {
  type: MessageType;
  id: string;
  timestamp: string;
}

export interface DetectContextMessage extends BaseMessage {
  type: "DETECT_CONTEXT";
}

export interface ContextDetectedMessage extends BaseMessage {
  type: "CONTEXT_DETECTED";
  payload: PageContext;
}

export interface CapturePublicPageMessage extends BaseMessage {
  type: "CAPTURE_PUBLIC_PAGE";
  payload: { url: string };
}

export interface CaptureNativePageMessage extends BaseMessage {
  type: "CAPTURE_NATIVE_PAGE";
  payload: { url: string };
}

export interface InspectSavePayloadMessage extends BaseMessage {
  type: "INSPECT_SAVE_PAYLOAD";
}

export interface CrawlFunnelMessage extends BaseMessage {
  type: "CRAWL_FUNNEL";
  payload: {
    rootUrl: string;
    maxDepth?: number;
    maxPages?: number;
    delayMs?: number;
    allowedDomains?: string[];
    includePatterns?: string[];
    excludePatterns?: string[];
    stripQueryStrings?: boolean;
  };
}

export interface CaptureThumbnailsMessage extends BaseMessage {
  type: "CAPTURE_THUMBNAILS";
  payload: { urls: string[] };
}

export interface ExportFunnelMapMessage extends BaseMessage {
  type: "EXPORT_FUNNEL_MAP";
}

export interface ExportAssetManifestMessage extends BaseMessage {
  type: "EXPORT_ASSET_MANIFEST";
}

export interface GetLastPackageMessage extends BaseMessage {
  type: "GET_LAST_PACKAGE";
}

export interface ClearSessionMessage extends BaseMessage {
  type: "CLEAR_SESSION";
}

export interface GetSettingsMessage extends BaseMessage {
  type: "GET_SETTINGS";
}

export interface UpdateSettingsMessage extends BaseMessage {
  type: "UPDATE_SETTINGS";
  payload: Partial<UserSettings>;
}

export interface EnableEditorInspectorMessage extends BaseMessage {
  type: "ENABLE_EDITOR_INSPECTOR";
}

export interface DisableEditorInspectorMessage extends BaseMessage {
  type: "DISABLE_EDITOR_INSPECTOR";
}

export interface GetInspectorSnapshotsMessage extends BaseMessage {
  type: "GET_INSPECTOR_SNAPSHOTS";
}

export interface ClearInspectorSnapshotsMessage extends BaseMessage {
  type: "CLEAR_INSPECTOR_SNAPSHOTS";
}

export interface GetInspectorStateMessage extends BaseMessage {
  type: "GET_INSPECTOR_STATE";
}

export interface GetBridgeStatusMessage extends BaseMessage {
  type: "GET_BRIDGE_STATUS";
}

export interface InjectTestSnapshotMessage extends BaseMessage {
  type: "INJECT_TEST_SNAPSHOT";
}

export interface ActivateBridgeDebugMessage extends BaseMessage {
  type: "ACTIVATE_BRIDGE_DEBUG";
}

export interface ActivateBridgeFallbackMessage extends BaseMessage {
  type: "ACTIVATE_BRIDGE_FALLBACK";
}

export interface InspectorBridgeAckMessage extends BaseMessage {
  type: "INSPECTOR_BRIDGE_ACK";
  payload: { timestamp: string; via: string; activated: boolean };
}

export interface GetBridgeAckMessage extends BaseMessage {
  type: "GET_BRIDGE_ACK";
}

export interface InspectorBridgeBootedMessage extends BaseMessage {
  type: "INSPECTOR_BRIDGE_BOOTED";
  payload: { ts: string; tabUrl: string; via?: string };
}

export interface InspectorPingAckMessage extends BaseMessage {
  type: "INSPECTOR_PING_ACK";
  payload: { nonce: string; ts: string; via?: string };
}

export interface GetBridgePingStatusMessage extends BaseMessage {
  type: "GET_BRIDGE_PING_STATUS";
}

export interface PingBridgeFromInspectorMessage extends BaseMessage {
  type: "PING_BRIDGE_FROM_INSPECTOR";
  payload?: { nonce?: string };
}

export interface InspectorSnapshotCapturedMessage extends BaseMessage {
  type: "INSPECTOR_SNAPSHOT_CAPTURED";
  payload: PayloadSnapshot;
}

export interface CrawlProgressMessage extends BaseMessage {
  type: "CRAWL_PROGRESS";
  payload: {
    discovered: number;
    crawled: number;
    currentUrl: string;
  };
}

export interface CrawlCompleteMessage extends BaseMessage {
  type: "CRAWL_COMPLETE";
  payload: FunnelMap;
}

export interface CaptureCompleteMessage extends BaseMessage {
  type: "CAPTURE_COMPLETE";
  payload: ClonePackage;
}

export interface ErrorMessage extends BaseMessage {
  type: "ERROR";
  payload: {
    code: string;
    message: string;
    details?: unknown;
  };
}

export interface ExtractStateMessage extends BaseMessage {
  type: "EXTRACT_STATE";
  /** Optionally target a specific tab; if absent, uses the active editor tab */
  payload?: { tabId?: number };
}

export interface GetStateExtractsMessage extends BaseMessage {
  type: "GET_STATE_EXTRACTS";
}

export interface ClearStateExtractsMessage extends BaseMessage {
  type: "CLEAR_STATE_EXTRACTS";
}

export interface GetPageSchemasMessage extends BaseMessage {
  type: "GET_PAGE_SCHEMAS";
}

export interface GetFunnelSchemasMessage extends BaseMessage {
  type: "GET_FUNNEL_SCHEMAS";
}

export interface GetSaveEventsMessage extends BaseMessage {
  type: "GET_SAVE_EVENTS";
}

export interface ClearSchemaStoreMessage extends BaseMessage {
  type: "CLEAR_SCHEMA_STORE";
}

export interface GetFunnelPackageMessage extends BaseMessage {
  type: "GET_FUNNEL_PACKAGE";
  payload: { funnelId: string };
}

export interface FetchPageLayoutMessage extends BaseMessage {
  type: "FETCH_PAGE_LAYOUT";
  payload: { pageId: string };
}

export interface GetImportCandidatesMessage extends BaseMessage {
  type: "GET_IMPORT_CANDIDATES";
}

export interface ClearImportCandidatesMessage extends BaseMessage {
  type: "CLEAR_IMPORT_CANDIDATES";
}

export interface SetImportTargetMessage extends BaseMessage {
  type: "SET_IMPORT_TARGET";
  payload: {
    tabId?: number; tabUrl?: string; pageId?: string; funnelId?: string;
    builderDetected: boolean;
  };
}

export interface GetImportTargetMessage extends BaseMessage {
  type: "GET_IMPORT_TARGET";
}

export type ExtensionMessage =
  | DetectContextMessage
  | ContextDetectedMessage
  | CapturePublicPageMessage
  | CaptureNativePageMessage
  | InspectSavePayloadMessage
  | CrawlFunnelMessage
  | CaptureThumbnailsMessage
