import type { PayloadSnapshot } from "../core/inspector/payload-schema";

const INSPECTOR_SNAPSHOTS_KEY = "clonelevel_inspector_snapshots_v2";
const MAX_SNAPSHOTS = 200;

export async function addSnapshot(snapshot: PayloadSnapshot): Promise<void> {
  const snapshots = await getAllSnapshots();
  snapshots.push(snapshot);
  if (snapshots.length > MAX_SNAPSHOTS) {
    snapshots.splice(0, snapshots.length - MAX_SNAPSHOTS);
  }
  await chrome.storage.local.set({ [INSPECTOR_SNAPSHOTS_KEY]: snapshots });
}

export async function getAllSnapshots(): Promise<PayloadSnapshot[]> {
  const result = await chrome.storage.local.get(INSPECTOR_SNAPSHOTS_KEY);
  return (result[INSPECTOR_SNAPSHOTS_KEY] as PayloadSnapshot[]) || [];
}

export async function clearSnapshots(): Promise<void> {
  await chrome.storage.local.remove(INSPECTOR_SNAPSHOTS_KEY);
}

export async function getSnapshotById(id: string): Promise<PayloadSnapshot | null> {
  const snapshots = await getAllSnapshots();
  return snapshots.find((s) => s.id === id) ?? null;
}

export function snapshotSummaryStats(snapshots: PayloadSnapshot[]): {
  total: number;
  structureHits: number;
  byMethod: Record<string, number>;
  byBuilder: Record<string, number>;
} {
  const byMethod: Record<string, number> = {};
  const byBuilder: Record<string, number> = {};
  let structureHits = 0;

  for (const s of snapshots) {
    byMethod[s.method] = (byMethod[s.method] || 0) + 1;
    byBuilder[s.builderFamily] = (byBuilder[s.builderFamily] || 0) + 1;
    if (s.looksLikeStructure) structureHits++;
  }

  return { total: snapshots.length, structureHits, byMethod, byBuilder };
}
