const ports = new Set<chrome.runtime.Port>();

export function registerInspectorPort(port: chrome.runtime.Port): void {
  ports.add(port);
  port.onDisconnect.addListener(() => {
    ports.delete(port);
  });
}

export function broadcastToInspectors(message: unknown): void {
  for (const port of ports) {
    try {
      port.postMessage(message);
    } catch {
    }
  }
}
