const KEY = "clonelevel_inspector_state";

export interface InspectorSessionState {
  enabled: boolean;
  tabId: number | null;
  editorTabId: number | null;
  lastSnapshotAt: string | null;
}

const DEFAULT: InspectorSessionState = {
  enabled: false,
  tabId: null,
  editorTabId: null,
  lastSnapshotAt: null,
};

export async function getInspectorSessionState(): Promise<InspectorSessionState> {
  const res = await chrome.storage.session.get(KEY);
  return (res[KEY] as InspectorSessionState) ?? DEFAULT;
}

export async function patchInspectorSessionState(
  patch: Partial<InspectorSessionState>
): Promise<InspectorSessionState> {
  const current = await getInspectorSessionState();
  const next = { ...current, ...patch };
  await chrome.storage.session.set({ [KEY]: next });
  return next;
}
