export function normalizeText(text: string): string {
  return text
    .replace(/\s+/g, " ")
    .trim()
    .toLowerCase();
}

export function containsAny(text: string, keywords: string[]): boolean {
  const normalized = normalizeText(text);
  return keywords.some((kw) => normalized.includes(kw.toLowerCase()));
}

export function extractTextContent(el: Element): string {
  return (el.textContent || "").trim();
}

export function truncate(text: string, maxLength: number): string {
  if (text.length <= maxLength) return text;
  return text.substring(0, maxLength) + "...";
}

export function hasClassToken(el: Element, token: string): boolean {
  return el.classList.contains(token);
}

export function hasAnyClassToken(el: Element, tokens: string[]): boolean {
  for (const t of tokens) {
    if (el.classList.contains(t)) return true;
  }
  return false;
}

export function hasClassTokenPrefix(el: Element, prefix: string): boolean {
  for (let i = 0; i < el.classList.length; i++) {
    if (el.classList[i].startsWith(prefix)) return true;
  }
  return false;
}

export function hasClassTokenContaining(el: Element, substring: string): boolean {
  for (let i = 0; i < el.classList.length; i++) {
    if (el.classList[i].includes(substring)) return true;
  }
  return false;
}

export function classTokens(el: Element): string[] {
  return Array.from(el.classList);
}
