/**
 * Import Store — Import Discovery
 *
 * Watches every captured snapshot and scores it as a candidate HighLevel
 * import/create/update/duplicate endpoint.  The top 50 candidates are
 * persisted in chrome.storage.local so the Import Workbench can display and
 * act on them without re-scanning the full snapshot archive.
 */
import type { PayloadSnapshot } from "../core/inspector/payload-schema";

// ── Storage key ───────────────────────────────────────────────────────────────
export const IMPORT_CANDIDATES_KEY  = "clonelevel_import_candidates";
export const IMPORT_TARGET_KEY      = "clonelevel_import_target";
const MAX_CANDIDATES = 50;

// ── Types ─────────────────────────────────────────────────────────────────────

export type CandidateTag =
  | "CREATE_CANDIDATE"
  | "UPDATE_CANDIDATE"
  | "IMPORT_CANDIDATE"
  | "DUPLICATE_CANDIDATE"
  | "PUBLISH_CANDIDATE"
  | "SAVE_CANDIDATE";

export interface ImportCandidate {
  id:             string;   // snapshot id
  capturedAt:     string;
  url:            string;
  method:         string;
  statusCode:     number | null;
  tag:            CandidateTag;
  score:          number;   // 0-100
  scoreBreakdown: ScoreBreakdown;
  requestBody:    string;   // raw (capped 200 KB)
  responseBody:   string;   // raw (capped 200 KB)
  contentType:    string;
  requestHeaders: Record<string, string>;  // captured auth/session headers (optional for legacy entries)
  // alias from paste.tsx normalizeCandidate — kept optional so legacy stored candidates still deserialise
  headers?: Record<string, string>;
  payloadSize:    number;
}

export interface ScoreBreakdown {
  domain:    number;
  method:    number;
  path:      number;
  bodyKeys:  number;
  bodySize:  number;
  mutation:  number;
  tag:       number;
}

export interface ImportTarget {
  tabId?:    number;
  tabUrl?:   string;
  pageId?:   string;
  funnelId?: string;
  builderDetected: boolean;
  detectedAt?: string;
}

// ── Scoring constants ─────────────────────────────────────────────────────────

const HL_DOMAINS = ["gohighlevel.com", "leadconnectorhq.com", "highlevel.com", "msgsndr.com", "app.ghl.io"];

// URL path segments that indicate a mutation/create/import action
const CREATE_SEGS   = ["/create", "/new", "/add", "/import", "/template", "/clone", "/copy"];
const UPDATE_SEGS   = ["/update", "/save", "/savepage", "/autosave", "/upsert", "/publish", "/draft"];
const DUPE_SEGS     = ["/duplicate", "/clone", "/copy"];
const IMPORT_SEGS   = ["/import", "/template"];

// URL path segments that increase relevance to page/funnel builder
const BUILDER_SEGS  = [
  "/pages", "/funnels", "/funnel", "/builder", "/elements",
  "/sections", "/rows", "/columns",
];

// JSON body keys that suggest page content being written
const PAGE_BODY_KEYS = [
  "sections", "rows", "columns", "elements", "content", "layout",
  "page", "pages", "funnel", "funnels", "steps", "nodes", "blocks",
  "html", "css", "templateId", "pageId", "funnelId",
];

// Minimum score a snapshot needs to be stored as a candidate
const MIN_SCORE = 40;

// ── Scoring logic ─────────────────────────────────────────────────────────────

function scoreSnapshot(snap: PayloadSnapshot): {
  tag: CandidateTag | null;
  score: number;
  breakdown: ScoreBreakdown;
} {
  const url    = snap.requestUrl.toLowerCase();
  const method = snap.method.toUpperCase();
  const body   = snap.requestBodyText ?? "";

  let domain  = 0;
  let methodS = 0;
  let path    = 0;
  let bodyKeys = 0;
  let bodySize = 0;
  let mutation = 0;
  let tagScore = 0;

  // 1. Domain — must be HighLevel to qualify
  if (!HL_DOMAINS.some((d) => url.includes(d))) {
    return { tag: null, score: 0, breakdown: { domain, method: methodS, path, bodyKeys, bodySize, mutation, tag: tagScore } };
  }
  domain = 30;

  // 2. Method — mutations are the primary signal
  if (method === "POST")  methodS = 25;
  else if (method === "PUT" || method === "PATCH") methodS = 20;
  else if (method === "GET") methodS = 0; // GETs excluded — they're reads not writes

  // Only consider GET if URL strongly matches an import/duplicate/create path
  if (method === "GET") {
    const hasCreatePath = [...CREATE_SEGS, ...DUPE_SEGS, ...IMPORT_SEGS].some((s) => url.includes(s));
    if (!hasCreatePath) {
      return { tag: null, score: 0, breakdown: { domain, method: methodS, path, bodyKeys, bodySize, mutation, tag: tagScore } };
    }
    methodS = 5;
  }

  // 3. Path relevance
  if (BUILDER_SEGS.some((s) => url.includes(s))) path = 15;

  // 4. Body — parse and inspect keys
  if (body && body.length > 4) {
    try {
      const parsed = JSON.parse(body);
      if (parsed && typeof parsed === "object" && !Array.isArray(parsed)) {
        const keys = Object.keys(parsed as object).map((k) => k.toLowerCase());
        const hits  = PAGE_BODY_KEYS.filter((k) => keys.some((bk) => bk.includes(k)));
        bodyKeys = Math.min(hits.length * 5, 20);
        if (body.length > 5_000) bodySize = 5;
      }
    } catch { /* non-JSON body */ }
  }

  // 5. Mutation signals (URL segment matching)
  const isDupe    = DUPE_SEGS.some((s) => url.includes(s));
  const isImport  = IMPORT_SEGS.some((s) => url.includes(s));
  const isCreate  = CREATE_SEGS.some((s) => url.includes(s));
  const isUpdate  = UPDATE_SEGS.some((s) => url.includes(s));

  if (isImport)     mutation = 15;
  else if (isDupe)  mutation = 12;
  else if (isCreate) mutation = 10;
  else if (isUpdate) mutation = 8;

  // 6. Tag + tag score
  let tag: CandidateTag | null = null;
  if (isImport)      { tag = "IMPORT_CANDIDATE";    tagScore = 10; }
  else if (isDupe)   { tag = "DUPLICATE_CANDIDATE"; tagScore = 8;  }
  else if (isCreate) { tag = "CREATE_CANDIDATE";    tagScore = 7;  }
  else if (isUpdate && (url.includes("/page") || url.includes("/funnel") || url.includes("/builder"))) {
    tag = "UPDATE_CANDIDATE"; tagScore = 6;
  } else if (url.includes("/publish")) {
    tag = "PUBLISH_CANDIDATE"; tagScore = 5;
  } else if (url.includes("/save") || url.includes("/autosave")) {
    tag = "SAVE_CANDIDATE"; tagScore = 4;
  }

  // Fallback: if method is POST + builder path, still tag as UPDATE/CREATE
  if (!tag && method === "POST" && path > 0) {
    tag = "CREATE_CANDIDATE"; tagScore = 3;
  }
  if (!tag && (method === "PUT" || method === "PATCH") && path > 0) {
    tag = "UPDATE_CANDIDATE"; tagScore = 3;
  }

  if (!tag) {
    return { tag: null, score: 0, breakdown: { domain, method: methodS, path, bodyKeys, bodySize, mutation, tag: tagScore } };
  }

  const raw   = domain + methodS + path + bodyKeys + bodySize + mutation + tagScore;
  const maxRaw = 30 + 25 + 15 + 20 + 5 + 15 + 10;
  const score = Math.round(Math.min((raw / maxRaw) * 100, 100));

  return { tag, score, breakdown: { domain, method: methodS, path, bodyKeys, bodySize, mutation, tag: tagScore } };
}

// ── Storage helpers ───────────────────────────────────────────────────────────

export async function getImportCandidates(): Promise<ImportCandidate[]> {
  const r = await chrome.storage.local.get(IMPORT_CANDIDATES_KEY);
  return Array.isArray(r[IMPORT_CANDIDATES_KEY]) ? r[IMPORT_CANDIDATES_KEY] : [];
}

export async function clearImportCandidates(): Promise<void> {
  await chrome.storage.local.remove(IMPORT_CANDIDATES_KEY);
}

export async function getImportTarget(): Promise<ImportTarget | null> {
  const r = await chrome.storage.local.get(IMPORT_TARGET_KEY);
  return r[IMPORT_TARGET_KEY] ?? null;
}

export async function setImportTarget(target: ImportTarget): Promise<void> {
  await chrome.storage.local.set({ [IMPORT_TARGET_KEY]: target });
}

// ── Learn Session Storage ─────────────────────────────────────────────────────

export const LEARN_SESSIONS_KEY = "clonelevel_learn_sessions";
const MAX_LEARN_SESSIONS = 20;

export type LearnActionType =
  | "add-section"
  | "duplicate-section"
  | "duplicate-page"
  | "delete-section"
  | "edit-text-autosave"
  | "publish"
  | "other";

export interface LearnCapturedRequest {
  url:            string;
  method:         string;
  body:           string;
  ts:             number;
  score:          number;
  scoreBreakdown: Record<string, number>;
  source:         "watcher" | "storage";
  tag?:           string;
  statusCode?:    number;
  payloadSize?:   number;
  requestBody?:   string;
  responseBody?:  string;
  id?:            string;
}

export interface LearnSession {
  id:           string;
  actionType:   LearnActionType;
  builderTabId: number;
  builderUrl:   string;
  startedAt:    string;
  completedAt:  string;
  candidates:   LearnCapturedRequest[];
  winnerUrl?:   string;
  winnerScore?: number;
  domMutations: number;
  domChanged:   boolean;
  snapBefore?:  { sectionCount: number; elementCount: number; htmlLength: number };
  snapAfter?:   { sectionCount: number; elementCount: number; htmlLength: number };
}

export async function getLearnSessions(): Promise<LearnSession[]> {
  const r = await chrome.storage.local.get(LEARN_SESSIONS_KEY);
  return Array.isArray(r[LEARN_SESSIONS_KEY]) ? r[LEARN_SESSIONS_KEY] : [];
}

export async function saveLearnSession(session: LearnSession): Promise<void> {
  const existing = await getLearnSessions();
  const merged = [session, ...existing.filter((s) => s.id !== session.id)]
    .slice(0, MAX_LEARN_SESSIONS);
  await chrome.storage.local.set({ [LEARN_SESSIONS_KEY]: merged });
}

export async function clearLearnSessions(): Promise<void> {
  await chrome.storage.local.remove(LEARN_SESSIONS_KEY);
}

// ── Main entry — called after every captured snapshot ─────────────────────────

export async function classifyForImport(snap: PayloadSnapshot): Promise<void> {
  const { tag, score, breakdown } = scoreSnapshot(snap);
  if (!tag || score < MIN_SCORE) return;

  const candidate: ImportCandidate = {
    id:             snap.id,
    capturedAt:     snap.timestamp,
    url:            snap.requestUrl,
    method:         snap.method,
    statusCode:     snap.statusCode,
    tag,
    score,
    scoreBreakdown: breakdown,
    requestBody:    (snap.requestBodyText ?? "").slice(0, 200_000),
    responseBody:   (snap.rawBody ?? "").slice(0, 200_000),
    contentType:    snap.contentType,
    requestHeaders: snap.requestHeaders ?? {},
    payloadSize:    snap.payloadSize,
  };

  const existing = await getImportCandidates();
  // De-duplicate by snapshot id
  const filtered = existing.filter((c) => c.id !== snap.id);
  // Merge and sort by score desc, keep top MAX_CANDIDATES
  const merged = [candidate, ...filtered]
    .sort((a, b) => b.score - a.score)
    .slice(0, MAX_CANDIDATES);

  await chrome.storage.local.set({ [IMPORT_CANDIDATES_KEY]: merged });
}
