import { FunnelMap } from "../core/schema/funnel-map";

const LAST_FUNNEL_MAP_KEY = "clonelevel_last_funnel_map";
const CRAWL_HISTORY_KEY = "clonelevel_crawl_history";
const MAX_HISTORY = 10;

export async function getLastFunnelMap(): Promise<FunnelMap | null> {
  const result = await chrome.storage.local.get(LAST_FUNNEL_MAP_KEY);
  return (result[LAST_FUNNEL_MAP_KEY] as FunnelMap) || null;
}

export async function saveFunnelMap(map: FunnelMap): Promise<void> {
  await chrome.storage.local.set({ [LAST_FUNNEL_MAP_KEY]: map });

  const history = await getCrawlHistory();
  history.unshift({
    rootUrl: map.rootUrl,
    crawledAt: map.crawledAt,
    pageCount: map.discoveredPages.length,
    edgeCount: map.edges.length,
  });

  if (history.length > MAX_HISTORY) {
    history.splice(MAX_HISTORY);
  }

  await chrome.storage.local.set({ [CRAWL_HISTORY_KEY]: history });
}

export interface CrawlHistoryEntry {
  rootUrl: string;
  crawledAt: string;
  pageCount: number;
  edgeCount: number;
}

export async function getCrawlHistory(): Promise<CrawlHistoryEntry[]> {
  const result = await chrome.storage.local.get(CRAWL_HISTORY_KEY);
  return (result[CRAWL_HISTORY_KEY] as CrawlHistoryEntry[]) || [];
}

export async function clearCrawlData(): Promise<void> {
  await chrome.storage.local.remove([LAST_FUNNEL_MAP_KEY, CRAWL_HISTORY_KEY]);
}
