type SendResponse = (response: unknown) => void;

// ── webRequest header buffer ───────────────────────────────────────────────────
// Stores the real headers Chrome sends for each HL API request, keyed by URL.
// Populated by chrome.webRequest.onBeforeSendHeaders in service-worker.ts.
// The JS-layer watcher only captures what the app puts in fetch(init.headers);
// auth tokens set by service workers, browser extensions, or credential stores
// won't appear there.  This buffer always has the ground-truth headers because
// it intercepts at the network layer before Chrome sends the request.

const MAX_HEADER_BUFFER = 300; // rolling window — oldest evicted first
const HEADER_BUFFER_TTL = 10 * 60 * 1000; // 10 minutes

interface HeaderBufferEntry {
  method:  string;
  headers: Record<string, string>;
  ts:      number;
}

/** url → { method, headers, ts } */
const _headerBuffer = new Map<string, HeaderBufferEntry>();

/** Header names that indicate this is a versioned HL API request worth persisting. */
const VERSION_HEADER_NAMES = new Set([
  "version", "x-version", "x-hl-version", "x-build-version",
  "x-app-version", "x-client-version", "x-api-version",
]);

function hasVersionHeaders(headers: Record<string, string>): boolean {
  return Object.keys(headers).some((k) => VERSION_HEADER_NAMES.has(k.toLowerCase()));
}

/** Storage key for the best captured HL backend request headers. Survives SW restart. */
const HL_BEST_REQUEST_KEY = "hl_best_api_request";

export function updateHeaderBuffer(url: string, method: string, rawHeaders: chrome.webRequest.HttpHeader[]): void {
  // Evict expired entries
  const now = Date.now();
  for (const [k, v] of _headerBuffer) {
    if (now - v.ts > HEADER_BUFFER_TTL) _headerBuffer.delete(k);
  }
  // Evict oldest if still over limit
  if (_headerBuffer.size >= MAX_HEADER_BUFFER) {
    const oldest = [..._headerBuffer.entries()].sort((a, b) => a[1].ts - b[1].ts)[0];
    if (oldest) _headerBuffer.delete(oldest[0]);
  }

  const headers: Record<string, string> = {};
  for (const h of rawHeaders) {
    if (h.name && h.value) headers[h.name.toLowerCase()] = h.value;
  }
  _headerBuffer.set(url, { method: method.toUpperCase(), headers, ts: now });

  // ── Persist to chrome.storage.local ────────────────────────────────────────
  // _headerBuffer is in-memory and dies on every service worker restart.
  // Whenever we see a backend.leadconnectorhq.com request WITH version headers,
  // save it to storage immediately so the Paste path can load it even after a
  // full extension reload.
  const isBackend = url.includes("backend.leadconnectorhq.com") ||
                    url.includes("services.leadconnectorhq.com");
  if (isBackend && hasVersionHeaders(headers)) {
    chrome.storage.local
      .set({ [HL_BEST_REQUEST_KEY]: { url, method: method.toUpperCase(), headers, ts: now } })
      .catch(() => {/* storage unavailable */});
    logger.info(
      "router",
      `updateHeaderBuffer: persisted HL API headers to storage — url=${url} ` +
      `versionKeys=[${Object.keys(headers).filter((k) => VERSION_HEADER_NAMES.has(k)).join(",")}]`,
    );
  }
}

async function getActiveTab(): Promise<chrome.tabs.Tab | null> {
  // Prefer the last real tab the user was on (avoids returning the extension tab)
  const real = await resolveRealTab();
  if (real) return real;
  // Final fallback
  const [tab] = await chrome.tabs.query({ active: true, currentWindow: true });
  return tab ?? null;
}

async function sendToContentScript(tabId: number, message: Record<string, unknown>): Promise<unknown> {
  return chrome.tabs.sendMessage(tabId, message);
}

/** Forward a message to the active editor tab's content script. */
async function forwardToContentScript(type: string, payload: unknown, sendResponse: SendResponse): Promise<void> {
  try {
    const state = await getInspectorSessionState();
    const targetTabId = state.editorTabId ?? null;
    if (!targetTabId) { sendResponse({ ok: false, error: "No editorTabId in session" }); return; }
    const result = await pingContentScript(targetTabId, { type, payload });
    sendResponse({ ok: result?.ok ?? false, data: result?.data, error: result?.error });
  } catch (err) {
    sendResponse({ ok: false, error: String(err) });
  }
}

/** GET_BRIDGE_RAW_LOG: ask CS to request raw log from bridge; also return last cached value. */
async function handleGetBridgeRawLog(sendResponse: SendResponse): Promise<void> {
  try {
    // Trigger the bridge to push a fresh BRIDGE_RAW_LOG (async; won't be in this response).
    const state = await getInspectorSessionState();
    const targetTabId = state.editorTabId ?? null;
    if (targetTabId) {
      pingContentScript(targetTabId, { type: "DO_GET_BRIDGE_RAW_LOG" }).catch(() => {});
    }
    // Return whatever was persisted from last BRIDGE_RAW_LOG event.
    const res = await chrome.storage.local.get("clonelevel_bridge_raw_log");
    sendResponse({ ok: true, data: res["clonelevel_bridge_raw_log"] ?? null });
  } catch (err) {
    sendResponse({ ok: false, error: String(err) });
  }
}

async function pingContentScript(tabId: number, message: Record<string, unknown>, maxAttempts = 3): Promise<any> {
  for (let attempt = 0; attempt < maxAttempts; attempt++) {
    try {
      const result = await sendToContentScript(tabId, message);
      return result;
    } catch {
      if (attempt === 0) {
        logger.info("router", "Content script not ready, injecting...");
        await chrome.scripting.executeScript({ target: { tabId }, files: ["content/bootstrap.js"] });
      }
      await new Promise((r) => setTimeout(r, 150 * (attempt + 1)));
    }
  }
  return null;
}

const PASTE_SESSION_KEY = "clonelevel_paste_session";

async function ensureBuilderConnection(tabId: number): Promise<{ ok: boolean; error?: string }> {
  // 1. Try direct ping
  try {
    const res = await chrome.tabs.sendMessage(tabId, { type: "PING_BUILDER" });
    if (res?.ok) return { ok: true };
  } catch { /* not yet injected */ }

  // 2. Inject bootstrap script
  try {
    await chrome.scripting.executeScript({ target: { tabId }, files: ["content/bootstrap.js"] });
  } catch (e) {
    return { ok: false, error: "Could not inject into builder tab. Refresh HighLevel and try again." };
  }

  // 3. Retry ping after a brief delay
  await new Promise((r) => setTimeout(r, 400));
  try {
    const res2 = await chrome.tabs.sendMessage(tabId, { type: "PING_BUILDER" });
    if (res2?.ok) return { ok: true };
  } catch { /* */ }

  return { ok: false, error: "Could not connect to the HighLevel builder. Refresh the builder tab and try again." };
}

async function findBuilderTab(): Promise<chrome.tabs.Tab | null> {
  const allTabs = await chrome.tabs.query({});
  return allTabs.find((t) => {
    if (!t.url) return false;
    const isHL   = /gohighlevel\.com|highlevel\.com|msgsndr\.com|leadconnectorhq\.com|app\.ghl\.io/.test(t.url);
    const isEdit = /\/funnel|\/page-builder|\/builder\/|funnels\/|\/pages\/|funnel-builder|page-editor|site-builder|\/edit\/|\/editor\//.test(t.url);
    return isHL && isEdit;
  }) ?? null;
}

// ── Fetch Replay ─────────────────────────────────────────────────────────────
// Replays a captured HL network request with our page content merged in.
// The captured requestHeaders include the Authorization token, so this works
// as a fully authenticated API call from the background service worker.

// ── Candidate priority sort ───────────────────────────────────────────────────
// Replay order: prebuilt-section > autosave > element-template > global-sections
function candidatePriority(url: string): number {
  const u = url.toLowerCase();
  if (u.includes("prebuilt-section"))  return 1000;
  if (u.includes("autosave"))          return 800;
  if (u.includes("element-template"))  return 600;
  if (u.includes("global-section"))    return 400;
  return 0;
}

function sortCandidatesByPriority(cands: ImportCandidate[]): ImportCandidate[] {
  return [...cands].sort((a, b) =>
    (candidatePriority(b.url) + b.score) - (candidatePriority(a.url) + a.score)
  );
}

// ── Build replay headers ──────────────────────────────────────────────────────
// Forwards captured headers verbatim except for browser-blocked (forbidden) headers
// per the Fetch Living Standard § 2.2.6 — browsers silently drop these anyway.
// Auth headers (authorization, token, x-location-id, x-builder-session-id, csrf, etc.)
// are ALWAYS preserved as-is.
const FORBIDDEN_REPLAY_HEADERS = new Set([
  // Fetch spec forbidden headers
  "accept-charset", "accept-encoding",
  "access-control-request-headers", "access-control-request-method",
  "connection", "content-length",
  "cookie", "cookie2",
  "date", "dnt", "expect",
  "host", "keep-alive",
  "origin",         // browser sets this automatically in MAIN world fetch
  "referer",        // browser manages
  "te", "trailer", "transfer-encoding", "upgrade", "via",
  "upgrade-insecure-requests",
  // All headers starting with proxy- or sec- are also forbidden (handled below via prefix check)
]);

/**
 * Returns captured headers verbatim — only browser-blocked headers are removed.
 * Preserves: authorization, token, x-location-id, x-builder-session-id, csrf headers,
 *            content-type (from capture; falls back to cand.contentType or application/json).
 *
 * @returns header audit map { headers: Record<string,string>, authKeys: string[] }
 */
function buildReplayHeaders(cand: ImportCandidate): Record<string, string> {
  // Merge both field-name variants (requestHeaders from debugger path, headers from watcher path)
  const captured: Record<string, string> = {
    ...(cand.requestHeaders ?? {}),
    ...((cand as any).headers ?? {}),
  };

  const headers: Record<string, string> = {};

  for (const [k, v] of Object.entries(captured)) {
    const kl = k.toLowerCase();
    // Drop browser-blocked headers — fetch() ignores them anyway
    if (FORBIDDEN_REPLAY_HEADERS.has(kl)) continue;
    if (kl.startsWith("proxy-") || kl.startsWith("sec-")) continue;
    if (!v) continue;       // drop empty values
    headers[kl] = v;
  }

  // Ensure content-type is always present — prefer captured value, then cand.contentType,
  // then fall back to application/json (safe default for HL builder API calls).
  if (!headers["content-type"]) {
    headers["content-type"] = cand.contentType || "application/json";
  }

  return headers;
}

/** Returns a diagnostic string listing which auth-relevant headers are present/missing. */
function auditReplayHeaders(headers: Record<string, string>): string {
  const AUTH_KEYS = [
    "authorization", "token", "x-location-id", "x-builder-session-id",
    "x-csrf-token", "x-xsrf-token", "x-session-id", "x-api-key",
    "x-user-id", "x-organization-id",
  ];
  const present = AUTH_KEYS.filter((k) => k in headers);
  const missing = AUTH_KEYS.filter((k) => !(k in headers));
  const allKeys = Object.keys(headers).sort().join(", ");
  // "Auth V" = verified present, "Auth X" = missing — matches error report format
  return (
    `total=${Object.keys(headers).length} [${allKeys}] | ` +
    `Auth V: ${present.length > 0 ? present.join(", ") : "(none)"} | ` +
    `Auth X: ${missing.length > 0 ? missing.join(", ") : "(none)"}`
  );
}

// ── Fetch relay: three-layer cascade ─────────────────────────────────────────
//
// Layer 1 — MAIN world (best):
//   executeScript({ world: "MAIN" }) injects a self-contained async function
//   directly into the HL page's JavaScript execution context.  From there the
//   fetch() call is IDENTICAL to what the HL builder itself sends:
//     • Origin header = HL page origin
//     • credentials:"include" works without CORS preflight rejection
//     • All page cookies attach automatically
//   This is the authoritative path and should succeed on any normal HL tab.
//
// Layer 2 — Content-script relay (fallback):
//   Sends REPLAY_MUTATION to the content script already injected into the tab.
//   The isolated-world fetch() shares the page cookie jar but sets the
//   extension origin; some HL API endpoints reject this via CORS.  Kept as a
//   fallback in case executeScript is blocked by a strict CSP on the tab.
//
// Layer 3 — Service-worker direct fetch (last resort):
//   No cookies, no page origin.  Will 401 on cookie-gated endpoints but may
//   succeed on header-only-auth endpoints.  Always logged as a warning.

// Layer 1: self-contained MAIN-world fetch injected via executeScript.
// ── Why MAIN world matters ─────────────────────────────────────────────────
// Fetching from the extension service-worker or content-script isolated world
// sends a chrome-extension:// Origin which backend.leadconnectorhq.com rejects.
// Injecting into MAIN world makes the request originate from the page itself
// (e.g. https://page-builder.leadconnectorhq.com), so cookies and Origin match
// exactly what the HL builder sends natively.
//
// ── Frame targeting ────────────────────────────────────────────────────────
// The HL funnel builder sometimes runs inside an iframe.  When the caller
// knows the exact frameId (captured during Learn Import Path), we target that
// frame directly so the fetch shares the same origin and cookie context as
// the request that was recorded.  If no frameId is given, we inject into ALL
// frames and pick the first one that produces a real HTTP response (status>0).
async function fetchInMainWorld(
  tabId:    number,
  frameId:  number | undefined,
  url:      string,
  method:   string,
  headers:  Record<string, string>,
  body:     string,
): Promise<{ ok: boolean; status: number; bodyText: string }> {
  // The injected function must be ENTIRELY self-contained — no closures,
  // no references to outer variables (they won't be available in MAIN world).
  const injectedFunc = async (
    u:  string,
    m:  string,
    h:  Record<string, string>,
    b:  string,
  ): Promise<{ ok: boolean; status: number; bodyText: string }> => {
    try {
      const r    = await fetch(u, { method: m, headers: h, body: b || undefined, credentials: "include" });
      const text = await r.text().catch(() => "");
      return { ok: r.ok, status: r.status, bodyText: text.slice(0, 2000) };
    } catch (err) {
      return { ok: false, status: 0, bodyText: String(err) };
    }
  };

  // Build target: prefer the known frame, fall back to all frames
  const target: chrome.scripting.InjectionTarget = frameId != null
    ? { tabId, frameIds: [frameId] }
    : { tabId, allFrames: true };

  const injected = await chrome.scripting.executeScript({
    target,
    world: "MAIN",
    func:  injectedFunc,
    args:  [url, method, headers, body],
  });

  if (!injected?.length) throw new Error("executeScript returned no results");

  // Pick the first frame result that returned a real HTTP response (status > 0).
  // A status of 0 means a network error in that frame — try the next frame.
  for (const frame of injected) {
    const r = frame.result;
    if (r && r.status > 0) return r;
  }

  // All frames returned network errors — return the first result (with its error message)
  // so the caller can log it and decide whether to fall through to Layer 2.
  const first = injected[0]?.result;
  if (!first) throw new Error("executeScript: all frames returned null");
  return first;
}

// Layer 2: content-script relay via chrome.tabs.sendMessage
async function fetchViaContentScript(
  tabId:   number,
  url:     string,
  method:  string,
  headers: Record<string, string>,
  body:    string,
): Promise<{ ok: boolean; status: number; bodyText: string }> {
  return new Promise((resolve) => {
    chrome.tabs.sendMessage(
      tabId,
      { type: "REPLAY_MUTATION", payload: { fullUrl: url, method, headers, body } },
      (result: { ok: boolean; status: number; bodyText: string } | undefined) => {
        if (chrome.runtime.lastError || !result) {
          const errMsg = chrome.runtime.lastError?.message ?? "No response from content script";
          logger.warn("router", `fetchViaContentScript: ${errMsg}`);
          resolve({ ok: false, status: 0, bodyText: errMsg });
        } else {
          resolve(result);
        }
      },
    );
  });
}

// Unified entry point — tries each layer in order, logs which one succeeded.
// frameId: the specific iframe within the tab where the builder runs.
//   When provided → Layer 1 targets that frame directly (correct origin).
//   When absent   → Layer 1 tries all frames; picks first with status > 0.
async function fetchReplayRequest(
  tabId:    number | undefined,
  frameId:  number | undefined,
  url:      string,
  method:   string,
  headers:  Record<string, string>,
  body:     string,
): Promise<{ ok: boolean; status: number; bodyText: string; fetchPath: string }> {
  if (tabId) {
    // ── Layer 1: MAIN world executeScript ──────────────────────────────────
    // This makes the fetch originate FROM the HL builder page, not the extension.
    // Origin header = page origin → no CORS rejection, session cookies included.
    try {
      const r = await fetchInMainWorld(tabId, frameId, url, method, headers, body);
      if (r.status > 0) {
        // Got a real HTTP response (even 4xx/5xx counts — that's the server talking)
        logger.info("router", `fetchReplayRequest: main-world path → ${r.status}`);
        return { ...r, fetchPath: "main-world" };
      }
      // status=0 means a network-level failure (e.g. "Failed to fetch") from every frame.
      // The MAIN world fetch failed — fall through to content-script relay.
      logger.warn("router", `fetchReplayRequest: main-world got network error (${r.bodyText.slice(0, 80)}), trying content-script`);
    } catch (err) {
      logger.warn("router", `fetchReplayRequest: main-world threw (${err}), trying content-script`);
    }

    // ── Layer 2: content-script relay ──────────────────────────────────────
    try {
      const r = await fetchViaContentScript(tabId, url, method, headers, body);
      if (r.status > 0 || r.ok) {          // got a real HTTP response (even 401 counts)
        logger.info("router", `fetchReplayRequest: content-script path → ${r.status}`);
        return { ...r, fetchPath: "content-script" };
      }
      logger.warn("router", `fetchReplayRequest: content-script returned network error: ${r.bodyText}`);
    } catch (err) {
      logger.warn("router", `fetchReplayRequest: content-script threw (${err}), falling back`);
    }
  }

  // ── Layer 3: service-worker direct (last resort, no cookies) ─────────────
  // Warning: this runs from the extension context — no page cookies, CORS may block.
  logger.warn("router", "fetchReplayRequest: service-worker fallback (no cookies — likely 401)");
  try {
    const r    = await fetch(url, { method, headers, body });
    const text = await r.text().catch(() => "");
    return { ok: r.ok, status: r.status, bodyText: text.slice(0, 2000), fetchPath: "service-worker" };
  } catch (err) {
    return { ok: false, status: 0, bodyText: String(err), fetchPath: "service-worker-error" };
  }
}

// ── Replay result type ────────────────────────────────────────────────────────
interface ReplayDetail {
  ok:                  boolean;
  verified:            boolean;
  message:             string;
  status:              number;
  responseBodyPreview: string;
  responseSize:        number;
  requestBodySize:     number;
  candidateUrl:        string;
  candidateMethod:     string;
  fetchPath?:          string;  // which relay layer delivered the response
}

// ── attemptTestSectionReplay ──────────────────────────────────────────────────
// Replays the EXACT captured request (verbatim body + verbatim headers) to verify
// that the candidate endpoint accepts our auth context.
//
// Using the verbatim body means:
//   • All original page/funnel IDs are intact — the backend can validate them against the token
//   • No risk of sending a structurally invalid payload (bad key names, missing required fields)
//   • Prebuilt-section / element-template candidates that ADD content will cause a measurable
//     DOM change that the DOM-snapshot verify step can detect
//
// Only browser-blocked headers (Fetch spec § 2.2.6) are stripped; all auth headers are forwarded.
async function attemptTestSectionReplay(
  cand: ImportCandidate,
  targetTabId?: number,
  targetFrameId?: number,
): Promise<ReplayDetail> {
  // ── Verbatim body ────────────────────────────────────────────────────────────
  // Send exactly what was captured — do NOT parse/reconstruct/append.
  // The original request was accepted by HL's backend; replaying it verbatim should
  // also be accepted, proving the auth context is correct.
  const bodyStr = cand.requestBody ?? "";

  // ── Verbatim headers (minus browser-blocked) ─────────────────────────────────
  const headers  = buildReplayHeaders(cand);
  const audit    = auditReplayHeaders(headers);

  logger.info("router", `test-replay [VERBATIM]: ${cand.method} ${cand.url}`);
  logger.info("router", `test-replay header-audit: ${audit}`);
  logger.info("router", `test-replay body: ${bodyStr.length} bytes verbatim, tabCtx=${!!targetTabId}, frameId=${targetFrameId ?? "auto"}`);

  try {
    // ── Use three-layer cascade: MAIN world → content-script → service worker
    // targetFrameId ensures injection lands in the correct iframe origin (not the top frame)
    const r = await fetchReplayRequest(targetTabId, targetFrameId, cand.url, cand.method, headers, bodyStr);
    const { ok, status, bodyText, fetchPath } = r;

    logger.info("router", `test-replay [${fetchPath}] frame=${targetFrameId ?? "auto"}: response ${status}`, { bodyPreview: bodyText.slice(0, 200) });

    return {
      ok,
      verified:            ok,
      message:             ok
        ? `Test section sent (${status}) — ${cand.method} ${cand.url}`
        : `Test section rejected (${status}) — ${bodyText.slice(0, 120)}`,
      status,
      responseBodyPreview: bodyText.slice(0, 400),
      responseSize:        bodyText.length,
      requestBodySize:     bodyStr.length,
      candidateUrl:        cand.url,
      candidateMethod:     cand.method,
      fetchPath,
    };
  } catch (err) {
    return {
      ok: false, verified: false,
      message: `Fetch error: ${String(err).slice(0, 120)}`,
      status: 0, responseBodyPreview: "", responseSize: 0,
      requestBodySize: bodyStr.length,
      candidateUrl: cand.url, candidateMethod: cand.method,
    };
  }
}

// ── attemptFetchReplay ────────────────────────────────────────────────────────
async function attemptFetchReplay(
  cand:          ImportCandidate,
  cap:           PublicPageCapture,
  targetTabId?:  number,
  targetFrameId?: number,
): Promise<ReplayDetail> {
  // Parse the original request body to understand the payload structure
  let origBody: Record<string, unknown> = {};
  try {
    origBody = JSON.parse(cand.requestBody);
  } catch {
    return { ok: false, verified: false, message: "Could not parse original request body as JSON", status: 0, responseBodyPreview: "", responseSize: 0, requestBodySize: 0, candidateUrl: cand.url, candidateMethod: cand.method };
  }

  // Identify the key that holds page sections/content
  const SECTION_KEYS = ["sections","rows","elements","columns","blocks","nodes","content","layout","steps","pages"];
  const sectionKey = SECTION_KEYS.find((k) => k in origBody && Array.isArray(origBody[k]));

  // Build minimal section objects that mirror HL's structure
  const ourSections = (cap.sections ?? []).map((sec, idx) => ({
    id:    `cl_${Date.now()}_${idx}`,
    type:  "section",
    label: sec.sectionHint || `Imported Section ${idx + 1}`,
    rows:  [],
    props: { importedBy: "clonelevel", sourceHint: sec.sectionHint },
  }));

  // Merge: keep all original body fields (IDs, metadata, etc.) but replace sections
  const newBody: Record<string, unknown> = { ...origBody };
  if (sectionKey) {
    newBody[sectionKey] = ourSections;
    logger.info("router", `fetch-replay: replacing "${sectionKey}" with ${ourSections.length} sections`);
  } else {
    newBody["sections"] = ourSections;
    newBody["importedTitle"] = cap.title;
    logger.warn("router", "fetch-replay: no known sections key found — injecting sections directly");
  }

  // Override identifiable metadata
  if ("title" in origBody || "name" in origBody) {
    const titleKey = "title" in origBody ? "title" : "name";
    newBody[titleKey] = cap.title || (origBody[titleKey] as string);
  }

  const bodyStr = JSON.stringify(newBody);
  const headers = buildReplayHeaders(cand);
  const audit   = auditReplayHeaders(headers);

  logger.info("router", `fetch-replay [MODIFIED]: ${cand.method} ${cand.url}`);
  logger.info("router", `fetch-replay header-audit: ${audit}`);
  logger.info("router", `fetch-replay body: ${bodyStr.length} bytes (${sectionKey ? `"${sectionKey}" replaced` : "sections injected"}), tabCtx=${!!targetTabId}, frameId=${targetFrameId ?? "auto"}`);

  try {
    // ── Use three-layer cascade: MAIN world → content-script → service worker
    // targetFrameId ensures injection lands in the correct iframe origin (not the top frame)
    const r = await fetchReplayRequest(targetTabId, targetFrameId, cand.url, cand.method, headers, bodyStr);
    const { ok, status, bodyText, fetchPath } = r;

    logger.info("router", `fetch-replay [${fetchPath}] frame=${targetFrameId ?? "auto"}: response ${status}`, { bodyPreview: bodyText.slice(0, 200) });

    return {
      ok,
      verified:            ok,
      message:             ok
        ? `API call succeeded (${status}) — ${cand.method} ${cand.url}. ${sectionKey ? `Replaced "${sectionKey}" with ${ourSections.length} sections.` : ""}`
        : `API call returned ${status} — ${cand.method} ${cand.url}. Body: ${bodyText.slice(0, 120)}`,
      status,
      responseBodyPreview: bodyText.slice(0, 400),
      responseSize:        bodyText.length,
      requestBodySize:     bodyStr.length,
      candidateUrl:        cand.url,
      candidateMethod:     cand.method,
      fetchPath,
    };
  } catch (err) {
    return {
      ok: false, verified: false,
      message: `Fetch error: ${String(err).slice(0, 120)}`,
      status: 0, responseBodyPreview: "", responseSize: 0,
      requestBodySize: 0, candidateUrl: cand.url, candidateMethod: cand.method,
    };
  }
}

export function handleMessage(
  message: ExtensionMessage,
  sender: chrome.runtime.MessageSender,
  sendResponse: SendResponse
): boolean {
  const tabId = sender.tab?.id;

  switch (message.type) {
    // ── Prebuilt section body capture ────────────────────────────────────────
    // Sent by bootstrap.ts when the page bridge captures a real builder request
    // to prebuilt-section/sync/changes.  Stored verbatim so PASTE_DIRECT_TO_BUILDER
    // can replay it exactly (control test) before mutating sections.
    case "SAVE_PREBUILT_REQUEST": {
      const pl = (message as any).payload ?? {};
      if (pl.reqBody) {
        const entry = { url: pl.url, method: pl.method, reqBody: pl.reqBody, statusCode: pl.statusCode, ts: pl.ts ?? Date.now() };
        chrome.storage.local.set({ hl_prebuilt_body: entry }).catch(() => {});
        logger.info("router", `SAVE_PREBUILT_REQUEST: stored ${pl.reqBody.length} chars from ${pl.url} HTTP ${pl.statusCode}`);
        sendResponse({ ok: true, stored: pl.reqBody.length });
      } else {
        sendResponse({ ok: false, error: "no reqBody in payload" });
      }
      return false;
    }

    case "CONTEXT_DETECTED":
      if (tabId) {
        setTabContext(tabId, message.payload);
        logger.info("router", `Context detected for tab ${tabId}`, message.payload);
        if (message.payload.pageType === "editor-page") {
          patchInspectorSessionState({ editorTabId: tabId }).then((state) => {
            broadcastToInspectors({ type: "STATE_UPDATE", payload: state });
          });
        }
      }
      sendResponse({ ok: true });
      return false;

    // ── Cache per-tab GHL metadata sent by clonelevel-inject.js ──────────────
    // inject.js fires GHL_PAGE_DETECTED at [0,100,300,600,1000,2000]ms on every
    // page load. We cache the best result (one with funnelId+stepId) so that
    // handleCapturePublicPage can use it without re-running executeScript.
    case "GHL_PAGE_DETECTED": {
      if (!tabId) { sendResponse({ ok: true }); return false; }
      const ghlPayload = message.payload ?? {};
      if (ghlPayload.isGhlPage && ghlPayload.pageInfo?.funnelId && ghlPayload.pageInfo?.stepId) {
        const cached = {
          funnelId:   ghlPayload.pageInfo.funnelId,
          stepId:     ghlPayload.pageInfo.stepId,
          locationId: ghlPayload.locationId ?? "",
          source:     "inject-detect",
        };
        chrome.storage.session.set({ [`ghl_tab_${tabId}`]: cached }).catch(() => {});
        logger.info("router", `GHL_PAGE_DETECTED cached for tab ${tabId}: funnelId=${cached.funnelId} stepId=${cached.stepId}`);
      }
      sendResponse({ ok: true });
      return false;
    }

    case "DETECT_CONTEXT":
      handleDetectContext(sendResponse);
      return true;

    case "GET_SETTINGS":
      getSettings().then((s) => sendResponse({ ok: true, data: s }));
      return true;

    case "UPDATE_SETTINGS":
      saveSettings(message.payload).then((s) => sendResponse({ ok: true, data: s }));
      return true;

    case "GET_LAST_PACKAGE":
      getLastPackage().then((pkg) => sendResponse({ ok: true, data: pkg }));
      return true;

    case "CAPTURE_PUBLIC_PAGE":
      handleCapturePublicPage(sendResponse);
      return true;

    case "CRAWL_FUNNEL":
      handleCrawlFunnel(message.payload, sendResponse);
      return true;

    case "EXPORT_FUNNEL_MAP":
      getLastFunnelMap().then((m) => sendResponse({ ok: true, data: m }));
      return true;

    // ── FETCH_GHL_FUNNEL_MAP ──────────────────────────────────────────────────
    // Fetches all steps of a GHL funnel via revex, using the funnelId from:
    //   1. Message payload (explicit)
    //   2. Current tab GHL detection cache (from inject.js)
    //   3. Most recent GHL capture in the library
    case "FETCH_GHL_FUNNEL_MAP": {
      (async () => {
        try {
          let funnelId: string | null = (message as any).payload?.funnelId ?? null;
          let locationId: string = (message as any).payload?.locationId ?? "";
          const payloadDomain: string = (message as any).payload?.domain ?? "";

          // Source 0: domain lookup — find funnelId from a public custom domain
          if (!funnelId && payloadDomain) {
            const allTabs = await chrome.tabs.query({});
            const hlTab = allTabs.find((t) =>
              t.url && /page-builder\.leadconnectorhq\.com|app\.gohighlevel\.com/.test(t.url)
            );
            if (hlTab?.id) {
              try {
                const hostname = payloadDomain.replace(/^https?:\/\//, "").replace(/\/.*$/, "");
                const lookupExec = await chrome.scripting.executeScript({
                  target: { tabId: hlTab.id, frameIds: [0] },
                  world:  "MAIN",
                  func:   _lookupGhlPageByDomainFunc,
                  args:   [hostname, "/"],
                });
                const lookupRaw = lookupExec?.[0]?.result;
                if (lookupRaw) {
                  const lp = JSON.parse(lookupRaw);
                  if (lp?.ok && lp.funnelId) {
                    funnelId   = lp.funnelId;
                    locationId = lp.locationId ?? "";
                    logger.info("router", `FETCH_GHL_FUNNEL_MAP: domain "${hostname}" → funnelId=${funnelId}`);
                  } else {
                    sendResponse({ ok: false, error: `Domain not found in this HL account: ${lp?.error ?? "no match"} — log: ${lp?.log ?? ""}` });
                    return;
                  }
                }
              } catch (lookupErr) {
                logger.warn("router", `domain lookup failed: ${String(lookupErr)}`);
              }
            } else {
              sendResponse({ ok: false, error: "No HighLevel builder tab is open. Open the HL page builder, then try again." });
              return;
            }
          }

          // Source 2: current tab GHL cache
          if (!funnelId) {
            const activeTab = await resolveRealTab();
            if (activeTab?.id) {
              const stored = await chrome.storage.session.get(`ghl_tab_${activeTab.id}`);
              const cached = stored[`ghl_tab_${activeTab.id}`];
              if (cached?.funnelId) { funnelId = cached.funnelId; locationId = cached.locationId ?? ""; }
            }
          }

          // Source 3: last GHL capture in library
          if (!funnelId) {
            const captures = await getPublicCaptures();
            const ghlCap = captures.find((c) => c.isGhlPage && c.ghlFunnelId);
            if (ghlCap) { funnelId = ghlCap.ghlFunnelId!; locationId = ghlCap.ghlLocationId ?? ""; }
          }

          if (!funnelId) {
            sendResponse({ ok: false, error: "No GHL funnel detected. Open a published GHL funnel page or capture one first, then try again." });
            return;
          }

          // Find an HL tab with revex access
          const allTabs = await chrome.tabs.query({});
          const builderTab = allTabs.find((t) =>
            t.url && /page-builder\.leadconnectorhq\.com|app\.gohighlevel\.com/.test(t.url)
          );
          if (!builderTab?.id) {
            sendResponse({ ok: false, error: "No HighLevel tab is open. Open the HL page builder, then try again." });
            return;
          }

          logger.info("router", `FETCH_GHL_FUNNEL_MAP: funnelId=${funnelId} via builderTab=${builderTab.id}`);
          const execResult = await chrome.scripting.executeScript({
            target: { tabId: builderTab.id, frameIds: [0] },
            world:  "MAIN",
            func:   _fetchGhlFunnelStepsFunc,
            args:   [funnelId],
          });

          const raw = execResult?.[0]?.result;
          if (!raw) { sendResponse({ ok: false, error: "No result returned from HL API" }); return; }

          const parsed = JSON.parse(raw);
          logger.info("router", `FETCH_GHL_FUNNEL_MAP: ok=${parsed.ok} steps=${parsed.steps?.length ?? 0} name=${parsed.funnelName ?? "?"}`);
          sendResponse(parsed.ok ? { ok: true, data: parsed } : { ok: false, error: parsed.error ?? "Fetch failed" });
        } catch (err) {
          sendResponse({ ok: false, error: String(err) });
        }
      })();
      return true;
    }

    case "EXPORT_ASSET_MANIFEST":
      handleExportAssetManifest(sendResponse);
      return true;

    case "CLEAR_SESSION":
      handleClearSession(sendResponse);
      return true;

    case "CAPTURE_COMPLETE":
      savePackage(message.payload).then(() => {
        addDiagnostic(createDiagnosticEntry("info", "CAPTURE_SAVED", `Package saved for ${message.payload.source.url}`));
        sendResponse({ ok: true });
      });
      return true;

    case "CRAWL_COMPLETE":
      saveFunnelMap(message.payload).then(() => {
        addDiagnostic(createDiagnosticEntry("info", "CRAWL_SAVED", `Funnel map saved: ${message.payload.discoveredPages.length} pages`));
        sendResponse({ ok: true });
      });
      return true;

    case "ENABLE_EDITOR_INSPECTOR":
      handleEnableInspector(sendResponse);
      return true;

    case "DISABLE_EDITOR_INSPECTOR":
      handleDisableInspector(sendResponse);
      return true;

    case "GET_INSPECTOR_SNAPSHOTS":
      getAllSnapshots().then((snapshots) => sendResponse({ ok: true, data: snapshots }));
      return true;

    case "CLEAR_INSPECTOR_SNAPSHOTS":
      clearSnapshots().then(() => {
        broadcastToInspectors({ type: "SNAPSHOTS_CLEARED" });
        sendResponse({ ok: true });
      });
      return true;

    case "GET_INSPECTOR_STATE":
      getInspectorSessionState().then((state) => sendResponse({ ok: true, data: state }));
      return true;

    case "GET_BRIDGE_STATUS":
      handleGetBridgeStatus(sendResponse);
      return true;

    case "INJECT_TEST_SNAPSHOT":
      handleInjectTestSnapshot(sendResponse);
      return true;

    case "ACTIVATE_BRIDGE_DEBUG":
      handleActivateBridgeDebug(sendResponse);
      return true;

    case "ACTIVATE_BRIDGE_FALLBACK":
      handleActivateBridgeFallback(sendResponse);
      return true;

    case "INSPECTOR_BRIDGE_ACK":
      handleInspectorBridgeAck(message.payload, sendResponse);
      return true;

    case "GET_BRIDGE_ACK":
      chrome.storage.local.get("clonelevel_bridge_ack").then((res) =>
        sendResponse({ ok: true, data: res["clonelevel_bridge_ack"] ?? null })
      );
      return true;

    case "INSPECTOR_BRIDGE_BOOTED":
      chrome.storage.local.set({ clonelevel_bridge_boot: message.payload }).then(() =>
        sendResponse({ ok: true })
      );
      return true;

    case "INSPECTOR_PING_ACK":
      chrome.storage.local.set({ clonelevel_bridge_ping_ack: message.payload }).then(() =>
        sendResponse({ ok: true })
      );
      return true;

    case "GET_BRIDGE_PING_STATUS":
      chrome.storage.local.get(["clonelevel_bridge_boot", "clonelevel_bridge_ping_ack"]).then((res) =>
        sendResponse({ ok: true, data: { boot: res["clonelevel_bridge_boot"] ?? null, pingAck: res["clonelevel_bridge_ping_ack"] ?? null } })
      );
      return true;

    case "PING_BRIDGE_FROM_INSPECTOR":
      handlePingBridgeFromInspector(message.payload, sendResponse);
      return true;

    case "ENABLE_DEBUG_INTERCEPT":
      forwardToContentScript("DO_ENABLE_DEBUG_INTERCEPT", null, sendResponse);
      return true;

    case "DISABLE_DEBUG_INTERCEPT":
      forwardToContentScript("DO_DISABLE_DEBUG_INTERCEPT", null, sendResponse);
      return true;

    case "MARK_SAVE_EVENT":
      forwardToContentScript("DO_MARK_SAVE_EVENT", null, sendResponse);
      return true;

    case "GET_BRIDGE_RAW_LOG":
      handleGetBridgeRawLog(sendResponse);
      return true;

    case "VERIFY_PATCHES":
      forwardToContentScript("DO_VERIFY_PATCHES", null, sendResponse);
      return true;

    case "INSPECTOR_SNAPSHOT_CAPTURED":
      handleSnapshotCaptured(message.payload, sendResponse);
      return true;

    case "CAPTURE_NATIVE_PAGE":
      sendResponse({ ok: false, error: "Native page capture is not yet implemented" });
      return false;

    case "INSPECT_SAVE_PAYLOAD":
      sendResponse({ ok: false, error: "Use ENABLE_EDITOR_INSPECTOR then trigger a save action" });
      return false;

    case "CAPTURE_THUMBNAILS":
      sendResponse({ ok: false, error: "Thumbnail capture is not yet implemented" });
      return false;

    case "ATTACH_DEBUGGER":
      handleAttachDebugger(sendResponse);
      return true;

    case "DETACH_DEBUGGER":
      handleDetachDebugger(sendResponse);
      return true;

    case "GET_DEBUGGER_STATUS":
      getDebuggerStatus().then((s) => sendResponse({ ok: true, data: s }));
      return true;

    case "MARK_SAVE_EVENT_NOW":
      setSaveMarkNow().then((ts) => sendResponse({ ok: true, data: { ts } }));
      return true;

    case "CLEAR_SAVE_MARK":
      clearSaveMark().then(() => sendResponse({ ok: true }));
      return true;

    case "EXTRACT_STATE":
      handleExtractState(message.payload?.tabId ?? null, sendResponse);
      return true;

    case "GET_STATE_EXTRACTS":
      getStateExtracts().then((data) => sendResponse({ ok: true, data }));
      return true;

    case "CLEAR_STATE_EXTRACTS":
      clearStateExtracts().then(() => sendResponse({ ok: true }));
      return true;

    case "GET_PAGE_SCHEMAS":
      getPageSchemas().then((data) => sendResponse({ ok: true, data }));
      return true;

    case "GET_FUNNEL_SCHEMAS":
      getFunnelSchemas().then((data) => sendResponse({ ok: true, data }));
      return true;

    case "GET_SAVE_EVENTS":
      getSaveEvents().then((data) => sendResponse({ ok: true, data }));
      return true;

    case "CLEAR_SCHEMA_STORE":
      clearSchemaStore().then(() => sendResponse({ ok: true }));
      return true;

    case "GET_FUNNEL_PACKAGE":
      buildFunnelPackage(message.payload.funnelId).then((pkg) =>
        sendResponse({ ok: !!pkg, data: pkg, error: pkg ? undefined : "Funnel not found" })
      );
      return true;

    case "FETCH_PAGE_LAYOUT":
      fetchAndStorePageLayout(message.payload.pageId).then((result) =>
        sendResponse(result
          ? { ok: true,  data: result.layout }
          : { ok: false, error: "No pageDataDownloadUrl found for this page — the schema may not include one" }
        )
      ).catch((err: unknown) =>
        sendResponse({ ok: false, error: String(err) })
      );
      return true;

    case "GET_IMPORT_CANDIDATES":
      getImportCandidates().then((data) => sendResponse({ ok: true, data }));
      return true;

    case "CLEAR_IMPORT_CANDIDATES":
      clearImportCandidates().then(() => sendResponse({ ok: true }));
      return true;

    case "SAVE_IMPORT_CANDIDATES": {
      // Merge incoming candidates into the persistent store (dedup by id, keep top 50 by score)
      (async () => {
        try {
          const incoming: ImportCandidate[] = (message as any).payload?.candidates ?? [];
          if (!incoming.length) { sendResponse({ ok: true, saved: 0 }); return; }
          const existing = await getImportCandidates();
          const byId = new Map(existing.map((c) => [c.id, c]));
          for (const c of incoming) {
            // Only add/update — never downgrade an existing high-score entry
            const prev = byId.get(c.id);
            if (!prev || c.score >= prev.score) byId.set(c.id, c);
          }
          const merged = [...byId.values()]
            .sort((a, b) => b.score - a.score)
            .slice(0, 50);
          await chrome.storage.local.set({ clonelevel_import_candidates: merged });
          sendResponse({ ok: true, saved: incoming.length, total: merged.length });
        } catch (err) {
          sendResponse({ ok: false, error: String(err) });
        }
      })();
      return true;
    }

    case "GET_LEARN_SESSIONS":
      getLearnSessions().then((data) => sendResponse({ ok: true, data }));
      return true;

    case "SAVE_LEARN_SESSION":
      saveLearnSession((message as any).payload).then(() => sendResponse({ ok: true }));
      return true;

    case "CLEAR_LEARN_SESSIONS":
      clearLearnSessions().then(() => sendResponse({ ok: true }));
      return true;

    case "GET_IMPORT_TARGET":
      getImportTarget().then((data) => sendResponse({ ok: true, data }));
      return true;

    case "SET_IMPORT_TARGET":
      setImportTarget({
        tabId:           message.payload.tabId,
        tabUrl:          message.payload.tabUrl,
        pageId:          message.payload.pageId,
        funnelId:        message.payload.funnelId,
        builderDetected: message.payload.builderDetected,
        detectedAt:      new Date().toISOString(),
      }).then(() => sendResponse({ ok: true }));
      return true;

    case "GET_ALL_ASSETS":
      getAllAssets().then((data) => sendResponse({ ok: true, data }));
      return true;

    case "CLEAR_ASSETS":
      clearAssets().then(() => sendResponse({ ok: true }));
      return true;

    case "SCAN_PAGE_ASSETS": {
      const pid = message.payload?.pageId;
      if (!pid) { sendResponse({ ok: false, error: "pageId required" }); return false; }
      getPageSchemas().then(async (pages) => {
        const pg = pages.find((p) => p.pageId === pid);
        if (!pg || !pg.pageLayout) { sendResponse({ ok: false, error: "Page or layout not found" }); return; }
        const count = await scanPageLayoutForAssets(pg);
        sendResponse({ ok: true, data: { count } });
      });
      return true;
    }

    case "REBUILD_ASSET_STORE":
      getPageSchemas().then(async (pages) => {
        const count = await rebuildAssetStore(pages);
        sendResponse({ ok: true, data: { count } });
      });
      return true;

    // ── Global Sections ────────────────────────────────────────────────────────
    case "GET_GLOBAL_SECTIONS":
      getGlobalSections().then((data) => sendResponse({ ok: true, data }));
      return true;

    case "CLEAR_GLOBAL_SECTIONS":
      clearGlobalSections().then(() => sendResponse({ ok: true }));
      return true;

    // ── Theme Settings ─────────────────────────────────────────────────────────
    case "GET_THEME_SETTINGS":
      getThemeSettings().then((data) => sendResponse({ ok: true, data }));
      return true;

    case "CLEAR_THEME_SETTINGS":
      clearThemeSettings().then(() => sendResponse({ ok: true }));
      return true;

    // ── Templates ──────────────────────────────────────────────────────────────
    case "GET_TEMPLATES":
      getTemplates().then((data) => sendResponse({ ok: true, data }));
      return true;

    case "CLEAR_TEMPLATES":
      clearTemplates().then(() => sendResponse({ ok: true }));
      return true;

    // ── Clear all global store ─────────────────────────────────────────────────
    case "CLEAR_GLOBAL_STORE":
      clearGlobalStore().then(() => sendResponse({ ok: true }));
      return true;

    // ── Full Clone Package (upgraded v2 format) ────────────────────────────────
    case "GET_FULL_CLONE_PACKAGE": {
      const fid = message.payload?.funnelId as string | undefined;
      Promise.all([buildFullClonePackage(fid), getAllAssets()]).then(([pkg, assets]) => {
        pkg.assets = assets;
        sendResponse({ ok: true, data: pkg });
      });
      return true;
    }

    // ── Export as Template ─────────────────────────────────────────────────────
    case "EXPORT_AS_TEMPLATE": {
      const fid2 = message.payload?.funnelId as string | undefined;
      Promise.all([buildFullClonePackage(fid2), getAllAssets()]).then(([pkg, assets]) => {
        pkg.assets    = assets;
        pkg.sourceType = "template" as any;
        const name = message.payload?.name as string | undefined;
        const exportBlob = JSON.stringify({ templateName: name ?? "CloneLevel Template", package: pkg }, null, 2);
        sendResponse({ ok: true, data: { size: exportBlob.length, json: exportBlob } });
      });
      return true;
    }

    // ── Public Clone ───────────────────────────────────────────────────────────
    case "GET_CURRENT_TAB_INFO": {
      (async () => {
        try {
          const tab = await resolveRealTab();
          if (!tab?.id || !tab.url || !isRealUrl(tab.url)) {
            sendResponse({ ok: true, data: null });
            return;
          }
          const url        = tab.url ?? "";
          const title      = tab.title ?? "";
          const favIconUrl = tab.favIconUrl ?? "";
          const isHighLevel = /gohighlevel\.com|highlevel\.com|msgsndr\.com|leadconnectorhq\.com|app\.ghl\.io/.test(url);
          const isEditor    = isHighLevel && /\/funnel|\/page-builder|\/builder\/|funnels\/|\/pages\/|funnel-builder|page-editor|site-builder|\/edit\/|\/editor\//.test(url);
          sendResponse({ ok: true, data: { tabId: tab.id, url, title, favIconUrl, isHighLevel, isEditor } });
        } catch (err) {
          sendResponse({ ok: false, error: String(err) });
        }
      })();
      return true;
    }

    case "CLONE_PUBLIC_PAGE": {
      (async () => {
        try {
          const tab = await resolveRealTab();
          if (!tab?.id) { sendResponse({ ok: false, error: "No active tab found. Navigate to a public page in your browser, then try again." }); return; }
          if (!tab.url || !isRealUrl(tab.url)) {
            sendResponse({ ok: false, error: "Cannot scrape browser or extension pages. Open a public website first." });
            return;
          }
          // Inject and run the page scraper function
          const results = await chrome.scripting.executeScript({
            target: { tabId: tab.id },
            func: () => {
              const url   = window.location.href;
              const title = document.title || "";
              const desc  = document.querySelector<HTMLMetaElement>('meta[name="description"]')?.content ?? "";
              const favicon = document.querySelector<HTMLLinkElement>('link[rel~="icon"]')?.href ?? "";

              let domain = "";
              try { domain = new URL(url).hostname; } catch { domain = ""; }

              // ── Asset collection ──────────────────────────────────────────
              const assets: Array<{url:string;type:string;alt?:string;source:string}> = [];
              const seenUrls = new Set<string>();

              // Normalise raw URL: handle protocol-relative and relative paths
              const absUrl = (u: string): string => {
                if (!u || u === "about:blank") return "";
                if (u.startsWith("//")) return "https:" + u;
                if (u.startsWith("http")) return u;
                try { return new URL(u, url).href; } catch { return ""; }
              };

              const addAsset = (raw: string, type: string, alt?: string, source?: string) => {
                const u = absUrl(raw);
                if (!u || !u.startsWith("http") || seenUrls.has(u)) return;
                seenUrls.add(u);
                assets.push({ url: u, type, alt: alt?.trim() || undefined, source: source ?? "unknown" });
              };

              // Extract all URLs from a srcset string (e.g. "img.jpg 1x, img@2x.jpg 2x")
              const parseSrcset = (srcset: string) =>
                srcset.split(",").map((s) => s.trim().split(/\s+/)[0]).filter(Boolean);

              // ── Images (all forms) ────────────────────────────────────────
              document.querySelectorAll("img").forEach((el) => {
                const img = el as HTMLImageElement;
                // currentSrc first (already resolved by browser), then src, then data-* lazy attrs
                addAsset(img.currentSrc || img.src, "image", img.alt, "img");
                for (const attr of ["data-src","data-lazy","data-lazy-src","data-original","data-url","data-image"]) {
                  const v = img.getAttribute(attr);
                  if (v) addAsset(v, "image", img.alt, `img[${attr}]`);
                }
                if (img.srcset) parseSrcset(img.srcset).forEach((u) => addAsset(u, "image", img.alt, "img[srcset]"));
              });

              // ── <picture> sources ─────────────────────────────────────────
              document.querySelectorAll("picture source").forEach((el) => {
                const src = el as HTMLSourceElement;
                if (src.srcset) parseSrcset(src.srcset).forEach((u) => addAsset(u, "image", undefined, "picture"));
                if (src.src)    addAsset(src.src, "image", undefined, "picture");
              });

              // ── Video ─────────────────────────────────────────────────────
              document.querySelectorAll("video, video source").forEach((el) => {
                const v = el as HTMLVideoElement & HTMLSourceElement;
                if (v.src)    addAsset(v.src,    "video", undefined, "video");
                if (v.poster) addAsset(v.poster, "image", undefined, "video-poster");
                const ds = v.getAttribute("data-src");
                if (ds) addAsset(ds, "video", undefined, "video[data-src]");
              });

              // ── Audio ─────────────────────────────────────────────────────
              document.querySelectorAll("audio, audio source").forEach((el) => {
                const a = el as HTMLAudioElement & HTMLSourceElement;
                if (a.src) addAsset(a.src, "audio", undefined, "audio");
              });

              // ── Background images — inline style + data-bg attrs ──────────
              const BG_URL_RE = /url\(["']?((?:https?:|\/\/)[^"')]+)["']?\)/g;
              document.querySelectorAll("[style]").forEach((el) => {
                const styleStr = el.getAttribute("style") ?? "";
                let m: RegExpExecArray | null;
                while ((m = BG_URL_RE.exec(styleStr)) !== null) addAsset(m[1], "image", undefined, "style-bg");
              });
              for (const bgAttr of ["data-bg","data-background","data-background-image","data-lazy-bg"]) {
                document.querySelectorAll(`[${bgAttr}]`).forEach((el) => {
                  addAsset(el.getAttribute(bgAttr) ?? "", "image", undefined, bgAttr);
                });
              }

              // ── Scripts ───────────────────────────────────────────────────
              document.querySelectorAll("script[src]").forEach((el) => {
                const src = (el as HTMLScriptElement).src;
                // Skip tiny GA/analytics noise — only capture meaningful scripts
                if (src && !src.includes("google-analytics") && !src.includes("gtag") && !src.includes("fbq")) {
                  addAsset(src, "script", undefined, "script");
                }
              });

              // ── Stylesheets + fonts ───────────────────────────────────────
              document.querySelectorAll('link[rel="stylesheet"], link[rel="preload"][as="style"]').forEach((el) => {
                const href = (el as HTMLLinkElement).href;
                if (!href) return;
                const type = href.includes("fonts.google") || href.includes("font") || /\.(woff2?|ttf|otf|eot)/.test(href)
                  ? "font" : "css";
                addAsset(href, type, undefined, "link");
              });
              // Inline @font-face / @import scan from <style> blocks
              document.querySelectorAll("style").forEach((el) => {
                const text = el.textContent ?? "";
                const fontRe = /url\(["']?((?:https?:|\/\/)[^"')]+\.(?:woff2?|ttf|otf|eot)[^"')']*)["']?\)/g;
                let m: RegExpExecArray | null;
                while ((m = fontRe.exec(text)) !== null) addAsset(m[1], "font", undefined, "style-font");
              });

              // Collect links
              const sameDomainLinks: Array<{url:string;text?:string;isSameDomain:boolean}> = [];
              const seenLinks = new Set<string>();
              document.querySelectorAll("a[href]").forEach((el) => {
                const a = el as HTMLAnchorElement;
                try {
                  const abs = new URL(a.href, url).href;
                  if (!abs.startsWith("http") || seenLinks.has(abs) || abs === url) return;
                  seenLinks.add(abs);
                  const isSameDomain = new URL(abs).hostname === domain;
                  sameDomainLinks.push({ url: abs, text: a.textContent?.trim().slice(0, 60), isSameDomain });
                } catch { /* ignore */ }
              });

              // Sections: top-level visual blocks
              const sectionEls = document.querySelectorAll(
                'section, [class*="section"], [class*="block"], [class*="row"], [class*="container"], main > div, article'
              );
              const sections = Array.from(sectionEls).slice(0, 30).map((el) => {
                const elCount = el.querySelectorAll("p,h1,h2,h3,img,a,button").length;
                const cls = el.className?.toString().toLowerCase() ?? "";
                let hint = "section";
                if (/hero|banner|head/.test(cls)) hint = "hero";
                else if (/cta|call.to.action|button/.test(cls)) hint = "cta";
                else if (/footer/.test(cls)) hint = "footer";
                else if (/nav|menu/.test(cls)) hint = "nav";
                else if (/testimonial|review/.test(cls)) hint = "testimonial";
                else if (/pricing|price/.test(cls)) hint = "pricing";
                else if (/faq|accordion/.test(cls)) hint = "faq";
                else if (/feature/.test(cls)) hint = "features";
                return { hint, confidence: elCount > 3 ? 0.8 : 0.5, elementCount: elCount };
              });

              return {
                url, title, description: desc, favicon,
                assets, links: sameDomainLinks, sections,
                rawHtmlSize: document.documentElement.outerHTML.length,
              };
            },
          });

          const scrapeResult = results?.[0]?.result;
          if (!scrapeResult) { sendResponse({ ok: false, error: "Scrape returned no result" }); return; }
          const capture = buildCaptureFromScrape(scrapeResult as any);

          // ── Platform / CMS detection (MAIN world) ──────────────────────────
          try {
            const cmsResult = await chrome.scripting.executeScript({
              target: { tabId: tab.id, frameIds: [0] },
              world:  "MAIN",
              func:   _detectCmsFunc,
            });
            const platform = cmsResult?.[0]?.result;
            if (platform && typeof platform === "string") {
              capture.platform = platform;
              logger.info("router", `CLONE_PUBLIC_PAGE: platform=${platform}`);
            }
          } catch (_) { /* non-fatal */ }

          // ── GHL metadata — inject cache → executeScript → CRM lookup ───────
          let ghlFound = false;

          // Path A: inject.js pre-detection cache
          try {
            const stored = await chrome.storage.session.get(`ghl_tab_${tab.id}`);
            const cached = stored[`ghl_tab_${tab.id}`];
            if (cached?.funnelId && cached?.stepId) {
              capture.isGhlPage = true; capture.ghlFunnelId = cached.funnelId;
              capture.ghlStepId = cached.stepId; capture.ghlLocationId = cached.locationId ?? "";
              if (!capture.platform) capture.platform = "HighLevel";
              ghlFound = true;
              logger.info("router", `CLONE_PUBLIC_PAGE: Path A (inject cache) funnelId=${cached.funnelId}`);
            }
          } catch (_) {}

          // Path B: executeScript _extractGhlMetadataFunc
          if (!ghlFound) {
            try {
              for (const delay of [0, 400, 1000]) {
                if (delay > 0) await new Promise((r) => setTimeout(r, delay));
                const pr = await chrome.scripting.executeScript({
                  target: { tabId: tab.id, frameIds: [0] },
                  world:  "MAIN",
                  func:   _extractGhlMetadataFunc,
                });
                const raw = pr?.[0]?.result;
                if (!raw) continue;
                const p = JSON.parse(raw);
                logger.info("router", `CLONE_PUBLIC_PAGE: Path B delay=${delay} isGhl=${p.isGhlPage} funnelId=${p.funnelId ?? "?"} log=[${p.debugLog ?? ""}]`);
                if (p.isGhlPage && p.funnelId && p.stepId) {
                  capture.isGhlPage = true; capture.ghlFunnelId = p.funnelId;
                  capture.ghlStepId = p.stepId; capture.ghlLocationId = p.locationId ?? "";
                  if (!capture.platform) capture.platform = "HighLevel";
                  ghlFound = true; break;
                }
              }
            } catch (_) { /* non-fatal */ }
          }

          // Path C: CRM domain lookup from any open HL builder tab
          if (!ghlFound && scrapeResult.url) {
            try {
              let pu: URL | null = null;
              try { pu = new URL(scrapeResult.url); } catch { /**/ }
              if (pu) {
                const allT = await chrome.tabs.query({});
                const bldr = allT.find(t => t.url && /page-builder\.leadconnectorhq\.com|app\.gohighlevel\.com/.test(t.url));
                if (bldr?.id) {
                  const lr = await chrome.scripting.executeScript({
                    target: { tabId: bldr.id, frameIds: [0] },
                    world:  "MAIN",
                    func:   _lookupGhlPageByDomainFunc,
                    args:   [pu.hostname, pu.pathname],
                  });
                  const dr = lr?.[0]?.result ? JSON.parse(lr[0].result) : null;
                  logger.info("router", `CLONE_PUBLIC_PAGE: Path C ok=${dr?.ok} funnelId=${dr?.funnelId ?? "?"} log=[${dr?.log ?? ""}]`);
                  if (dr?.ok && dr.funnelId && dr.stepId) {
                    capture.isGhlPage = true; capture.ghlFunnelId = dr.funnelId;
                    capture.ghlStepId = dr.stepId; capture.ghlLocationId = dr.locationId ?? "";
                    if (!capture.platform) capture.platform = "HighLevel";
                  }
                }
              }
            } catch (_) { /* non-fatal */ }
          }

          await storePublicCapture(capture);
          sendResponse({ ok: true, data: capture });
        } catch (err) {
          sendResponse({ ok: false, error: String(err) });
        }
      })();
      return true;
    }

    // ── CLONE_PAGE_BY_URL ─────────────────────────────────────────────────────
    // Opens any URL in a background tab, scrapes it, saves to library, closes tab.
    // Used for cloning public HL-built pages (custom domains, leadconnectorhq, etc.)
    case "CLONE_PAGE_BY_URL": {
      (async () => {
        try {
          const targetUrl = ((message as any).payload?.url as string ?? "").trim();
          if (!targetUrl || !targetUrl.startsWith("http")) {
            sendResponse({ ok: false, error: "Please enter a valid URL starting with http:// or https://" });
            return;
          }

          // Open the page in a new background tab
          const newTab = await chrome.tabs.create({ url: targetUrl, active: false });
          if (!newTab.id) { sendResponse({ ok: false, error: "Failed to open tab" }); return; }

          // Wait for the tab to finish loading (polling — survives SW termination)
          for (let i = 0; i < 60; i++) {
            await new Promise((r) => setTimeout(r, 500));
            try {
              const t = await chrome.tabs.get(newTab.id!);
              if (t.status === "complete") break;
            } catch { break; }
          }

          // Give JS a moment to render dynamic content
          await new Promise((r) => setTimeout(r, 1500));

          // Inject the same scraper as CLONE_PUBLIC_PAGE
          const results = await chrome.scripting.executeScript({
            target: { tabId: newTab.id! },
            func: () => {
              const url   = window.location.href;
              const title = document.title || "";
              const desc  = document.querySelector<HTMLMetaElement>('meta[name="description"]')?.content ?? "";
              const favicon = document.querySelector<HTMLLinkElement>('link[rel~="icon"]')?.href ?? "";
              let domain = "";
              try { domain = new URL(url).hostname; } catch { domain = ""; }

              const assets: Array<{url:string;type:string;alt?:string;source:string}> = [];
              const seenUrls = new Set<string>();
              const absUrl = (u: string): string => {
                if (!u || u === "about:blank") return "";
                if (u.startsWith("//")) return "https:" + u;
                if (u.startsWith("http")) return u;
                try { return new URL(u, url).href; } catch { return ""; }
              };
              const addAsset = (raw: string, type: string, alt?: string, source?: string) => {
                const u = absUrl(raw);
                if (!u || !u.startsWith("http") || seenUrls.has(u)) return;
                seenUrls.add(u);
                assets.push({ url: u, type, alt: alt?.trim() || undefined, source: source ?? "unknown" });
              };
              const parseSrcset = (srcset: string) =>
                srcset.split(",").map((s) => s.trim().split(/\s+/)[0]).filter(Boolean);

              document.querySelectorAll("img").forEach((el) => {
                const img = el as HTMLImageElement;
                addAsset(img.currentSrc || img.src, "image", img.alt, "img");
                for (const attr of ["data-src","data-lazy","data-lazy-src","data-original","data-url","data-image"]) {
                  const v = img.getAttribute(attr);
                  if (v) addAsset(v, "image", img.alt, `img[${attr}]`);
                }
                if (img.srcset) parseSrcset(img.srcset).forEach((u) => addAsset(u, "image", img.alt, "img[srcset]"));
              });
              document.querySelectorAll("picture source").forEach((el) => {
                const src = el as HTMLSourceElement;
                if (src.srcset) parseSrcset(src.srcset).forEach((u) => addAsset(u, "image", undefined, "picture"));
                if (src.src)    addAsset(src.src, "image", undefined, "picture");
              });
              document.querySelectorAll("video, video source").forEach((el) => {
                const v = el as HTMLVideoElement & HTMLSourceElement;
                if (v.src)    addAsset(v.src,    "video", undefined, "video");
                if (v.poster) addAsset(v.poster, "image", undefined, "video-poster");
              });
              const BG_URL_RE = /url\(["']?((?:https?:|\/\/)[^"')]+)["']?\)/g;
              document.querySelectorAll("[style]").forEach((el) => {
                const styleStr = el.getAttribute("style") ?? "";
                let m: RegExpExecArray | null;
                while ((m = BG_URL_RE.exec(styleStr)) !== null) addAsset(m[1], "image", undefined, "style-bg");
              });
              document.querySelectorAll("script[src]").forEach((el) => {
                const src = (el as HTMLScriptElement).src;
                if (src && !src.includes("google-analytics") && !src.includes("gtag")) addAsset(src, "script", undefined, "script");
              });
              document.querySelectorAll('link[rel="stylesheet"]').forEach((el) => {
                const href = (el as HTMLLinkElement).href;
                if (href) addAsset(href, "css", undefined, "link");
              });

              const sameDomainLinks: Array<{url:string;text?:string;isSameDomain:boolean}> = [];
              const seenLinks = new Set<string>();
              document.querySelectorAll("a[href]").forEach((el) => {
                const a = el as HTMLAnchorElement;
                try {
                  const abs = new URL(a.href, url).href;
                  if (!abs.startsWith("http") || seenLinks.has(abs) || abs === url) return;
                  seenLinks.add(abs);
                  sameDomainLinks.push({ url: abs, text: a.textContent?.trim().slice(0, 60), isSameDomain: new URL(abs).hostname === domain });
                } catch { /**/ }
              });

              const sectionEls = document.querySelectorAll('section, [class*="section"], [class*="block"], [class*="row"], main > div, article');
              const sections = Array.from(sectionEls).slice(0, 30).map((el) => {
                const elCount = el.querySelectorAll("p,h1,h2,h3,img,a,button").length;
                const cls = el.className?.toString().toLowerCase() ?? "";
                let hint = "section";
                if (/hero|banner/.test(cls)) hint = "hero";
                else if (/footer/.test(cls)) hint = "footer";
                else if (/cta|call.to.action/.test(cls)) hint = "cta";
                return { hint, confidence: elCount > 3 ? 0.8 : 0.5, elementCount: elCount };
              });

              return { url, title, description: desc, favicon, assets, links: sameDomainLinks, sections, rawHtmlSize: document.documentElement.outerHTML.length };
            },
          });

          // Close the background tab
          try { await chrome.tabs.remove(newTab.id!); } catch { /**/ }

          const scrapeResult = results?.[0]?.result;
          if (!scrapeResult) { sendResponse({ ok: false, error: "Scrape returned no data — page may have blocked script injection" }); return; }
          const capture = buildCaptureFromScrape(scrapeResult as any);
          await storePublicCapture(capture);
          logger.info("router", `CLONE_PAGE_BY_URL: saved captureId=${capture.captureId} from ${targetUrl}`);
          sendResponse({ ok: true, data: capture });
        } catch (err) {
          logger.error("router", `CLONE_PAGE_BY_URL threw: ${String(err)}`);
          sendResponse({ ok: false, error: String(err) });
        }
      })();
      return true;
    }

    case "CLONE_PUBLIC_FUNNEL":
      sendResponse({ ok: true, data: { message: "Funnel detection starting — trigger CLONE_PUBLIC_PAGE on each linked page." } });
      return false;

    case "GET_PUBLIC_CAPTURES":
      getPublicCaptures().then((data) => sendResponse({ ok: true, data }));
      return true;

    case "CLEAR_PUBLIC_CAPTURES":
      clearPublicCaptures().then(() => sendResponse({ ok: true }));
      return true;

    case "PING_BUILDER": {
      (async () => {
        try {
          const builderTab = await findBuilderTab();
          if (!builderTab?.id) {
            sendResponse({ ok: false, error: "No HighLevel builder tab found." });
            return;
          }
          const conn = await ensureBuilderConnection(builderTab.id);
          sendResponse({ ok: conn.ok, data: conn.ok ? { tabId: builderTab.id, url: builderTab.url, title: builderTab.title } : null, error: conn.error });
        } catch (err) {
          sendResponse({ ok: false, error: String(err) });
        }
      })();
      return true;
    }

    // ── GET_IMPORT_ENGINE_STATUS ────────────────────────────────────────────────
    // Single shared status model read by popup, workbench, and executor.
    // Returns mode + readiness + candidate counts so every surface stays in sync.
    case "GET_IMPORT_ENGINE_STATUS": {
      (async () => {
        try {
          const allCandidates  = await getImportCandidates();
          const allCaptures    = await getPublicCaptures();
          const builderTab     = await findBuilderTab().catch(() => null);

          const dispatchCandidates = allCandidates.filter(
            (c) => (c as any).source === "runtime-dispatch" || !!(c as any).dispatchActionType
          );
          const networkCandidates  = allCandidates.filter(
            (c) => (c as any).source !== "runtime-dispatch" && !(c as any).dispatchActionType
          );

          let mode: string;
          let available: boolean;
          let reasonIfUnavailable = "";

          if (dispatchCandidates.length > 0) {
            mode      = "runtime-dispatch";
            available = true;
          } else if (networkCandidates.length > 0) {
            mode      = "learned-replay";
            available = true;
          } else {
            mode               = "not-configured";
            available          = false;
            reasonIfUnavailable = "No import path learned yet. Open the Debug Workbench and run \"Learn Import Path\" while the page builder is open.";
          }

          const best = sortCandidatesByPriority(allCandidates)[0] ?? null;
          sendResponse({
            ok:   true,
            data: {
              mode,
              available,
              reasonIfUnavailable,
              activeCandidateId:      best?.id ?? null,
              activeCandidateTag:     (best as any)?.tag ?? null,
              builderConnected:       !!builderTab?.id,
              builderTabTitle:        builderTab?.title ?? null,
              candidateCount:         allCandidates.length,
              dispatchCandidateCount: dispatchCandidates.length,
              networkCandidateCount:  networkCandidates.length,
              libraryCount:           allCaptures.length,
            },
          });
        } catch (err) {
          sendResponse({ ok: false, error: String(err) });
        }
      })();
      return true;
    }

    // ── GET_HEADER_BUFFER ──────────────────────────────────────────────────────
    // Returns headers buffered by onBeforeSendHeaders for the requested URLs.
    // Called by paste.tsx finalize() to enrich watcher candidates that had
    // empty requestHeaders (because the JS watcher couldn't see auth headers
    // that HL adds outside of fetch(init.headers), e.g. from service workers).
    case "GET_HEADER_BUFFER": {
      try {
        const urls: string[] = (message as any).payload?.urls ?? [];
        const result: Record<string, { headers: Record<string, string>; method: string }> = {};
        const now = Date.now();
        for (const url of urls) {
          const entry = _headerBuffer.get(url);
          if (entry && (now - entry.ts) < HEADER_BUFFER_TTL) {
            result[url] = { headers: entry.headers, method: entry.method };
          }
        }
        sendResponse({ ok: true, data: result });
      } catch (err) {
        sendResponse({ ok: false, error: String(err) });
      }
      return false; // sync
    }

    // ── COPY_PAGE ────────────────────────────────────────────────────────────────
    // Reads funnel + step identity from the current HL page via Nuxt's payload.
    // Stores result in chrome.storage.session under "cl_copied_page".
    case "COPY_PAGE": {
      (async () => {
        try {
          const cpTabId = tabId ?? (await chrome.tabs.query({ active: true, currentWindow: true }))[0]?.id;
          if (!cpTabId) { sendResponse({ ok: false, error: "no_active_tab" }); return; }
          // First try getFunnelInfo from the Nuxt payload (funnel overview page)
          let res = await chrome.scripting.executeScript({
            target: { tabId: cpTabId, allFrames: false },
            world:  "MAIN",
            func:   _nuxtGetFunnelInfoFunc,
          });
          let info: any = {};
          try { info = JSON.parse(res?.[0]?.result ?? "{}"); } catch { /**/ }

          // If that failed, try to extract from URL and use revexGetBuilderInfo
          if (!info.ok) {
            const tab = await chrome.tabs.get(cpTabId);
            const url  = tab.url ?? "";
            // Pattern: /location/{locId}/page-builder/{pageBuilderOrFunnelId}
            const m = url.match(/\/location\/([^/]+)\/page-builder\/([^/]+)/);
            if (m) {
              const [, locationId, builderId] = m;
              const res2 = await chrome.scripting.executeScript({
                target: { tabId: cpTabId, allFrames: false },
                world:  "MAIN",
                func:   _revexGetBuilderInfoFunc,
                args:   [builderId],
              });
              let info2: any = {};
              try { info2 = JSON.parse(res2?.[0]?.result ?? "{}"); } catch { /**/ }
              if (info2.ok) {
                info = { ...info2, locationId: info2.locationId || locationId, builderId };
              } else {
                info = { ok: false, error: info2.error ?? "revexGetBuilderInfo failed", locationId, builderId };
              }
            } else {
              info.urlNote = "URL did not match /page-builder/ pattern; try on funnel overview page";
            }
          }

          if (info.ok) {
            await chrome.storage.session.set({ cl_copied_page: info });
            logger.info("router", `COPY_PAGE: stored funnelId=${info.funnelId} stepId=${info.stepId}`);
            sendResponse({ ok: true, info });
          } else {
            logger.warn("router", `COPY_PAGE: failed — ${info.error}`);
            sendResponse({ ok: false, error: info.error, info });
          }
        } catch (err) {
          logger.error("router", `COPY_PAGE threw: ${String(err)}`);
          sendResponse({ ok: false, error: String(err) });
        }
      })();
      return true;
    }

    // ── PASTE_PAGE ───────────────────────────────────────────────────────────────
    // Clones the copied page into the currently open builder page using
    // revexBackendService.post('/funnels/funnel/clone-funnel-step/', ...).
    case "PASTE_PAGE": {
      (async () => {
        try {
          const ppTabId = tabId ?? (await chrome.tabs.query({ active: true, currentWindow: true }))[0]?.id;
          if (!ppTabId) { sendResponse({ ok: false, error: "no_active_tab" }); return; }

          // Retrieve what was copied
          const stor = await chrome.storage.session.get("cl_copied_page");
          const src: any = stor.cl_copied_page;
          if (!src?.funnelId || !src?.stepId) {
            sendResponse({ ok: false, error: "Nothing copied yet — use Copy Page first", src });
            return;
          }

          // Get destination info from current tab URL
          const ppTab = await chrome.tabs.get(ppTabId);
          const url = ppTab.url ?? "";
          const m = url.match(/\/location\/([^/]+)\/page-builder\/([^/]+)/);
          if (!m) {
            sendResponse({ ok: false, error: "Current tab is not a /page-builder/ URL — navigate to the destination page first" });
            return;
          }
          const [, locationId, builderId] = m;

          // Read destination funnelId + stepId from builder via revex.get
          const destRes = await chrome.scripting.executeScript({
            target: { tabId: ppTabId, allFrames: false },
            world:  "MAIN",
            func:   _revexGetBuilderInfoFunc,
            args:   [builderId],
          });
          let dest: any = {};
          try { dest = JSON.parse(destRes?.[0]?.result ?? "{}"); } catch { /**/ }

          if (!dest.ok) {
            sendResponse({ ok: false, error: `Could not read destination page: ${dest.error}`, dest });
            return;
          }

          // Build the clone request
          const req = {
            sourceFunnelId: src.funnelId,
            sourceStepId:   src.stepId,
            destFunnelId:   dest.funnelId,
            destStepId:     dest.stepId,
            locationId:     dest.locationId || locationId,
          };

          logger.info("router", `PASTE_PAGE: cloning ${req.sourceFunnelId}/${req.sourceStepId} → ${req.destFunnelId}/${req.destStepId}`);

          // Perform the clone
          const cloneRes = await chrome.scripting.executeScript({
            target: { tabId: ppTabId, allFrames: false },
            world:  "MAIN",
            func:   _revexCloneFunnelStepFunc,
            args:   [req],
          });
          let cloneResult: any = {};
          try { cloneResult = JSON.parse(cloneRes?.[0]?.result ?? "{}"); } catch { /**/ }

          if (cloneResult.ok) {
            // Refresh the builder iframe so the cloned page renders
            await chrome.scripting.executeScript({
              target: { tabId: ppTabId, allFrames: false },
              world:  "MAIN",
              func:   _refreshBuilderIframeFunc,
            });
            logger.info("router", `PASTE_PAGE: success — ${cloneResult.raw?.slice(0, 80)}`);
            sendResponse({ ok: true, req, cloneResult });
          } else {
            logger.warn("router", `PASTE_PAGE: clone failed — ${cloneResult.error}`);
            sendResponse({ ok: false, error: cloneResult.error, req, cloneResult });
          }
        } catch (err) {
          logger.error("router", `PASTE_PAGE threw: ${String(err)}`);
          sendResponse({ ok: false, error: String(err) });
        }
      })();
      return true;
    }

    // ── GET_COPIED_PAGE ───────────────────────────────────────────────────────────
    // Returns the currently stored copied page info.
    case "GET_COPIED_PAGE": {
      (async () => {
        const stor = await chrome.storage.session.get("cl_copied_page");
        sendResponse({ ok: true, data: stor.cl_copied_page ?? null });
      })();
      return true;
    }

    // ── PASTE_DIRECT_TO_BUILDER ─────────────────────────────────────────────────
    // Single deterministic insertion primitive — no setup, no learning required.
    //
    // ONE method:  POST /funnels/builder/prebuilt-section/sync/changes
    // ONE context: Extension service worker (bypasses CORS, full host_permissions)
    // ONE auth:    chrome.cookies.getAll() — reads httpOnly session cookies
    // ONE payload: { sections, pageId?, funnelId? }
    // ONE verify:  response.ok
    //
    // Why service worker, not MAIN world:
    //   - MAIN world fetch to backend.leadconnectorhq.com from app.gohighlevel.com
    //     is blocked by CORS (TypeError: Failed to fetch).
    //   - HL stores its auth JWT in httpOnly cookies, invisible to document.cookie
    //     and localStorage.  Only chrome.cookies can read them.
    //   - Extension service workers have host_permissions:<all_urls>, so fetch
    //     calls are not subject to CORS restrictions.
    case "PASTE_DIRECT_TO_BUILDER": {
      (async () => {
        try {
          const msgPayload = (message as any).payload ?? {};
          const captureId  = msgPayload.captureId as string | undefined;

          // ── Step 1: Find active HL builder tab ─────────────────────────────
          const builderTab = await findBuilderTab();
          if (!builderTab?.id || !builderTab.url) {
            sendResponse({
              ok: false,
              error: "No HighLevel page builder tab found. Open the page builder in Chrome first, then paste.",
            });
            return;
          }
          const tabUrl = builderTab.url;

          // ── Step 2: Extract page context from the tab URL ──────────────────
          // HL builder URLs: .../location/{locId}/funnels/{funnelId}/...
          //                  .../location/{locId}/page-builder/{pageId}
          const locationId = tabUrl.match(/\/location\/([a-zA-Z0-9_-]{6,})/i)?.[1] ?? "";
          const funnelId   = tabUrl.match(/\/funnels?\/([a-zA-Z0-9_-]{6,})/i)?.[1] ?? "";
          const pageId     = tabUrl.match(/\/(?:pages?|steps?|page-builder)\/([a-zA-Z0-9_-]{6,})/i)?.[1] ?? "";

          logger.info(
            "router",
            `PASTE_DIRECT_TO_BUILDER: tabUrl=${tabUrl} ` +
            `locationId=${locationId || "(none)"} funnelId=${funnelId || "(none)"} pageId=${pageId || "(none)"}`,
          );

          // ── Step 3: Resolve source capture ─────────────────────────────────
          const captures = await getPublicCaptures();
          const cap = captureId
            ? captures.find((c) => c.captureId === captureId)
            : captures[captures.length - 1];
          if (!cap) {
            sendResponse({ ok: false, error: "No saved page in library. Capture a page first, then paste." });
            return;
          }

          const isGhlCapture = !!(cap as any).isGhlPage && !!(cap as any).ghlFunnelId && !!(cap as any).ghlStepId;
          logger.info(
            "router",
            `PASTE_DIRECT_TO_BUILDER: captureId=${cap.captureId} sections=${(cap.sections ?? []).length} ` +
            `isGhlCapture=${isGhlCapture} ghlFunnelId=${(cap as any).ghlFunnelId ?? "(none)"} ` +
            `ghlStepId=${(cap as any).ghlStepId ?? "(none)"} ` +
            `pageId=${pageId || "(none)"} locationId=${locationId || "(none)"}`,
          );

          // ── Step 4: Paste via executeScript in MAIN world (no content script needed) ─
          // For GHL captures: use clone-funnel-step (SmartCloner's exact method).
          // executeScript does NOT require the content script to already be running.
          let pasteResult: any = {};

          try {
            if (isGhlCapture) {
              // GHL path: clone-funnel-step via _cloneFromGhlCaptureFunc (uses revex)
              logger.info("router", `PASTE: GHL clone-funnel-step — srcFunnel=${(cap as any).ghlFunnelId} srcStep=${(cap as any).ghlStepId}`);
              const injectRes = await chrome.scripting.executeScript({
                target: { tabId: builderTab.id!, frameIds: [0] },
                world:  "MAIN",
                func:   _cloneFromGhlCaptureFunc,
                args:   [
                  (cap as any).ghlFunnelId,
                  (cap as any).ghlStepId,
                  pageId,
                  locationId,
                ],
              });
              const raw = injectRes?.[0]?.result;
              try { pasteResult = JSON.parse(raw ?? "{}"); }
              catch { pasteResult = { ok: false, error: "parse_failed", raw }; }
            } else {
              // No GHL metadata — nothing we can paste
              pasteResult = {
                ok: false,
                error: "No GHL data — capture this page with the extension open, then paste. If the page is not a GHL funnel, it cannot be pasted.",
              };
            }
          } catch (injectErr) {
            pasteResult = { ok: false, error: `executeScript failed: ${String(injectErr).slice(0, 200)}` };
          }

          logger.info(
            "router",
            `PASTE_DIRECT_TO_BUILDER: ok=${pasteResult.ok} HTTP=${pasteResult.status ?? "?"} ` +
            `strategy=${pasteResult.strategy ?? "?"} saveUrl=${pasteResult.saveUrl ?? "?"} ` +
            `destFunnelId=${pasteResult.destFunnelId ?? "?"} destStepId=${pasteResult.destStepId ?? "?"} ` +
            `userId=${pasteResult.userId ?? "?"} ` +
            `sectionsPath=${pasteResult.sectionsPath ?? "?"} added=${pasteResult.addedSections ?? "?"} ` +
            `existing=${pasteResult.existingSections ?? "?"} pageDataKeys=[${pasteResult.pageDataKeys ?? ""}] ` +
            `bodyKeys=[${pasteResult.bodyKeys ?? ""}]`,
          );
          if (pasteResult.sampleSection) {
            logger.info("router", `PASTE_DIRECT_TO_BUILDER: sampleSection=${pasteResult.sampleSection}`);
          }
          if (pasteResult.attempts) {
            logger.warn("router", `PASTE_DIRECT_TO_BUILDER: attempts=${JSON.stringify(pasteResult.attempts).slice(0, 400)}`);
          }

          if (pasteResult.ok) {
            // Reload the builder tab so it re-fetches the updated page from the server.
            // The prebuilt-section API saves directly to the backend; the builder's
            // in-memory Vue state doesn't update automatically — a reload is required.
            try {
              await chrome.tabs.reload(builderTab.id!);
            } catch (reloadErr) {
              logger.warn("router", `PASTE_DIRECT_TO_BUILDER: tab reload failed — ${String(reloadErr)}`);
            }

            sendResponse({
              ok:           true,
              strategy:     pasteResult.strategy ?? "revex",
              status:       pasteResult.status,
              captureTitle: cap.title || cap.domain || "Captured Page",
              added:        pasteResult.addedSections,
              existing:     pasteResult.existingSections,
            });
            return;
          }

          // Build a readable error including what each endpoint returned
          const attemptsSummary = Array.isArray(pasteResult.attempts)
            ? pasteResult.attempts.map((a: any) =>
                `${(a.method ?? "?").toUpperCase()} ${a.url ?? "?"}→HTTP${a.status ?? "?"}${a.msg ? ":"+String(a.msg).slice(0,40) : ""}`
              ).join(" | ")
            : "";

          sendResponse({
            ok:           false,
            status:       pasteResult.status,
            error:        attemptsSummary
              ? `${pasteResult.error ?? "Failed"} — ${attemptsSummary}`
              : (pasteResult.error ?? `HTTP ${pasteResult.status ?? "?"}: ${JSON.stringify(pasteResult.data ?? "").slice(0, 150)}`),
            canOpenDebug: true,
          });
        } catch (err) {
          logger.error("router", `PASTE_DIRECT_TO_BUILDER threw: ${String(err)}`);
          sendResponse({ ok: false, error: String(err), canOpenDebug: true });
        }
      })();
      return true;
    }

    // ── Runtime probe: inject dispatch spy into MAIN world ────────────────────
    // Discovers the Redux store via React DevTools hook, window globals, and DOM
    // scan, then wraps store.dispatch so every dispatched action is recorded in
    // window.__cl_runtime.dispatched.  Safe to call multiple times — idempotent.
    case "PROBE_BUILDER_RUNTIME": {
      (async () => {
        try {
          const pl     = (message as any).payload ?? {};
          const tabId  = pl.tabId  as number | undefined;
          const frameId = pl.frameId as number | undefined;

          // Auto-detect builder tab if tabId not provided
          let resolvedTabId = tabId;
          if (!resolvedTabId) {
            const bt = await findBuilderTab();
            resolvedTabId = bt?.id;
          }
          if (!resolvedTabId) {
            sendResponse({ ok: false, error: "No builder tab found — open HL page builder first." });
            return;
          }

          const probeResults: string[] = [];

          // Inject into top frame (frameId 0) — covers cases where builder is
          // embedded directly in the top document.
          try {
            const r = await chrome.scripting.executeScript({
              target: { tabId: resolvedTabId, frameIds: [0] },
              world:  "MAIN",
              func:   _builderRuntimeProbeFunc,
            });
            probeResults.push(`top:${r?.[0]?.result ?? "no_result"}`);
          } catch (e) {
            probeResults.push(`top:err:${String(e).slice(0, 60)}`);
          }

          // Also inject into the specific builder frame if known
          if (frameId != null && frameId !== 0) {
            try {
              const r = await chrome.scripting.executeScript({
                target: { tabId: resolvedTabId, frameIds: [frameId] },
                world:  "MAIN",
                func:   _builderRuntimeProbeFunc,
              });
              probeResults.push(`frame${frameId}:${r?.[0]?.result ?? "no_result"}`);
            } catch (e) {
              probeResults.push(`frame${frameId}:err:${String(e).slice(0, 60)}`);
            }
          }

          // Auto-discover builder frame if not provided
          if (!frameId) {
            try {
              const frames = await chrome.webNavigation.getAllFrames({ tabId: resolvedTabId }) ?? [];
              const builderFrame = frames.find((f) =>
                /leadconnectorhq\.com|gohighlevel\.com|msgsndr\.com/.test(f.url ?? "") &&
                /builder|editor|funnel|page/.test(f.url ?? "") &&
                f.frameId !== 0
              );
              if (builderFrame) {
                try {
                  const r = await chrome.scripting.executeScript({
                    target: { tabId: resolvedTabId, frameIds: [builderFrame.frameId] },
                    world:  "MAIN",
                    func:   _builderRuntimeProbeFunc,
                  });
                  probeResults.push(`auto-frame${builderFrame.frameId}:${r?.[0]?.result ?? "no_result"}`);
                } catch (e) {
                  probeResults.push(`auto-frame${builderFrame.frameId}:err:${String(e).slice(0, 60)}`);
                }
              }
            } catch { /* webNavigation might not be ready */ }
          }

          const storeFound = probeResults.some((r) => r.includes("store:") && !r.includes("no_store"));
          logger.info("router", `PROBE_BUILDER_RUNTIME: ${probeResults.join(" | ")}`);
          sendResponse({ ok: true, storeFound, probeResults });
        } catch (err) {
          logger.error("router", `PROBE_BUILDER_RUNTIME threw: ${String(err)}`);
          sendResponse({ ok: false, error: String(err) });
        }
      })();
      return true;
    }

    // ── TEST_INJECT: state-introspect + dispatch test section ─────────────────
    case "TEST_INJECT": {
      (async () => {
        try {
          const pl    = (message as any).payload ?? {};
          const tabId = pl.tabId as number | undefined;

          let resolvedTabId = tabId;
          if (!resolvedTabId) {
            const bt = await findBuilderTab();
            resolvedTabId = bt?.id;
          }
          if (!resolvedTabId) {
            sendResponse({ ok: false, error: "No builder tab found — open HL page builder first.", frames: [] });
            return;
          }

          // ── Enumerate ALL frames in the tab ────────────────────────────────
          interface FrameInfo { frameId: number; url: string; parentFrameId: number; }
          let allFrames: FrameInfo[] = [{ frameId: 0, url: "", parentFrameId: -1 }];
          try {
            const nav = await chrome.webNavigation.getAllFrames({ tabId: resolvedTabId }) ?? [];
            allFrames = nav.map((f) => ({ frameId: f.frameId, url: f.url ?? "", parentFrameId: f.parentFrameId ?? -1 }));
          } catch { /* webNavigation might not be ready — use top frame only */ }

          // ── Per-frame diagnostic record ────────────────────────────────────
          interface FrameDiag {
            frameId:        number;
            url:            string;
            parentFrameId:  number;
            injectionOk:    boolean;
            probeRaw:       string;
            // Redux path
            storeFound:     boolean;
            storeType:      string;
            insertRaw:      string;
            sectionsFound:  boolean;
            sectionsPath:   string;
            capturedCount:  number;
            capturedTypes:  string[];
            templateShape:  string;
            stateKeys:      string[];
            tried:          number;
            failureReason:  string;
            insertOk:       boolean;
            actionType:     string;
            countBefore:    number;
            countAfter:     number;
            // Fiber path
            fiberRaw:       string;
            framework:      string;
            hasAngular:     boolean;
            hasVue:         boolean;
            fiberInjectOk:  boolean;
            fiberMethod:    string;
            fiberError:     string;
            fiberCount:     string;
            fiberStateSnap: string[];
            notableGlobals: string[];
          }

          async function diagnoseFrame(fi: FrameInfo): Promise<FrameDiag> {
            const diag: FrameDiag = {
              frameId: fi.frameId, url: fi.url, parentFrameId: fi.parentFrameId,
              injectionOk: false, probeRaw: "", storeFound: false, storeType: "",
              insertRaw: "", sectionsFound: false, sectionsPath: "", capturedCount: 0,
              capturedTypes: [], templateShape: "", stateKeys: [], tried: 0,
              failureReason: "not_run", insertOk: false, actionType: "",
              countBefore: 0, countAfter: 0,
              // fiber
              fiberRaw: "", framework: "unknown", hasAngular: false, hasVue: false,
              fiberInjectOk: false, fiberMethod: "", fiberError: "",
              fiberCount: "", fiberStateSnap: [], notableGlobals: [],
            };

            // ── Step 1: MAIN-world injection check ──────────────────────────
            try {
              const pr = await chrome.scripting.executeScript({
                target: { tabId: resolvedTabId!, frameIds: [fi.frameId] },
                world:  "MAIN",
                func:   _builderRuntimeProbeFunc,
              });
              diag.probeRaw    = String(pr?.[0]?.result ?? "no_result");
              diag.injectionOk = true;
            } catch (e) {
              diag.probeRaw      = "injection_failed:" + String(e).slice(0, 120);
              diag.failureReason = "injection_failed";
              return diag;
            }

            // Parse Redux probe string
            const pr = diag.probeRaw;
            if (pr.startsWith("store:") || pr === "already_active") {
              diag.storeFound = true;
              const m = pr.match(/^store:([^:]+)/);
              diag.storeType = m ? m[1] : "unknown";
            }

            // ── Step 2: Redux insert test ────────────────────────────────────
            let insertJson = "";
            try {
              const ir = await chrome.scripting.executeScript({
                target: { tabId: resolvedTabId!, frameIds: [fi.frameId] },
                world:  "MAIN",
                func:   _insertTestSectionFunc,
              });
              insertJson     = String(ir?.[0]?.result ?? "{}");
              diag.insertRaw = insertJson;
            } catch (e) {
              diag.insertRaw = "injection_failed:" + String(e).slice(0, 120);
            }

            let ins: any = {};
            try { ins = JSON.parse(insertJson); } catch { ins = {}; }

            diag.insertOk      = !!ins.ok;
            diag.capturedCount = (ins.capturedTypes ?? []).length;
            diag.capturedTypes = ins.capturedTypes ?? [];
            diag.stateKeys     = ins.stateKeys ?? [];
            diag.templateShape = ins.templateShape ?? "";
            diag.tried         = ins.tried ?? 0;

            if (ins.ok) {
              diag.actionType    = ins.actionType ?? "";
              diag.sectionsFound = true;
              diag.sectionsPath  = ins.path ?? "";
              diag.countBefore   = ins.countBefore ?? 0;
              diag.countAfter    = ins.countAfter ?? 0;
              diag.failureReason = "";
              return diag; // Redux succeeded — no need to run fiber
            }

            // ── Step 3: React fiber inject test (always runs) ────────────────
            let fiberJson = "";
            try {
              const fr = await chrome.scripting.executeScript({
                target: { tabId: resolvedTabId!, frameIds: [fi.frameId] },
                world:  "MAIN",
                func:   _fiberInjectTestFunc,
              });
              fiberJson     = String(fr?.[0]?.result ?? "{}");
              diag.fiberRaw = fiberJson;
            } catch (e) {
              diag.fiberRaw = "injection_failed:" + String(e).slice(0, 120);
            }

            let fib: any = {};
            try { fib = JSON.parse(fiberJson); } catch { fib = {}; }

            diag.framework      = fib.framework ?? "unknown";
            diag.hasAngular     = !!(fib.hasAngular || fib.hasAngularGlobal || fib.hasAngularIvy);
            diag.hasVue         = !!fib.hasVue;
            diag.fiberInjectOk  = fib.ok === true;
            diag.fiberMethod    = fib.method ?? "";
            diag.fiberError     = (fib.ok !== true ? (fib.error ?? "") : "").slice(0, 100);
            diag.fiberStateSnap = fib.stateSnapshot ?? [];
            diag.notableGlobals = fib.notableGlobals ?? [];
            if (fib.ok === true) {
              diag.fiberCount = `${fib.countBefore ?? "?"} → ${fib.countAfter ?? "?"}`;
            }

            // ── Determine canonical failure reason ───────────────────────────
            if (diag.fiberInjectOk) {
              diag.failureReason = "";   // fiber succeeded
            } else {
              const fiberErr = fib.error ?? "";
              if      (fiberErr.includes("no_react_detected"))        diag.failureReason = fib.hasAngular ? "angular_not_react" : fib.hasVue ? "vue_not_react" : "no_framework";
              else if (fiberErr.includes("no_fiber_roots_found"))     diag.failureReason = "react_no_fiber_roots";
              else if (fiberErr.includes("no_sections_in_fiber_state")) diag.failureReason = "react_no_sections_in_fiber";
              else if (fiberErr.includes("no_store_ref"))              diag.failureReason = "no_store_ref";
              else if (fiberErr.includes("no_sections_array"))         diag.failureReason = "no_sections_array_in_state";
              else if (fiberErr.includes("no_action_type"))            diag.failureReason = "no_action_type_changed_state";
              else                                                      diag.failureReason = fiberErr.slice(0, 50) || (ins.error ?? "unknown").slice(0, 50);
            }

            return diag;
          }

          // Run all frames (sequentially to avoid overloading the tab)
          const frames: FrameDiag[] = [];
          for (const fi of allFrames) {
            frames.push(await diagnoseFrame(fi));
          }

          // Find success (Redux or fiber)
          const successFrame = frames.find((f) => f.insertOk || f.fiberInjectOk);

          // Rank most-likely builder frame
          function builderScore(f: FrameDiag): number {
            let s = 0;
            if (/leadconnectorhq\.com|gohighlevel\.com|msgsndr\.com/.test(f.url)) s += 10;
            if (/builder|editor|funnel|page/.test(f.url))   s += 10;
            if (f.injectionOk)   s += 4;
            if (f.storeFound)    s += 6;
            if (f.sectionsFound) s += 6;
            if (f.framework === "react")   s += 5;
            if (f.framework === "angular") s += 3;
            if (f.failureReason === "react_no_sections_in_fiber") s += 8;
            if (f.failureReason === "no_action_type_changed_state") s += 7;
            if (f.fiberStateSnap.length > 0) s += 4;
            return s;
          }
          const ranked = [...frames].sort((a, b) => builderScore(b) - builderScore(a));
          const best = ranked[0];

          // Recommendation string
          let recommendation = "";
          if (successFrame) {
            const method = successFrame.fiberInjectOk
              ? `fiber:${successFrame.fiberMethod}`
              : `redux:${successFrame.actionType}`;
            recommendation = `PRIMITIVE PROVEN via ${method} in frame ${successFrame.frameId}`;
          } else if (best?.failureReason === "react_no_sections_in_fiber") {
            recommendation =
              "React detected, fiber roots found, but sections not in component state. " +
              "Sections may be in a context/provider or loaded lazily. " +
              "State snapshot: " + (best.fiberStateSnap.slice(0, 4).join(" | ") || "empty") + ". " +
              "Try scrolling the builder to trigger lazy load, then re-run.";
          } else if (best?.failureReason === "react_no_fiber_roots") {
            recommendation =
              "React detected but no fiber roots found. " +
              "The builder may be in a cross-origin iframe not accessible to MAIN world injection. " +
              "Check which frame has the builder canvas in the table above.";
          } else if (best?.failureReason === "angular_not_react") {
            recommendation =
              "HL builder uses Angular (not React). Redux and React fiber paths both inapplicable. " +
              "Use ng.getComponent() + ng.applyChanges() or the HTTP API path instead.";
          } else if (best?.failureReason === "no_action_type_changed_state") {
            recommendation =
              "Redux store + sections found but no action type worked. " +
              (best.capturedTypes.length > 0
                ? "Captured real action types: " + best.capturedTypes.slice(0, 4).join(", ")
                : "No real actions captured — interact with the builder then re-run.");
          } else if (best?.failureReason === "no_sections_array_in_state") {
            recommendation =
              "Redux store found but sections not in state. " +
              "State keys: " + (best.stateKeys.slice(0, 8).join(", ") || "none");
          } else if (frames.every((f) => f.failureReason === "injection_failed")) {
            recommendation =
              "executeScript injection failed in ALL frames. " +
              "Check manifest scripting permission or Content-Security-Policy blocking.";
          } else if (best?.framework === "unknown" || best?.failureReason === "no_framework") {
            recommendation =
              "No known JS framework detected. Builder may be server-rendered or use a bundled custom runtime. " +
              "HTTP API path (Option A) is the only remaining option.";
          } else {
            recommendation =
              "Unhandled failure — see frame table. Best frame: #" + (best?.frameId ?? "?") +
              " reason: " + (best?.failureReason ?? "unknown");
          }

          if (successFrame) {
            sendResponse({
              ok:          true,
              // Redux fields
              actionType:  successFrame.actionType || undefined,
              path:        successFrame.sectionsPath || undefined,
              countBefore: successFrame.insertOk ? successFrame.countBefore : successFrame.fiberInjectOk ? undefined : undefined,
              countAfter:  successFrame.insertOk ? successFrame.countAfter  : undefined,
              // Fiber fields
              fiberMethod: successFrame.fiberMethod || undefined,
              fiberCount:  successFrame.fiberCount  || undefined,
              method:      successFrame.fiberInjectOk ? `fiber:${successFrame.fiberMethod}` : `redux:${successFrame.actionType}`,
              frame:       `frame${successFrame.frameId}`,
              frameUrl:    successFrame.url,
              framework:   successFrame.framework,
              frames,
              recommendation,
            });
          } else {
            sendResponse({
              ok: false,
              error: "All frames failed — see frames[] for per-frame diagnostics",
              frames,
              recommendation,
            });
          }
        } catch (err) {
          logger.error("router", `TEST_INJECT threw: ${String(err)}`);
          sendResponse({ ok: false, error: String(err), frames: [] });
        }
      })();
      return true;
    }

    // ── Pull runtime captures: read action spy log from MAIN world ────────────
    // Reads window.__cl_runtime.dispatched and scores each action for relevance
    // to "add section" operations.  Returns top candidates for the Learn panel.
    case "PULL_RUNTIME_CAPTURES": {
      (async () => {
        try {
          const pl      = (message as any).payload ?? {};
          const tabId   = pl.tabId   as number | undefined;
          const frameId = pl.frameId as number | undefined;

          let resolvedTabId = tabId;
          if (!resolvedTabId) {
            const bt = await findBuilderTab();
            resolvedTabId = bt?.id;
          }
          if (!resolvedTabId) {
            sendResponse({ ok: false, error: "No builder tab." });
            return;
          }

          // Try top frame first, then builder frame
          const frameIds: number[] = [0];
          if (frameId != null && frameId !== 0) frameIds.push(frameId);

          let best: RuntimeCaptureResult | null = null;
          for (const fid of frameIds) {
            try {
              const r = await chrome.scripting.executeScript({
                target: { tabId: resolvedTabId, frameIds: [fid] },
                world:  "MAIN",
                func:   _pullRuntimeCapturesFunc,
              });
              const result = r?.[0]?.result as RuntimeCaptureResult | undefined;
              if (result?.storeFound) { best = result; break; }
              if (!best && result) best = result;
            } catch { /* frame might not be injectable */ }
          }

          sendResponse({ ok: true, data: best });
        } catch (err) {
          sendResponse({ ok: false, error: String(err) });
        }
      })();
      return true;
    }

    // ── Dispatch section insert: replay captured action with our content ───────
    // Uses the exact action type observed during Learn Import Path (from the
    // dispatch spy) and dispatches it with our cloned section merged into the
    // payload.  Falls back through multiple payload shapes.
    case "DISPATCH_SECTION_INSERT": {
      (async () => {
        try {
          const pl         = (message as any).payload ?? {};
          const tabId      = pl.tabId      as number | undefined;
          const frameId    = pl.frameId    as number | undefined;
          const actionType = pl.actionType as string | undefined;
          const sectionsJson     = pl.sectionsJson     as string | undefined;
          const origPayloadJson  = pl.origPayloadJson  as string | undefined;

          if (!actionType) {
            sendResponse({ ok: false, error: "actionType is required" });
            return;
          }

          let resolvedTabId = tabId;
          if (!resolvedTabId) {
            const bt = await findBuilderTab();
            resolvedTabId = bt?.id;
          }
          if (!resolvedTabId) {
            sendResponse({ ok: false, error: "No builder tab." });
            return;
          }

          // Try the specific frame first, fall back to frame 0
          const frameIds: number[] = frameId != null ? [frameId, 0] : [0];
          let lastResult: DispatchInsertResult = { ok: false, error: "No frames tried", results: [] };

          for (const fid of frameIds) {
            try {
              const r = await chrome.scripting.executeScript({
                target: { tabId: resolvedTabId, frameIds: [fid] },
                world:  "MAIN",
                func:   _dispatchSectionInsertFunc,
                args:   [
                  actionType,
                  sectionsJson     ?? "[]",
                  origPayloadJson  ?? "null",
                ],
              });
              const result = r?.[0]?.result as DispatchInsertResult | undefined;
              lastResult = result ?? { ok: false, error: "No result from executeScript", results: [] };
              if (lastResult.ok) break;
            } catch (e) {
              lastResult = { ok: false, error: String(e), results: [] };
            }
          }

          logger.info("router", `DISPATCH_SECTION_INSERT: actionType=${actionType} ok=${lastResult.ok} results=${lastResult.results?.join(", ")}`);
          sendResponse({ ok: lastResult.ok, data: lastResult, error: lastResult.error });
        } catch (err) {
          logger.error("router", `DISPATCH_SECTION_INSERT threw: ${String(err)}`);
          sendResponse({ ok: false, error: String(err) });
        }
      })();
      return true;
    }

    case "SAVE_PASTE_SESSION": {
      (async () => {
        try {
          const session = {
            ...(message as any).payload,
            createdAt: new Date().toISOString(),
          };
          await chrome.storage.local.set({ [PASTE_SESSION_KEY]: session });
          sendResponse({ ok: true });
        } catch (err) {
          sendResponse({ ok: false, error: String(err) });
        }
      })();
      return true;
    }

    case "GET_PASTE_SESSION": {
      (async () => {
        try {
          const r = await chrome.storage.local.get(PASTE_SESSION_KEY);
          const session = r[PASTE_SESSION_KEY] ?? null;
          sendResponse({ ok: true, data: session });
        } catch (err) {
          sendResponse({ ok: false, error: String(err) });
        }
      })();
      return true;
    }

    case "CLEAR_PASTE_SESSION": {
      (async () => {
        try {
          await chrome.storage.local.remove(PASTE_SESSION_KEY);
          sendResponse({ ok: true });
        } catch (err) {
          sendResponse({ ok: false, error: String(err) });
        }
      })();
      return true;
    }

    case "IMPORT_JSON_PACKAGE": {
      (async () => {
        try {
          const captureId       = (message as any).payload?.captureId      as string | undefined;
          const targetTabId     = (message as any).payload?.targetTabId   as number | undefined;
          // targetFrameId: the specific iframe in the builder tab where HL runs.
          // Injecting the MAIN-world fetch into this exact frame ensures the request
          // originates from the correct origin (e.g. page-builder.leadconnectorhq.com)
          // rather than the top frame, which may have a different origin.
          const targetFrameId   = (message as any).payload?.targetFrameId as number | undefined;
          const candidateId     = (message as any).payload?.candidateId   as string | undefined;
          // Inline candidate payload — same pattern as REPLAY_TEST_SECTION.
          // Avoids store-lookup race conditions when paste runs immediately after learn.
          const inlineCand      = (message as any).payload?.candidate     as ImportCandidate | undefined;
          // strictStrategy = true means: the user explicitly chose a learned candidate.
          // If ALL candidates fail we must NOT silently fall through to content-script-inject.
          const strictStrategy  = !!((message as any).payload?.strictStrategy);

          if (!captureId) {
            sendResponse({ ok: false, error: "No saved page or funnel selected." });
            return;
          }

          // Load the capture from storage
          const captures = await getPublicCaptures();
          const cap = captures.find((c) => c.captureId === captureId);
          if (!cap) {
            sendResponse({ ok: false, error: "Capture not found in library. It may have been deleted." });
            return;
          }

          // ── Tier 1: Fetch replay via learned candidate(s) ──────────────────
          // Build candidate list:
          //   1. Inline candidate from payload (avoids store-lookup race)
          //   2. Store lookup by id (fallback for inline)
          //   3. All remaining store candidates by priority
          const allCandidates = await getImportCandidates();
          const replayCandidates: ImportCandidate[] = [];
          const seenIds = new Set<string>();

          // Prefer the inline candidate first
          if (inlineCand) {
            // Merge requestHeaders from both field name variants
            const merged: ImportCandidate = {
              ...inlineCand,
              url:    inlineCand.url || (inlineCand as any).fullUrl || (inlineCand as any).endpoint || "",
              method: inlineCand.method || "POST",
              requestHeaders: {
                ...(inlineCand.requestHeaders ?? {}),
                ...((inlineCand as any).headers ?? {}),
              },
            };
            replayCandidates.push(merged);
            seenIds.add(merged.id);
          }

          // Then the store lookup by id (if different from inline)
          if (candidateId && !seenIds.has(candidateId)) {
            const pinned = allCandidates.find((c) => c.id === candidateId);
            if (pinned) { replayCandidates.push(pinned); seenIds.add(pinned.id); }
          }

          // Then all remaining store candidates in priority order
          if (!strictStrategy) {
            // Only add fallback candidates when user has NOT locked to a specific strategy
            const rest = sortCandidatesByPriority(allCandidates.filter((c) => !seenIds.has(c.id)));
            replayCandidates.push(...rest);
          }

          logger.info("router", `IMPORT_JSON_PACKAGE — ${replayCandidates.length} candidate(s), strict=${strictStrategy}, tabId=${targetTabId}`);

          let lastFailReason = "";
          for (const cand of replayCandidates) {
            const logCtx = { url: cand.url, method: cand.method, headers: Object.keys(cand.requestHeaders ?? {}).length };
            logger.info("router", `Executing learned-mutation-replay [priority=${candidatePriority(cand.url)}]`, logCtx);
            const replayResult = await attemptFetchReplay(cand, cap, targetTabId, targetFrameId);
            if (replayResult.ok) {
              sendResponse({
                ok:                  true,
                attempted:           true,
                verified:            replayResult.verified,
                strategy:            "learned-mutation-replay",
                fetchPath:           replayResult.fetchPath,
                message:             replayResult.message,
                status:              replayResult.status,
                responseBodyPreview: replayResult.responseBodyPreview,
                responseSize:        replayResult.responseSize,
                requestBodySize:     replayResult.requestBodySize,
                candidateUrl:        replayResult.candidateUrl,
                candidateMethod:     replayResult.candidateMethod,
              });
              return;
            }
            lastFailReason = `${replayResult.status} — ${replayResult.message}`;
            logger.warn("router", `Candidate failed (${replayResult.status}), trying next`, { reason: replayResult.message });
          }

          // ── All Tier 1 candidates exhausted ────────────────────────────────
          if (strictStrategy) {
            // User explicitly chose a learned strategy — do NOT silently fall back.
            // Return a clear error so the UI can surface it.
            sendResponse({
              ok:       false,
              strategy: "learned-mutation-replay",
              error:    replayCandidates.length === 0
                ? "No learned candidate available. Run Learn Import Path first."
                : `Learned mutation replay failed: ${lastFailReason}`,
            });
            return;
          }

          // ── Tier 2: Content script DOM injection (only when no learned strategy) ──
          // Find / validate the builder tab
          let builderTab: chrome.tabs.Tab | null = null;
          if (targetTabId) {
            try {
              builderTab = await chrome.tabs.get(targetTabId);
              const url = builderTab.url ?? "";
              const isHL   = /gohighlevel\.com|highlevel\.com|msgsndr\.com|leadconnectorhq\.com|app\.ghl\.io/.test(url);
              const isEdit = /\/funnel|\/page-builder|\/builder\/|funnels\/|\/pages\/|funnel-builder|page-editor|site-builder|\/edit\/|\/editor\//.test(url);
              if (!isHL || !isEdit) {
                sendResponse({ ok: false, error: "Builder tab changed or was closed. Open a HighLevel page builder and try again." });
                return;
              }
            } catch {
              sendResponse({ ok: false, error: "Builder tab is no longer available. Open a HighLevel page builder and try again." });
              return;
            }
          } else {
            builderTab = await findBuilderTab();
          }

          if (!builderTab?.id) {
            sendResponse({ ok: false, error: "Open a HighLevel page builder first, then try again." });
            return;
          }

          // Ensure content script is live before sending
          const conn = await ensureBuilderConnection(builderTab.id);
          if (!conn.ok) {
            sendResponse({ ok: false, error: conn.error ?? "No live connection to the HighLevel builder tab." });
            return;
          }

          // Send DO_INJECT_CLONE_PACKAGE — the content script now has a real handler
          // that activates the page bridge and tries multiple injection strategies.
          let csResult: any;
          try {
            csResult = await chrome.tabs.sendMessage(builderTab.id, {
              type: "DO_INJECT_CLONE_PACKAGE",
              payload: {
                captureId:    cap.captureId,
                title:        cap.title,
                domain:       cap.domain,
                pageType:     cap.pageType,
                sections:     cap.sections,
                assets:       cap.assets,
                funnelLinks:  cap.funnelLinks,
                rawHtmlSize:  cap.rawHtmlSize,
              },
            });
          } catch (err) {
            sendResponse({ ok: false, error: "Builder detected, but content script communication failed. Refresh the builder tab and try again." });
            return;
          }

          sendResponse({
            ok:        true,
            attempted: true,
            verified:  csResult?.verified === true,
            strategy:  "content-script-inject",
            message:   csResult?.message ?? `"${cap.title}" — injection attempted via content script.`,
            strategies: csResult?.strategies,
            globals:    csResult?.globals,
          });
        } catch (err) {
          sendResponse({ ok: false, error: String(err).replace("Error: ", "") });
        }
      })();
      return true;
    }

    case "REPLAY_TEST_SECTION": {
      (async () => {
        try {
          const payload        = (message as any).payload ?? {};
          const candidateId    = payload.candidateId   as string | undefined;
          const targetTabId    = payload.targetTabId   as number | undefined;
          // targetFrameId: the exact iframe where the HL builder runs.
          // Used by fetchInMainWorld to inject the fetch into the correct origin.
          const targetFrameId  = payload.targetFrameId as number | undefined;
          const inlineCand     = payload.candidate     as ImportCandidate | undefined;

          if (!candidateId && !inlineCand) {
            sendResponse({ ok: false, error: "No candidateId or candidate provided" });
            return;
          }

          // ── Resolve candidate: inline payload first (avoids store lookup entirely),
          //   then store lookup as fallback for background-captured candidates ──────
          let cand: ImportCandidate | undefined = inlineCand;
          if (!cand && candidateId) {
            const allCandidates = await getImportCandidates();
            cand = allCandidates.find((c) => c.id === candidateId);
          }

          if (!cand) {
            sendResponse({ ok: false, error: `Candidate not found (id: ${candidateId ?? "n/a"})` });
            return;
          }

          // Normalize URL and method — candidate might have url in fullUrl or endpoint field
          const replayUrl    = cand.url ?? (cand as any).fullUrl ?? (cand as any).endpoint ?? "";
          const replayMethod = cand.method ?? "";
          if (!replayUrl || !replayMethod) {
            sendResponse({ ok: false, error: "Candidate missing required url or method for replay" });
            return;
          }
          // Ensure cand.url is always the resolved URL for downstream replay functions
          if (!cand.url) cand = { ...cand, url: replayUrl, method: replayMethod };

          // ── DOM snapshot BEFORE ────────────────────────────────────────────────
          const SECTION_SELS = ["[data-type='section']","[data-section]",".hl-section","section","[class*='section']"];
          const countSections = () => {
            const SELS = ["[data-type='section']","[data-section]",".hl-section","section","[class*='section']"];
            let n = 0;
            for (const s of SELS) { try { const c = document.querySelectorAll(s).length; if (c > n) n = c; } catch { /* */ } }
            return n;
          };
          void SECTION_SELS; // referenced via func injection below
          let sectionsBefore = 0;
          if (targetTabId) {
            try {
              const snapRes = await chrome.scripting.executeScript({ target: { tabId: targetTabId }, world: "MAIN", func: countSections });
              sectionsBefore = Number((snapRes?.[0]?.result as number | undefined) ?? 0) || 0;
            } catch { /* tab may not allow injection */ }
          }

          // ── Send test section payload ──────────────────────────────────────────
          // targetFrameId ensures the MAIN-world fetch runs in the builder's iframe origin
          const replayResult = await attemptTestSectionReplay(cand, targetTabId, targetFrameId);

          // ── DOM snapshot AFTER (900ms for builder to update) ──────────────────
          let sectionsAfter = 0;
          if (targetTabId && replayResult.ok) {
            await new Promise((r) => setTimeout(r, 900));
            try {
              const snapRes = await chrome.scripting.executeScript({ target: { tabId: targetTabId }, world: "MAIN", func: countSections });
              sectionsAfter = Number((snapRes?.[0]?.result as number | undefined) ?? 0) || 0;
            } catch { /* */ }
          }

          // ── Safe section delta — never NaN ─────────────────────────────────────
          const safeBefore = Number(sectionsBefore) || 0;
          const safeAfter  = Number(sectionsAfter)  || 0;
          const sectionsDelta = safeAfter - safeBefore;

          sendResponse({ ...replayResult, sectionsDelta, sectionsBefore: safeBefore });
        } catch (err) {
          sendResponse({ ok: false, error: String(err).replace("Error: ", "") });
        }
      })();
      return true;
    }

    case "CRAWL_PROGRESS":
      sendResponse({ ok: true });
      return false;

    case "ERROR":
      logger.error("router", "Error message received", message.payload);
      sendResponse({ ok: true });
      return false;

    default: {
      const _exhaustive: never = message;
      logger.warn("router", `Unhandled message type: ${(message as any).type}`);
      sendResponse({ ok: false, error: "Unknown message type" });
      return false;
    }
  }
}

async function handleDetectContext(sendResponse: SendResponse): Promise<void> {
  try {
    const tab = await getActiveTab();
    if (!tab?.id) { sendResponse({ ok: false, error: "No active tab" }); return; }

    const cached = getTabContext(tab.id);
    if (cached) { sendResponse({ ok: true, data: cached }); return; }

    const result = await pingContentScript(tab.id, { type: "DO_DETECT_CONTEXT" });
    if (result?.ok && result.data) {
      setTabContext(tab.id, result.data);
      sendResponse({ ok: true, data: result.data });
    } else {
      sendResponse({ ok: true, data: null });
    }
  } catch (err) {
    logger.error("router", "Failed to detect context", err);
    sendResponse({ ok: false, error: String(err) });
  }
}

async function handleCapturePublicPage(sendResponse: SendResponse): Promise<void> {
  try {
    const tab = await getActiveTab();
    if (!tab?.id) { sendResponse({ ok: false, error: "No active tab" }); return; }

    // ── Step 1: DOM capture (HTML sections, assets) ───────────────────────────
    const result = await pingContentScript(tab.id, { type: "DO_CAPTURE_PAGE" });
    if (!result?.ok || !result.data) {
      sendResponse({ ok: false, error: result?.error || "Capture returned no data" });
      return;
    }
    const capture = result.data;

    // ── Step 1b: Platform / CMS detection ────────────────────────────────────
    // Runs _detectCmsFunc in the MAIN world to detect the CMS (WordPress, Shopify,
    // Nuxt.js, HighLevel, etc.). Non-blocking; failure is silently ignored.
    try {
      const cmsProbe = await chrome.scripting.executeScript({
        target: { tabId: tab.id, frameIds: [0] },
        world:  "MAIN",
        func:   _detectCmsFunc,
      });
      const platform = cmsProbe?.[0]?.result;
      if (platform && typeof platform === "string" && platform !== "Web") {
        (capture as any).platform = platform;
        logger.info("router", `handleCapturePublicPage: platform=${platform}`);
      }
    } catch (cmsErr) {
      logger.warn("router", `handleCapturePublicPage: CMS detect failed (non-fatal): ${String(cmsErr).slice(0,80)}`);
    }

    // ── Step 2: GHL metadata — 3-path detection ──────────────────────────────
    // Path A: inject.js cached result (fastest — fires at page load)
    // Path B: executeScript _extractGhlMetadataFunc (on-demand)
    // Path C: CRM domain lookup via revex on builder tab (fallback)
    const sourceUrl = (capture as any).source?.url ?? tab.url ?? "";
    let ghl: any = null;

    // Path A: Check inject.js pre-detection cache for this tab
    try {
      const stored = await chrome.storage.session.get(`ghl_tab_${tab.id}`);
      const cached = stored[`ghl_tab_${tab.id}`];
      if (cached?.funnelId && cached?.stepId) {
        ghl = cached;
        logger.info("router", `handleCapturePublicPage: Path A (inject cache) — funnelId=${ghl.funnelId} stepId=${ghl.stepId}`);
      }
    } catch (_) {}

    // Path B: executeScript _extractGhlMetadataFunc (retries at 0, 300, 700, 1500ms)
    if (!ghl) {
      try {
        for (const delay of [0, 300, 700, 1500]) {
          if (delay > 0) await new Promise((r) => setTimeout(r, delay));
          const probe = await chrome.scripting.executeScript({
            target: { tabId: tab.id, frameIds: [0] },
            world:  "MAIN",
            func:   _extractGhlMetadataFunc,
          });
          const raw = probe?.[0]?.result;
          if (!raw) continue;
          const parsed = JSON.parse(raw);
          logger.info("router", `handleCapturePublicPage: Path B delay=${delay}ms isGhlPage=${parsed.isGhlPage} funnelId=${parsed.funnelId ?? "(none)"} log=[${parsed.debugLog ?? ""}]`);
          if (parsed.isGhlPage && parsed.funnelId && parsed.stepId) { ghl = parsed; break; }
        }
        if (ghl) logger.info("router", `handleCapturePublicPage: Path B confirmed — funnelId=${ghl.funnelId} stepId=${ghl.stepId} source=${ghl.source}`);
        else logger.info("router", "handleCapturePublicPage: Path B found no GHL metadata");
      } catch (probeErr) {
        logger.warn("router", `handleCapturePublicPage: Path B failed (non-fatal): ${String(probeErr).slice(0, 150)}`);
      }
    }

    // Path C: CRM domain lookup from builder tab (searches HL funnels by domain)
    // Only runs when Paths A+B failed and we have a source URL.
    if (!ghl && sourceUrl) {
      try {
        let parsedUrl: URL | null = null;
        try { parsedUrl = new URL(sourceUrl); } catch { /**/ }
        if (parsedUrl) {
          // Find any HL builder tab to run the revex lookup from
          const allTabs = await chrome.tabs.query({});
          const builderTabForLookup = allTabs.find(t =>
            t.url && /page-builder\.leadconnectorhq\.com|app\.gohighlevel\.com/.test(t.url)
          );
          if (builderTabForLookup?.id) {
            logger.info("router", `handleCapturePublicPage: Path C CRM lookup for domain=${parsedUrl.hostname} via builderTab=${builderTabForLookup.id}`);
            const lookupRes = await chrome.scripting.executeScript({
              target: { tabId: builderTabForLookup.id, frameIds: [0] },
              world:  "MAIN",
              func:   _lookupGhlPageByDomainFunc,
              args:   [parsedUrl.hostname, parsedUrl.pathname],
            });
            const domainRaw = lookupRes?.[0]?.result;
            if (domainRaw) {
              const domainResult = JSON.parse(domainRaw);
              logger.info("router", `handleCapturePublicPage: Path C result ok=${domainResult.ok} funnelId=${domainResult.funnelId ?? "?"} log=[${domainResult.log ?? ""}]`);
              if (domainResult.ok && domainResult.funnelId && domainResult.stepId) {
                ghl = { funnelId: domainResult.funnelId, stepId: domainResult.stepId, locationId: domainResult.locationId ?? "", source: "crm-domain-lookup" };
              }
            }
          } else {
            logger.info("router", "handleCapturePublicPage: Path C skipped — no HL builder tab open");
          }
        }
      } catch (lookupErr) {
        logger.warn("router", `handleCapturePublicPage: Path C failed (non-fatal): ${String(lookupErr).slice(0, 150)}`);
      }
    }

    if (ghl) {
      (capture as any).isGhlPage     = true;
      (capture as any).ghlFunnelId   = ghl.funnelId;
      (capture as any).ghlStepId     = ghl.stepId;
      (capture as any).ghlLocationId = ghl.locationId ?? "";
      logger.info("router", `handleCapturePublicPage: GHL confirmed via ${ghl.source} — funnelId=${ghl.funnelId} stepId=${ghl.stepId}`);
    } else {
      logger.info("router", "handleCapturePublicPage: all 3 detection paths failed — not a detectable GHL page");
    }

    await savePackage(capture);
    sendResponse({ ok: true, data: capture });
  } catch (err) {
    logger.error("router", "Failed to capture page", err);
    sendResponse({ ok: false, error: String(err) });
  }
}

async function handleEnableInspector(sendResponse: SendResponse): Promise<void> {
  try {
    const state = await getInspectorSessionState();
    const targetTabId = state.editorTabId ?? (await getActiveTab())?.id ?? null;

    if (!targetTabId) {
      sendResponse({ ok: false, error: "No editor tab found. Open the HighLevel editor first." });
      return;
    }

    const result = await pingContentScript(targetTabId, { type: "DO_ENABLE_INSPECTOR" });
    if (result?.ok) {
      const next = await patchInspectorSessionState({ enabled: true, tabId: targetTabId });
      addDiagnostic(createDiagnosticEntry("info", "INSPECTOR_ENABLED", `Inspector enabled on tab ${targetTabId}`));
      broadcastToInspectors({ type: "STATE_UPDATE", payload: next });
      sendResponse({ ok: true, data: result.data });
    } else {
      sendResponse({ ok: false, error: result?.error || "Failed to enable inspector", warning: result?.warning });
    }
  } catch (err) {
    logger.error("router", "Failed to enable inspector", err);
    sendResponse({ ok: false, error: String(err) });
  }
}

async function handleDisableInspector(sendResponse: SendResponse): Promise<void> {
  try {
    const state = await getInspectorSessionState();
    const targetTabId = state.tabId ?? (await getActiveTab())?.id ?? null;

    if (targetTabId) {
      try {
        await sendToContentScript(targetTabId, { type: "DO_DISABLE_INSPECTOR" });
      } catch { /* tab may be gone */ }
    }

    const next = await patchInspectorSessionState({ enabled: false, tabId: null });
    broadcastToInspectors({ type: "STATE_UPDATE", payload: next });
    sendResponse({ ok: true, data: { enabled: false } });
  } catch (err) {
    logger.error("router", "Failed to disable inspector", err);
    sendResponse({ ok: false, error: String(err) });
  }
}

async function handleSnapshotCaptured(payload: any, sendResponse: SendResponse): Promise<void> {
  try {
    await addSnapshot(payload);
    const next = await patchInspectorSessionState({ lastSnapshotAt: payload.timestamp });
    logger.info("router", `Snapshot saved: ${payload.id} — ${payload.requestUrl}`);
    broadcastToInspectors({ type: "STATE_UPDATE", payload: next });
    broadcastToInspectors({ type: "SNAPSHOT_ADDED", payload });
    sendResponse({ ok: true });
  } catch (err) {
    logger.error("router", "Failed to save snapshot", err);
    sendResponse({ ok: false, error: String(err) });
  }
}

async function handleCrawlFunnel(
  payload: {
    rootUrl: string;
    maxDepth?: number;
    maxPages?: number;
    delayMs?: number;
    allowedDomains?: string[];
    includePatterns?: string[];
    excludePatterns?: string[];
    stripQueryStrings?: boolean;
  },
  sendResponse: SendResponse
): Promise<void> {
  try {
    const settings = await getSettings();
    const config = {
      rootUrl: payload.rootUrl,
      maxDepth: payload.maxDepth ?? settings.maxCrawlDepth,
      maxPages: payload.maxPages ?? settings.maxPages,
      delayMs: payload.delayMs ?? settings.crawlDelayMs,
      allowedDomains: payload.allowedDomains ?? [],
      includePatterns: payload.includePatterns ?? [],
      excludePatterns: payload.excludePatterns ?? [],
      stripQueryStrings: payload.stripQueryStrings ?? settings.stripQueryStrings,
    };

    logger.info("router", "Starting crawl", config);
    const map = await crawlFunnel(config);
    await saveFunnelMap(map);
    sendResponse({ ok: true, data: map });
  } catch (err) {
    logger.error("router", "Crawl failed", err);
    sendResponse({ ok: false, error: String(err) });
  }
}

