async function handleSnapshotCapturedInternal(payload: any): Promise<void> {
  await addSnapshot(payload);
  const next = await patchInspectorSessionState({ lastSnapshotAt: payload.timestamp });
  broadcastToInspectors({ type: "STATE_UPDATE", payload: next });
  broadcastToInspectors({ type: "SNAPSHOT_ADDED", payload });
}

async function handleExtractState(tabId: number | null, sendResponse: SendResponse): Promise<void> {
  try {
    let targetTabId = tabId;
    if (!targetTabId) {
      // Try session editor tab first, then active tab
      const state = await getInspectorSessionState();
      targetTabId = state.editorTabId ?? state.tabId ?? (await getActiveTab())?.id ?? null;
    }
    if (!targetTabId) {
      sendResponse({ ok: false, error: "No HighLevel editor tab found. Open the HL editor first." });
      return;
    }
    const { ok, result, error } = await runStateExtract(targetTabId);
    // Notify inspector of new extract
    broadcastToInspectors({ type: "STATE_EXTRACT_DONE", payload: result });
    sendResponse({ ok, data: result, error });
  } catch (err) {
    logger.error("router", "handleExtractState failed", err);
    sendResponse({ ok: false, error: String(err) });
  }
}

function ts(): string {
  return new Date().toLocaleTimeString([], { hour12: false, hour: "2-digit", minute: "2-digit", second: "2-digit" });
}

async function handleActivateBridgeDebug(sendResponse: SendResponse): Promise<void> {
  const log: string[] = [];
  try {
    log.push(`[${ts()}] ▶ Stage 1 — Inspector sent ACTIVATE_BRIDGE_DEBUG`);
    log.push(`[${ts()}] ✔ Stage 2 — Background received ACTIVATE_BRIDGE_DEBUG`);

    const state = await getInspectorSessionState();
    const targetTabId = state.editorTabId ?? null;
    log.push(`[${ts()}] Stage 2 — editorTabId in session: ${targetTabId ?? "none"}`);

    if (!targetTabId) {
      log.push(`[${ts()}] ✗ Stage 2 — FAIL: no editorTabId. Open the HL editor first.`);
      sendResponse({ ok: false, log, error: "No editorTabId in session" });
      return;
    }

    try {
      const tab = await chrome.tabs.get(targetTabId);
      log.push(`[${ts()}] Stage 2 — Tab URL: ${tab.url ?? "unknown"}`);
    } catch { log.push(`[${ts()}] Stage 2 — WARNING: could not read tab URL`); }

    // Clear any previous ACK so we can detect a fresh one.
    await chrome.storage.local.remove("clonelevel_bridge_ack");
    log.push(`[${ts()}] Stage 2 — Cleared previous BRIDGE_ACK from storage`);

    // ── Step 1: Inject bridge runtime into MAIN world ──────────────────────────
    // chrome.scripting.executeScript({world:"MAIN"}) is NOT subject to the
    // page's Content-Security-Policy; <script src> from a content script IS.
    log.push(`[${ts()}] Stage 2b — Injecting bridge runtime into MAIN world via chrome.scripting…`);
    try {
      await chrome.scripting.executeScript({
        target: { tabId: targetTabId, allFrames: false },
        files: ["content/bridge/page-bridge-runtime.js"],
        world: "MAIN",
      });
      log.push(`[${ts()}] ✔ Stage 2b — Bridge runtime file loaded into MAIN world`);
    } catch (injErr) {
      log.push(`[${ts()}] ⚠ Stage 2b — executeScript(files) failed: ${String(injErr)} — bridge may already be active`);
    }

    // ── Step 2: Activate bridge & install hooks — also from MAIN world ─────────
    // We call installNetworkInterceptors() directly via executeScript so there
    // is ZERO doubt it runs in the page's MAIN context and patches the real APIs.
    // postMessage routing (content-script → bridge) can be intercepted by CSP or
    // extension isolated-world boundaries; executeScript bypasses both.
    log.push(`[${ts()}] Stage 2c — Calling installNetworkInterceptors() from MAIN world via executeScript…`);
    try {
      const enableResult = await chrome.scripting.executeScript({
        target: { tabId: targetTabId, allFrames: false },
        world: "MAIN",
        func: () => {
          const ds = document.documentElement.dataset;
          const bridge = (window as any).__clonelevel_bridge as {
            installNetworkInterceptors?: () => void;
            patchStatus?: () => Record<string, unknown>;
          } | undefined;

          if (!bridge) {
            return { ok: false, reason: "__clonelevel_bridge not found on window" };
          }
          if (typeof bridge.installNetworkInterceptors !== "function") {
            return { ok: false, reason: "installNetworkInterceptors not a function on bridge" };
          }

          // Set inspector enabled flag before installing so payloads are emitted.
          ds.clBridgeEnabled = "1";
          bridge.installNetworkInterceptors();

          const ps = bridge.patchStatus?.() ?? {};
          return {
            ok: true,
            patchStatus: ps,
            fetchPatched: ds.clFetchPatched === "1",
            xhrPatched:   ds.clXhrPatched   === "1",
          };
        },
      });

      const res = enableResult?.[0]?.result as { ok: boolean; reason?: string; patchStatus?: Record<string, unknown>; fetchPatched?: boolean; xhrPatched?: boolean } | undefined;
      if (res?.ok) {
        log.push(`[${ts()}] ✔ Stage 2c — installNetworkInterceptors() done. fetch=${res.fetchPatched} xhr=${res.xhrPatched}`);
        if (res.patchStatus) log.push(`[${ts()}] Stage 2c — patchStatus: ${JSON.stringify(res.patchStatus)}`);
      } else {
        log.push(`[${ts()}] ✗ Stage 2c — ${res?.reason ?? "unknown error calling installNetworkInterceptors"}`);
      }
    } catch (enableErr) {
      log.push(`[${ts()}] ⚠ Stage 2c — executeScript(func) failed: ${String(enableErr)}`);
    }

    log.push(`[${ts()}] Stage 2 → Stage 3 — Forwarding DO_ACTIVATE_BRIDGE to content script in tab ${targetTabId}`);
    const result = await pingContentScript(targetTabId, { type: "DO_ACTIVATE_BRIDGE" });

    if (!result) {
      log.push(`[${ts()}] ✗ Stage 3 — FAIL: pingContentScript returned null (content script unreachable)`);
      sendResponse({ ok: false, log, error: "Content script unreachable after retries" });
      return;
    }
    if (!result.ok) {
      log.push(`[${ts()}] ✗ Stage 3 — FAIL: ${result.error ?? "unknown error"}`);
      sendResponse({ ok: false, log, error: result.error });
      return;
    }

    if (result.log) log.push(...result.log);
    log.push(`[${ts()}] ✔ Stage 4 — Content script responded OK. Waiting for bridge ACK in storage…`);
    sendResponse({ ok: true, log, data: result.data });
  } catch (err) {
    log.push(`[${ts()}] ✗ Exception: ${String(err)}`);
    sendResponse({ ok: false, log, error: String(err) });
  }
}

async function handleActivateBridgeFallback(sendResponse: SendResponse): Promise<void> {
  const log: string[] = [];
  try {
    log.push(`[${ts()}] ▶ Fallback — Background received ACTIVATE_BRIDGE_FALLBACK`);

    const state = await getInspectorSessionState();
    const targetTabId = state.editorTabId ?? null;
    if (!targetTabId) {
      log.push(`[${ts()}] ✗ Fallback — no editorTabId in session`);
      sendResponse({ ok: false, log, error: "No editorTabId" });
      return;
    }

    log.push(`[${ts()}] Fallback — Using chrome.scripting.executeScript world=MAIN on tab ${targetTabId}`);

    // This injection bypasses the page's Content Security Policy because it
    // uses the privileged chrome.scripting API, not a <script> tag.
    await chrome.scripting.executeScript({
      target: { tabId: targetTabId },
      world: "MAIN",
      func: () => {
        const ds = document.documentElement.dataset;
        console.log("[CloneLevel] Fallback scripting injection running in MAIN world");
        if ((window as any).__clonelevel_bridge_active) {
          // Bridge already ran — just enable it directly from main world.
          (window as any).__CLONELEVEL_BRIDGE_ENABLE__ = true;
          ds.clBridgeEnabled = "1";
          // Also dispatch the postMessage that the bridge listens for.
          window.postMessage({ source: "clonelevel-content", type: "ENABLE_INSPECTOR" }, "*");
          console.log("[CloneLevel] Fallback: bridge was loaded — sent ENABLE_INSPECTOR from main world");
        } else {
          // Bridge script never ran (likely CSP blocked the <script src> tag).
          // Set a flag so the bridge can read it when it does run, AND store
          // it as a DOM attribute for the content script to observe.
          (window as any).__CLONELEVEL_BRIDGE_ENABLE__ = true;
          ds.clBridgeFallback = "1";
          console.warn(
            "[CloneLevel] Fallback: bridge NOT loaded — __clonelevel_bridge_active is false.",
            "This means HighLevel CSP blocked the <script src> injection.",
            "Set __CLONELEVEL_BRIDGE_ENABLE__ = true and ds.clBridgeFallback = '1' for bridge to pick up on load."
          );
        }
      },
    });

    log.push(`[${ts()}] ✔ Fallback — executeScript finished. Check the HL editor console for [CloneLevel] logs.`);
    log.push(`[${ts()}] Fallback — If bridge was loaded: postMessage sent from main world.`);
    log.push(`[${ts()}] Fallback — If bridge NOT loaded: CSP is blocking extension script injection.`);
    log.push(`[${ts()}] Fallback — Check document.documentElement.dataset.clBridgeFallback in HL editor console.`);
    sendResponse({ ok: true, log });
  } catch (err) {
    log.push(`[${ts()}] ✗ Fallback exception: ${String(err)}`);
    sendResponse({ ok: false, log, error: String(err) });
  }
}

async function handlePingBridgeFromInspector(msgPayload: any, sendResponse: SendResponse): Promise<void> {
  try {
    const state = await getInspectorSessionState();
    const targetTabId = state.editorTabId ?? null;
    if (!targetTabId) { sendResponse({ ok: false, error: "No editorTabId in session" }); return; }
    const nonce = msgPayload?.nonce ?? `ping_${Date.now()}`;
    // Clear old ping ACK first.
    await chrome.storage.local.remove("clonelevel_bridge_ping_ack");
    const result = await pingContentScript(targetTabId, { type: "DO_PING_BRIDGE", payload: { nonce } });
    sendResponse({ ok: result?.ok ?? false, data: { nonce }, error: result?.error });
  } catch (err) {
    sendResponse({ ok: false, error: String(err) });
  }
}

async function handleInspectorBridgeAck(payload: any, sendResponse: SendResponse): Promise<void> {
  try {
    await chrome.storage.local.set({ clonelevel_bridge_ack: payload });
    broadcastToInspectors({ type: "BRIDGE_ACK_RECEIVED", payload });
    sendResponse({ ok: true });
  } catch (err) {
    sendResponse({ ok: false, error: String(err) });
  }
}

async function handleAttachDebugger(sendResponse: SendResponse): Promise<void> {
  try {
    const state = await getInspectorSessionState();
    const targetTabId = state.editorTabId ?? (await getActiveTab())?.id ?? null;
    if (!targetTabId) {
      sendResponse({ ok: false, error: "No tab found. Open the HighLevel editor and try again." });
      return;
    }
    const result = await attachDebugger(targetTabId);
    sendResponse({ ok: result.ok, error: result.error, data: { tabId: targetTabId } });
  } catch (err) {
    sendResponse({ ok: false, error: String(err) });
  }
}

async function handleDetachDebugger(sendResponse: SendResponse): Promise<void> {
  try {
    const result = await detachDebugger();
    sendResponse({ ok: result.ok, error: result.error });
  } catch (err) {
    sendResponse({ ok: false, error: String(err) });
  }
}
