/**
 * Public Clone Store
 * Stores page captures from public (non-HighLevel) pages.
 * These come from DOM scraping via chrome.scripting.executeScript.
 */

export const PUBLIC_CAPTURES_KEY = "clonelevel_public_captures";
const MAX_CAPTURES = 20;

// ── Types ─────────────────────────────────────────────────────────────────────

export type PageTypeHint =
  | "landing" | "checkout" | "upsell" | "order-bump"
  | "thank-you" | "booking" | "webinar" | "squeeze" | "unknown";

export type CaptureStatus = "capturing" | "captured" | "assets-scraped" | "ready";

export interface PublicAsset {
  url:      string;
  type:     "image" | "video" | "audio" | "font" | "css" | "script" | "other";
  alt?:     string;
  source:   string;
}

export interface PublicLink {
  url:      string;
  text?:    string;
  type:     PageTypeHint;
  isSameDomain: boolean;
}

export interface PublicSection {
  sectionHint: string;
  confidence:  number;
  elementCount: number;
}

export interface PublicPageCapture {
  captureId:   string;
  capturedAt:  string;
  sourceUrl:   string;
  domain:      string;
  title:       string;
  description?: string;
  favicon?:    string;
  pageType:    PageTypeHint;
  status:      CaptureStatus;
  sections:    PublicSection[];
  links:       PublicLink[];
  assets:      PublicAsset[];
  assetCount:  number;
  linkCount:   number;
  funnelLinks: PublicLink[];   // same-domain links that look like funnel steps
  hasFunnel:   boolean;
  rawHtmlSize: number;

  // ── GHL page metadata (populated when source is a published GHL page) ────────
  // When present, paste uses clone-funnel-step instead of HTML injection.
  isGhlPage?:     boolean;
  ghlFunnelId?:   string;
  ghlStepId?:     string;
  ghlLocationId?: string;

  // ── CMS / platform detection ──────────────────────────────────────────────
  // Short display string, e.g. "HighLevel", "WordPress", "Shopify", "Nuxt.js".
  platform?: string;
}

// ── URL classification ────────────────────────────────────────────────────────

export function classifyPageType(url: string, title: string, text: string): PageTypeHint {
  const u = url.toLowerCase();
  const t = (title + " " + text).toLowerCase();
  if (/thank.?you|order.?confirm|success|receipt/.test(u+t)) return "thank-you";
  if (/checkout|order|payment|buy|purchase|billing/.test(u+t)) return "checkout";
  if (/upsell|one.time.offer|oto|upgrade|special.offer/.test(u+t)) return "upsell";
  if (/order.?bump/.test(u+t)) return "order-bump";
  if (/booking|schedule|calendar|appointment/.test(u+t)) return "booking";
  if (/webinar|workshop|masterclass|training/.test(u+t)) return "webinar";
  if (/squeeze|lead.?magnet|free.?gift|opt.?in/.test(u+t)) return "squeeze";
  return "landing";
}

// ── Storage ───────────────────────────────────────────────────────────────────

export async function getPublicCaptures(): Promise<PublicPageCapture[]> {
  const r = await chrome.storage.local.get(PUBLIC_CAPTURES_KEY);
  return Array.isArray(r[PUBLIC_CAPTURES_KEY]) ? r[PUBLIC_CAPTURES_KEY] : [];
}

export async function storePublicCapture(cap: PublicPageCapture): Promise<void> {
  const existing = await getPublicCaptures();
  const filtered = existing.filter((c) => c.sourceUrl !== cap.sourceUrl);
  const updated  = [cap, ...filtered].slice(0, MAX_CAPTURES);
  await chrome.storage.local.set({ [PUBLIC_CAPTURES_KEY]: updated });
}

export async function updateCaptureStatus(captureId: string, status: CaptureStatus): Promise<void> {
  const existing = await getPublicCaptures();
  const updated  = existing.map((c) => c.captureId === captureId ? { ...c, status } : c);
  await chrome.storage.local.set({ [PUBLIC_CAPTURES_KEY]: updated });
}

export async function clearPublicCaptures(): Promise<void> {
  await chrome.storage.local.remove(PUBLIC_CAPTURES_KEY);
}

// ── Build capture from raw DOM scrape result ──────────────────────────────────

interface RawScrapeResult {
  url:         string;
  title:       string;
  description?: string;
  favicon?:    string;
  assets:      Array<{ url: string; type: string; alt?: string; source: string }>;
  links:       Array<{ url: string; text?: string; isSameDomain: boolean }>;
  sections:    Array<{ hint: string; confidence: number; elementCount: number }>;
  rawHtmlSize: number;
}

export function buildCaptureFromScrape(raw: RawScrapeResult): PublicPageCapture {
  let domain = "";
  try { domain = new URL(raw.url).hostname; } catch { domain = raw.url; }

  const pageType = classifyPageType(raw.url, raw.title, raw.description ?? "");

  const links: PublicLink[] = raw.links.map((l) => ({
    url:          l.url,
    text:         l.text,
    type:         classifyPageType(l.url, l.text ?? "", ""),
    isSameDomain: l.isSameDomain,
  }));

  const funnelLinks = links.filter((l) =>
    l.isSameDomain && l.type !== "unknown" && l.url !== raw.url
  );

  const VALID_TYPES = new Set<PublicAsset["type"]>(["image","video","audio","font","css","script","other"]);
  const assets: PublicAsset[] = raw.assets.map((a) => ({
    url:    a.url,
    type:   VALID_TYPES.has(a.type as PublicAsset["type"]) ? (a.type as PublicAsset["type"]) : "other",
    alt:    a.alt,
    source: a.source,
  }));

  const sections: PublicSection[] = raw.sections.map((s) => ({
    sectionHint:  s.hint,
    confidence:   s.confidence,
    elementCount: s.elementCount,
  }));

  return {
    captureId:   crypto.randomUUID(),
    capturedAt:  new Date().toISOString(),
    sourceUrl:   raw.url,
    domain,
    title:       raw.title || domain,
    description: raw.description,
    favicon:     raw.favicon,
    pageType,
    status:      "captured",
    sections,
    links,
    funnelLinks,
    assets,
    assetCount:  assets.length,
    linkCount:   links.length,
    hasFunnel:   funnelLinks.length >= 2,
    rawHtmlSize: raw.rawHtmlSize,
  };
}
