/**
 * Schema Store
 * Detects PAGE_SCHEMA, FUNNEL_SCHEMA, and SAVE_EVENT requests from captured
 * snapshots, parses their JSON bodies, and persists structured records.
 */
import type { PayloadSnapshot } from "../core/inspector/payload-schema";
import { scanPageLayoutForAssets } from "./asset-store";

// ── Storage keys ──────────────────────────────────────────────────────────────
export const PAGE_SCHEMAS_KEY   = "clonelevel_page_schemas";
export const FUNNEL_SCHEMAS_KEY = "clonelevel_funnel_schemas";
export const SAVE_EVENTS_KEY    = "clonelevel_save_events";

const MAX_PAGE_SCHEMAS   = 30;
const MAX_FUNNEL_SCHEMAS = 20;
const MAX_SAVE_EVENTS    = 100;

// ── Types ─────────────────────────────────────────────────────────────────────

export interface ElementCounts {
  sections: number;
  rows:     number;
  columns:  number;
  elements: number;
}

export interface PageSchemaRecord {
  pageId:              string;
  snapshotId:          string;
  capturedAt:          string;
  url:                 string;
  raw:                 string;         // full JSON string of the /funnels/page/{id} response
  title?:              string;
  slug?:               string;
  summary:             ElementCounts;
  elementTypes:        Record<string, number>;
  linkedSaveIds:       string[];
  pageDataDownloadUrl?: string;        // Firebase storage URL from schema, if present
  pageLayout?:         unknown;        // parsed JSON downloaded from pageDataDownloadUrl
  layoutCapturedAt?:   string;         // ISO timestamp when layout was fetched
}

export interface FunnelStep {
  stepId:  string;
  name?:   string;
  path?:   string;
  pageIds: string[];          // page template IDs from steps[].pages[]
}

export interface FunnelSchemaRecord {
  funnelId:   string;
  snapshotId: string;
  capturedAt: string;
  url:        string;
  raw:        string;          // full JSON string (capped at 500 KB)
  name?:      string;
  pageCount:  number;
  pageIds:    string[];        // flat union of all pageIds across all steps
  steps:      FunnelStep[];    // structured step list with per-step pageIds
}

export interface SaveEventRecord {
  snapshotId: string;
  capturedAt: string;
  url:        string;
  method:     string;
  eventType:  "autosave" | "prebuilt-section" | "global-section" | "other-save";
  pageId?:    string;
  funnelId?:  string;
  bodySize:   number;
}

// ── URL classification ────────────────────────────────────────────────────────

export type SchemaTag = "PAGE_SCHEMA" | "FUNNEL_SCHEMA" | "SAVE_EVENT" | null;

export function classifyUrl(url: string): {
  tag:      SchemaTag;
  pageId?:  string;
  funnelId?: string;
  eventType?: SaveEventRecord["eventType"];
} {
  const u = url.toLowerCase();

  // PAGE_SCHEMA: GET /funnels/page/{pageId}
  if (u.includes("/funnels/page/") && !u.includes("/builder/")) {
    const m = url.match(/\/funnels\/page\/([^/?&#\s]+)/i);
    return { tag: "PAGE_SCHEMA", pageId: m?.[1] };
  }

  // FUNNEL_SCHEMA: GET /funnels/funnel/fetch/{funnelId}
  if (u.includes("/funnels/funnel/fetch/")) {
    const m = url.match(/\/funnels\/funnel\/fetch\/([^/?&#\s]+)/i);
    return { tag: "FUNNEL_SCHEMA", funnelId: m?.[1] };
  }

  // SAVE_EVENT patterns
  if (u.includes("/funnels/builder/autosave")) {
    const pm = url.match(/\/pages?\/([^/?&#\s]+)/i);
    const fm = url.match(/\/funnels?\/([^/?&#\s]+)/i);
    return { tag: "SAVE_EVENT", pageId: pm?.[1], funnelId: fm?.[1], eventType: "autosave" };
  }
  if (u.includes("/funnels/builder/prebuilt-section")) {
    return { tag: "SAVE_EVENT", eventType: "prebuilt-section" };
  }
  if (u.includes("/funnels/builder/global-section")) {
    return { tag: "SAVE_EVENT", eventType: "global-section" };
  }
  // Catch-all save: POST/PUT/PATCH to /funnels/builder/
  if (u.includes("/funnels/builder/") && ["POST","PUT","PATCH"].includes("")) {
    return { tag: "SAVE_EVENT", eventType: "other-save" };
  }

  return { tag: null };
}

// ── JSON helpers ──────────────────────────────────────────────────────────────

// Known HighLevel builder element type names
const KNOWN_ELEMENT_TYPES = new Set([
  "headline","paragraph","text","richtext",
  "image","video","audio","gif",
  "button","link",
  "form","input","textarea","select","radio","checkbox","captcha",
  "icon","icon-text","fa-icon",
  "list","ordered-list","unordered-list",
  "countdown","timer",
  "divider","spacer","separator","blank",
  "html","custom","embed","code","raw-html",
  "section","row","column","container","box","grid","flex",
  "map","survey","calendar","chat","testimonial","pricing",
  "progress","slider","carousel","tabs","accordion","navbar",
  "social","share","comments","rating",
]);

/** Walk the object and tally all `type` values found in any element-like object */
function detectElementTypes(obj: unknown): Record<string, number> {
  const counts: Record<string, number> = {};
  const seen = new WeakSet();

  const walk = (v: unknown, depth: number) => {
    if (depth > 25 || v === null || typeof v !== "object") return;
    if (seen.has(v as object)) return;
    seen.add(v as object);

    if (Array.isArray(v)) {
      v.forEach((item) => walk(item, depth + 1));
      return;
    }

    const o = v as Record<string, unknown>;
    // If this object has a "type" field that's a string, tally it
    if (typeof o.type === "string" && o.type) {
      const t = o.type.toLowerCase().trim();
      // Accept anything that looks like a builder element type
      if (KNOWN_ELEMENT_TYPES.has(t) || (t.length > 1 && t.length < 40 && !/^https?:/.test(t))) {
        counts[t] = (counts[t] ?? 0) + 1;
      }
    }
    for (const val of Object.values(o)) walk(val, depth + 1);
  };

  walk(obj, 0);
  return counts;
}

/** Recursively count builder element arrays anywhere in the object */
function countElements(obj: unknown, depth = 0): ElementCounts {
  const counts: ElementCounts = { sections: 0, rows: 0, columns: 0, elements: 0 };
  if (depth > 20 || obj === null || typeof obj !== "object") return counts;

  const rec = (v: unknown, d: number) => {
    if (d > 20 || v === null || typeof v !== "object") return;
    if (Array.isArray(v)) { v.forEach((item) => rec(item, d + 1)); return; }
    for (const [k, val] of Object.entries(v as Record<string, unknown>)) {
      if (Array.isArray(val)) {
        if (k === "sections")  counts.sections  += val.length;
        if (k === "rows")      counts.rows      += val.length;
        if (k === "columns")   counts.columns   += val.length;
        if (k === "elements")  counts.elements  += val.length;
        val.forEach((item) => rec(item, d + 1));
      } else {
        rec(val, d + 1);
      }
    }
  };
  rec(obj, 0);
  return counts;
}

function pluck(obj: unknown, ...keys: string[]): string | undefined {
  if (obj === null || typeof obj !== "object") return undefined;
  const o = obj as Record<string, unknown>;
  for (const k of keys) {
    if (typeof o[k] === "string" && o[k]) return o[k] as string;
  }
  // Search one level deeper
  for (const val of Object.values(o)) {
    if (val && typeof val === "object" && !Array.isArray(val)) {
      const found = pluck(val, ...keys);
      if (found) return found;
    }
  }
  return undefined;
}

/**
 * Walk the parsed funnel response and extract steps[] with their page IDs.
 *
 * HL structure (any nesting depth):
 *   { steps: [{ id, name, path, pages: ["pageId1", "pageId2"] }] }
 *
 * "pages" inside a step is always an array of plain ID strings.
 */
function extractSteps(obj: unknown): FunnelStep[] {
  if (!obj || typeof obj !== "object") return [];

  // Locate the first "steps" array anywhere in the object (BFS, max depth 6)
  const findStepsArray = (v: unknown, depth: number): unknown[] | null => {
    if (depth > 6 || !v || typeof v !== "object" || Array.isArray(v)) return null;
    const o = v as Record<string, unknown>;
    if (Array.isArray(o["steps"]) && o["steps"].length > 0) return o["steps"] as unknown[];
    for (const val of Object.values(o)) {
      const found = findStepsArray(val, depth + 1);
      if (found) return found;
    }
    return null;
  };

  const stepsArr = findStepsArray(obj, 0);
  if (!stepsArr) return [];

  const steps: FunnelStep[] = [];
  for (const item of stepsArr) {
    if (!item || typeof item !== "object" || Array.isArray(item)) continue;
    const s = item as Record<string, unknown>;
    const stepId = (s["id"] ?? s["stepId"] ?? s["_id"] ?? "") as string;
    if (!stepId) continue;

    // "pages" in a step is an array of string page IDs
    let pageIds: string[] = [];
    if (Array.isArray(s["pages"])) {
      pageIds = (s["pages"] as unknown[]).filter((p) => typeof p === "string") as string[];
    } else if (Array.isArray(s["pageIds"])) {
      pageIds = (s["pageIds"] as unknown[]).filter((p) => typeof p === "string") as string[];
    }

    steps.push({
      stepId,
      name:    (s["name"] ?? s["title"] ?? s["pageName"] ?? undefined) as string | undefined,
      path:    (s["path"] ?? s["slug"]  ?? s["url"]       ?? undefined) as string | undefined,
      pageIds,
    });
  }
  return steps;
}

// ── Storage helpers ───────────────────────────────────────────────────────────

export async function getPageSchemas(): Promise<PageSchemaRecord[]> {
  const r = await chrome.storage.local.get(PAGE_SCHEMAS_KEY);
  return Array.isArray(r[PAGE_SCHEMAS_KEY]) ? r[PAGE_SCHEMAS_KEY] : [];
}

export async function getFunnelSchemas(): Promise<FunnelSchemaRecord[]> {
  const r = await chrome.storage.local.get(FUNNEL_SCHEMAS_KEY);
  return Array.isArray(r[FUNNEL_SCHEMAS_KEY]) ? r[FUNNEL_SCHEMAS_KEY] : [];
}

export async function getSaveEvents(): Promise<SaveEventRecord[]> {
  const r = await chrome.storage.local.get(SAVE_EVENTS_KEY);
  return Array.isArray(r[SAVE_EVENTS_KEY]) ? r[SAVE_EVENTS_KEY] : [];
}

export async function clearSchemaStore(): Promise<void> {
  await chrome.storage.local.remove([PAGE_SCHEMAS_KEY, FUNNEL_SCHEMAS_KEY, SAVE_EVENTS_KEY]);
}

// ── Main entry — called from debugger-network after addSnapshot ───────────────

export async function classifyAndStore(snapshot: PayloadSnapshot): Promise<SchemaTag> {
  const { tag, pageId, funnelId, eventType } = classifyUrl(snapshot.requestUrl);

  if (tag === "PAGE_SCHEMA" && snapshot.rawBody && snapshot.rawBody.length > 2) {
    await _storePageSchema(snapshot, pageId);
    return "PAGE_SCHEMA";
  }

  if (tag === "FUNNEL_SCHEMA" && snapshot.rawBody && snapshot.rawBody.length > 2) {
    await _storeFunnelSchema(snapshot, funnelId);
    return "FUNNEL_SCHEMA";
  }

  if (tag === "SAVE_EVENT") {
    await _storeSaveEvent(snapshot, pageId, funnelId, eventType ?? "other-save");
    return "SAVE_EVENT";
  }

  return null;
}

async function _storePageSchema(snap: PayloadSnapshot, pageId?: string): Promise<void> {
  let parsed: unknown;
  try { parsed = JSON.parse(snap.rawBody); } catch { return; }

  const id = pageId ?? pluck(parsed, "id", "pageId", "_id") ?? snap.id;
  const raw = snap.rawBody.slice(0, 500_000);
  const summary      = countElements(parsed);
  const elementTypes = detectElementTypes(parsed);

  // Extract pageDataDownloadUrl at any depth
  const downloadUrl = pluck(
    parsed,
    "pageDataDownloadUrl", "pageDataUrl", "dataDownloadUrl", "downloadUrl",
  ) ?? _findDownloadUrl(parsed);

  const record: PageSchemaRecord = {
    pageId:              id,
    snapshotId:          snap.id,
    capturedAt:          snap.timestamp,
    url:                 snap.requestUrl,
    raw,
    title:               pluck(parsed, "name", "title", "pageName"),
    slug:                pluck(parsed, "path", "slug", "url", "pathname"),
    summary,
    elementTypes,
    linkedSaveIds:       [],
    pageDataDownloadUrl: downloadUrl ?? undefined,
  };

  const existing = await getPageSchemas();
  const filtered = existing.filter((r) => r.pageId !== id || r.snapshotId !== snap.id);
  const updated = [record, ...filtered].slice(0, MAX_PAGE_SCHEMAS);
  await chrome.storage.local.set({ [PAGE_SCHEMAS_KEY]: updated });

  // Auto-fetch the layout in the background (non-blocking)
  if (downloadUrl) {
    _fetchAndStoreLayout(id, downloadUrl).catch(() => {/* silent */});
  }
}

/** Recursively search for a value that looks like a Firebase Storage URL */
function _findDownloadUrl(obj: unknown, depth = 0): string | undefined {
  if (depth > 6 || !obj || typeof obj !== "object") return undefined;
  if (Array.isArray(obj)) {
    for (const item of obj) {
      const r = _findDownloadUrl(item, depth + 1);
      if (r) return r;
    }
    return undefined;
  }
  for (const [k, v] of Object.entries(obj as Record<string, unknown>)) {
    if (
      typeof v === "string" &&
      (k.toLowerCase().includes("downloadurl") || k.toLowerCase().includes("pagedata")) &&
      (v.startsWith("https://firebasestorage") || v.startsWith("https://storage.googleapis"))
    ) {
      return v;
    }
    const r = _findDownloadUrl(v, depth + 1);
    if (r) return r;
  }
  return undefined;
}

/**
 * Fetch the Firebase page layout JSON and patch it onto the stored record.
 * Called automatically on capture; also exported for the manual "Download" button.
 */
async function _fetchAndStoreLayout(pageId: string, url: string): Promise<unknown> {
  const res = await fetch(url);
  if (!res.ok) throw new Error(`Layout fetch failed: ${res.status}`);
  const layout = await res.json() as unknown;

  const existing = await getPageSchemas();
  // Patch the most-recent record for this pageId (there may be multiple captures)
  let patched = false;
  const updated = existing.map((r) => {
    if (r.pageId === pageId && !patched) {
      patched = true;
      return { ...r, pageLayout: layout, layoutCapturedAt: new Date().toISOString() };
    }
    return r;
  });
  if (patched) {
    await chrome.storage.local.set({ [PAGE_SCHEMAS_KEY]: updated });
    // Auto-scan the freshly fetched layout for asset URLs
    const patchedRecord = updated.find((r) => r.pageId === pageId && r.pageLayout);
    if (patchedRecord) {
      scanPageLayoutForAssets(patchedRecord).catch(() => {});
    }
  }
  return layout;
}

/**
 * Public entry-point called by the message router when the inspector fires
 * the "Download Page Layout" button for a page that wasn't auto-fetched yet.
 */
export async function fetchAndStorePageLayout(pageId: string): Promise<{ layout: unknown } | null> {
  const records = await getPageSchemas();
  const record = records.find((r) => r.pageId === pageId);
  if (!record?.pageDataDownloadUrl) return null;
  const layout = await _fetchAndStoreLayout(pageId, record.pageDataDownloadUrl);
  return { layout };
}

async function _storeFunnelSchema(snap: PayloadSnapshot, funnelId?: string): Promise<void> {
  let parsed: unknown;
  try { parsed = JSON.parse(snap.rawBody); } catch { return; }

  const id    = funnelId ?? pluck(parsed, "id", "funnelId", "_id") ?? snap.id;
  const name  = pluck(parsed, "name", "title", "funnelName");
  const steps = extractSteps(parsed);
  const raw   = snap.rawBody.slice(0, 500_000);

  // Flat union of all pageIds across all steps (deduplicated)
  const allPageIds = [...new Set(steps.flatMap((s) => s.pageIds))];

  const record: FunnelSchemaRecord = {
    funnelId:   id,
    snapshotId: snap.id,
    capturedAt: snap.timestamp,
    url:        snap.requestUrl,
    raw,
    name,
    pageCount:  allPageIds.length,
    pageIds:    allPageIds,
    steps,
  };

  const existing = await getFunnelSchemas();
  const filtered = existing.filter((r) => r.funnelId !== id || r.snapshotId !== snap.id);
  const updated = [record, ...filtered].slice(0, MAX_FUNNEL_SCHEMAS);
  await chrome.storage.local.set({ [FUNNEL_SCHEMAS_KEY]: updated });
}

async function _storeSaveEvent(
  snap: PayloadSnapshot,
  pageId?: string,
  funnelId?: string,
  eventType: SaveEventRecord["eventType"] = "other-save",
): Promise<void> {
  const record: SaveEventRecord = {
    snapshotId: snap.id,
    capturedAt: snap.timestamp,
    url:        snap.requestUrl,
    method:     snap.method,
    eventType,
    pageId,
    funnelId,
    bodySize:   snap.requestBodyText?.length ?? 0,
  };

  const existing = await getSaveEvents();
  const updated  = [record, ...existing].slice(0, MAX_SAVE_EVENTS);
  await chrome.storage.local.set({ [SAVE_EVENTS_KEY]: updated });

  // Link this save event back to the most recent matching page schema
  if (pageId) {
    const pages = await getPageSchemas();
    const page  = pages.find((p) => p.pageId === pageId);
    if (page && !page.linkedSaveIds.includes(snap.id)) {
      page.linkedSaveIds = [snap.id, ...page.linkedSaveIds].slice(0, 20);
      const patched = pages.map((p) => (p.pageId === pageId && p.snapshotId === page.snapshotId ? page : p));
      await chrome.storage.local.set({ [PAGE_SCHEMAS_KEY]: patched });
    }
  }
}

// ── Full Funnel Package builder ───────────────────────────────────────────────

export interface FunnelPackagePage {
  stepId:   string;
  pageId:   string;
  name?:    string;
  path?:    string;
  captured: boolean;           // false = page listed in funnel but not yet captured
  schema:   unknown | null;    // parsed JSON of the /funnels/page/{id} response
  layout:   unknown | null;    // parsed JSON from pageDataDownloadUrl (Firebase)
}

export async function buildFunnelPackage(funnelId: string): Promise<{
  funnel: FunnelSchemaRecord;
  pages: FunnelPackagePage[];
  saveEvents: SaveEventRecord[];
  exportedAt: string;
} | null> {
  const funnels = await getFunnelSchemas();
  const funnel  = funnels.find((f) => f.funnelId === funnelId);
  if (!funnel) return null;

  const allPages = await getPageSchemas();
  const allSaves = await getSaveEvents();

  // Build a map: pageId → latest captured PageSchemaRecord
  // (allPages is already stored latest-first, so first match wins)
  const latestPageByPageId = new Map<string, PageSchemaRecord>();
  for (const p of allPages) {
    if (!latestPageByPageId.has(p.pageId)) {
      latestPageByPageId.set(p.pageId, p);
    }
  }

  // Walk steps[] and emit one FunnelPackagePage per (step × pageId) pair
  const pages: FunnelPackagePage[] = [];
  for (const step of funnel.steps) {
    for (const pid of step.pageIds) {
      const captured = latestPageByPageId.get(pid) ?? null;
      let schema: unknown | null = null;
      if (captured) {
        try { schema = JSON.parse(captured.raw); } catch { schema = null; }
      }
      pages.push({
        stepId:   step.stepId,
        pageId:   pid,
        name:     captured?.title ?? step.name,
        path:     captured?.slug  ?? step.path,
        captured: captured !== null,
        schema,
        layout:   captured?.pageLayout ?? null,
      });
    }
  }

  // Fallback: if the funnel was stored without steps (old format or no steps found),
  // try matching page schemas via the flat pageIds list
  if (funnel.steps.length === 0 && funnel.pageIds.length > 0) {
    for (const pid of funnel.pageIds) {
      const captured = latestPageByPageId.get(pid) ?? null;
      let schema: unknown | null = null;
      if (captured) {
        try { schema = JSON.parse(captured.raw); } catch { schema = null; }
      }
      pages.push({
        stepId:   "unknown",
        pageId:   pid,
        name:     captured?.title,
        path:     captured?.slug,
        captured: captured !== null,
        schema,
        layout:   captured?.pageLayout ?? null,
      });
    }
  }

  const allPageIds  = new Set(funnel.pageIds);
  const saveEvents  = allSaves.filter(
    (s) => s.funnelId === funnelId || (s.pageId && allPageIds.has(s.pageId))
  );

  return { funnel, pages, saveEvents, exportedAt: new Date().toISOString() };
}
