import { FunnelMap, FunnelPage, FunnelEdge } from "../schema/funnel-map";
import { generateAllPlaceholders } from "./thumbnail-plan";

export function buildSitemap(
  rootUrl: string,
  pages: FunnelPage[],
  edges: FunnelEdge[],
  diagnostics: string[],
  settings: FunnelMap["settings"]
): FunnelMap {
  const thumbnails = generateAllPlaceholders(pages);
  const pagesWithThumbnails = pages.map((page) => {
    const thumb = thumbnails.get(page.id);
    if (thumb) {
      return { ...page, thumbnailDataUrl: thumb.dataUrl };
    }
    return page;
  });

  return {
    rootUrl,
    discoveredPages: pagesWithThumbnails,
    edges,
    diagnostics,
    crawledAt: new Date().toISOString(),
    settings,
  };
}
