/**
 * Asset Store
 * Recursively scans captured page layout JSON for image, video, font, and
 * other asset URLs. Stores up to MAX_ASSETS records sorted by type, then URL.
 */
import type { PageSchemaRecord } from "./schema-store";

export const ASSETS_KEY = "clonelevel_assets";
const MAX_ASSETS = 500;

// ── Types ──────────────────────────────────────────────────────────────────────

export type AssetType = "image" | "video" | "font" | "audio" | "script" | "style" | "other";

export interface AssetRecord {
  url:        string;
  type:       AssetType;
  ext:        string;           // lowercased file extension or ""
  domain:     string;           // hostname
  pageId:     string;
  pageTitle:  string;
  source:     string;           // the page schema URL this was found in
  capturedAt: string;           // ISO
}

// ── URL classification ─────────────────────────────────────────────────────────

const IMAGE_EXTS  = new Set(["jpg","jpeg","png","gif","webp","svg","avif","ico","bmp","tiff"]);
const VIDEO_EXTS  = new Set(["mp4","webm","mov","avi","m3u8","flv","mkv"]);
const FONT_EXTS   = new Set(["woff","woff2","ttf","eot","otf"]);
const AUDIO_EXTS  = new Set(["mp3","ogg","wav","m4a","aac","flac"]);
const SCRIPT_EXTS = new Set(["js","mjs"]);
const STYLE_EXTS  = new Set(["css"]);

const KNOWN_IMAGE_DOMAINS = [
  "storage.googleapis.com",
  "firebasestorage.googleapis.com",
  "cdn.gohighlevel.com",
  "msgsndr.com",
  "images.unsplash.com",
  "images.pexels.com",
  "cloudfront.net",
  "s3.amazonaws.com",
  "s3.us-east",
  "imagekit.io",
  "imgix.net",
];

function classifyAssetUrl(raw: string): { type: AssetType; ext: string; domain: string } | null {
  let href: URL;
  try { href = new URL(raw); } catch { return null; }

  // Must be http(s)
  if (href.protocol !== "http:" && href.protocol !== "https:") return null;

  const domain = href.hostname.toLowerCase();

  // Skip known noise domains
  if (
    domain.includes("analytics") || domain.includes("segment.io") ||
    domain.includes("google-analytics") || domain.includes("doubleclick") ||
    domain.includes("facebook.net") || domain.includes("hotjar") ||
    domain.includes("intercom") || domain.includes("sentry") ||
    raw.includes("/__/") || raw.includes("/beacon")
  ) return null;

  // Derive extension from pathname
  const path = href.pathname;
  const lastDot = path.lastIndexOf(".");
  const lastSlash = path.lastIndexOf("/");
  const ext = lastDot > lastSlash && lastDot < path.length - 1
    ? path.slice(lastDot + 1).split(/[?#]/)[0].toLowerCase()
    : "";

  if (IMAGE_EXTS.has(ext))  return { type: "image",  ext, domain };
  if (VIDEO_EXTS.has(ext))  return { type: "video",  ext, domain };
  if (FONT_EXTS.has(ext))   return { type: "font",   ext, domain };
  if (AUDIO_EXTS.has(ext))  return { type: "audio",  ext, domain };
  if (SCRIPT_EXTS.has(ext)) return { type: "script", ext, domain };
  if (STYLE_EXTS.has(ext))  return { type: "style",  ext, domain };

  // Check for known CDN / storage image domains even without extension
  if (KNOWN_IMAGE_DOMAINS.some((d) => domain.includes(d))) {
    return { type: "image", ext, domain };
  }

  // Only store URLs that look like they point to a file (have a path)
  if (path.length > 2 && ext.length === 0) return { type: "other", ext, domain };

  return null;
}

// ── Recursive URL extractor ────────────────────────────────────────────────────

const URL_PATTERN = /https?:\/\/[^\s"'<>`,)\\]+/g;

function extractUrlsFromString(str: string): string[] {
  const matches: string[] = [];
  let m: RegExpExecArray | null;
  URL_PATTERN.lastIndex = 0;
  while ((m = URL_PATTERN.exec(str)) !== null) {
    // Trim common trailing punctuation
    let u = m[0].replace(/[.,;:)}\]]+$/, "");
    if (u.startsWith("http")) matches.push(u);
  }
  return matches;
}

function walkJson(obj: unknown, depth = 0, urls: Set<string> = new Set(), seen = new WeakSet()): Set<string> {
  if (depth > 30 || obj === null) return urls;
  if (typeof obj === "string") {
    // Check if the string itself is a URL
    if (obj.startsWith("http")) {
      urls.add(obj.trimEnd().replace(/[.,;:)}\]]+$/, ""));
    } else if (obj.includes("https://") || obj.includes("http://")) {
      // Extract embedded URLs from longer strings (e.g. CSS background-image)
      extractUrlsFromString(obj).forEach((u) => urls.add(u));
    }
    return urls;
  }
  if (typeof obj !== "object") return urls;
  if (seen.has(obj as object)) return urls;
  seen.add(obj as object);

  if (Array.isArray(obj)) {
    for (const item of obj) walkJson(item, depth + 1, urls, seen);
  } else {
    for (const val of Object.values(obj as Record<string, unknown>)) {
      walkJson(val, depth + 1, urls, seen);
    }
  }
  return urls;
}

// ── Public API ─────────────────────────────────────────────────────────────────

export async function getAllAssets(): Promise<AssetRecord[]> {
  const r = await chrome.storage.local.get(ASSETS_KEY);
  return Array.isArray(r[ASSETS_KEY]) ? r[ASSETS_KEY] : [];
}

export async function clearAssets(): Promise<void> {
  await chrome.storage.local.remove(ASSETS_KEY);
}

/**
 * Scan a page's captured layout JSON for asset URLs and merge them into the
 * asset store. Returns the count of newly added records.
 */
export async function scanPageLayoutForAssets(page: PageSchemaRecord): Promise<number> {
  if (!page.pageLayout) return 0;

  const now      = new Date().toISOString();
  const pageId   = page.pageId;
  const pageTitle = page.title ?? page.slug ?? page.pageId;
  const source   = page.url;

  // Walk the layout JSON and collect all raw URLs
  const rawUrls = walkJson(page.pageLayout);

  // Classify each URL
  const newRecords: AssetRecord[] = [];
  for (const raw of rawUrls) {
    const cls = classifyAssetUrl(raw);
    if (!cls) continue;
    // Skip very long data: URLs
    if (raw.length > 2048) continue;
    newRecords.push({
      url: raw, type: cls.type, ext: cls.ext, domain: cls.domain,
      pageId, pageTitle, source, capturedAt: now,
    });
  }

  if (newRecords.length === 0) return 0;

  // Merge with existing, deduplicating by url+pageId
  const existing: AssetRecord[] = await getAllAssets();
  const existingKeys = new Set(existing.map((r) => `${r.url}::${r.pageId}`));
  const fresh = newRecords.filter((r) => !existingKeys.has(`${r.url}::${r.pageId}`));
  if (fresh.length === 0) return 0;

  const merged = [...existing, ...fresh]
    .sort((a, b) => a.type.localeCompare(b.type) || a.url.localeCompare(b.url))
    .slice(0, MAX_ASSETS);

  await chrome.storage.local.set({ [ASSETS_KEY]: merged });
  return fresh.length;
}

/**
 * Re-scan all stored page layouts and rebuild the asset store from scratch.
 */
export async function rebuildAssetStore(pages: PageSchemaRecord[]): Promise<number> {
  await clearAssets();
  let total = 0;
  for (const page of pages) {
    if (page.pageLayout) total += await scanPageLayoutForAssets(page);
  }
  return total;
}
