/**
 * State Extractor
 * Probes the HighLevel builder page's in-memory global state by injecting a
 * function into the MAIN world (page context) via chrome.scripting.executeScript.
 *
 * Checks: window.__INITIAL_STATE__, window.store.getState(), window.appStore,
 *         window.pageData, window.builderData, window.__NEXT_DATA__, window.__NUXT__
 *         and more — searching for keys matching the HL builder schema vocabulary.
 */

const STORAGE_KEY = "clonelevel_state_extracts";

export interface StateCandidate {
  id: string;
  capturedAt: string;
  /** e.g. "window.__INITIAL_STATE__" or "window.store.getState()" */
  source: string;
  /** Max nesting depth of the object */
  depth: number;
  /** JSON byte size */
  byteSize: number;
  /** Builder-schema keys matched inside the object */
  matchedKeys: string[];
  /** Computed priority score (higher = more relevant) */
  score: number;
  /** Top-level keys of the object (up to 40) */
  topLevelKeys: string[];
  /** First 800 chars of JSON for quick preview */
  preview: string;
  /** Full JSON, capped at 200 KB */
  full: string;
}

export interface StateExtractResult {
  id: string;
  extractedAt: string;
  tabId: number;
  tabUrl: string;
  candidates: StateCandidate[];
  error?: string;
}

// ── Storage helpers ────────────────────────────────────────────────────────────

export async function getStateExtracts(): Promise<StateExtractResult[]> {
  const res = await chrome.storage.local.get(STORAGE_KEY);
  return Array.isArray(res[STORAGE_KEY]) ? res[STORAGE_KEY] : [];
}

export async function clearStateExtracts(): Promise<void> {
  await chrome.storage.local.remove(STORAGE_KEY);
}

async function saveStateExtract(result: StateExtractResult): Promise<void> {
  const existing = await getStateExtracts();
  // Keep last 10 extractions
  const updated = [result, ...existing].slice(0, 10);
  await chrome.storage.local.set({ [STORAGE_KEY]: updated });
}

// ── Main world probe function (serialized and injected) ───────────────────────
//
// IMPORTANT: This function must be SELF-CONTAINED — no closure references.
// It runs in the page's MAIN world via chrome.scripting.executeScript.

function _probePageState(): {
  source: string;
  depth: number;
  byteSize: number;
  matchedKeys: string[];
  topLevelKeys: string[];
  json: string;
}[] {
  const BUILDER_KEYS = [
    "page","pages","site","sites","funnel","funnels",
    "sections","rows","columns","elements","styles",
    "layout","content","blocks","nodes","steps",
    "children","components","draft","publish","builder",
    "pageData","siteData","funnelData","locationId",
  ];

  /** Measure max nesting depth (bounded to avoid stack overflow) */
  function maxDepth(obj: unknown, d: number): number {
    if (d > 15 || obj === null || typeof obj !== "object") return d;
    let m = d;
    const keys = Object.keys(obj as Record<string, unknown>).slice(0, 10);
    for (const k of keys) {
      const v = maxDepth((obj as Record<string, unknown>)[k], d + 1);
      if (v > m) m = v;
    }
    return m;
  }

  /** Find BUILDER_KEYS that appear as JSON keys in the object */
  function matchedBuilderKeys(json: string, keys: string[]): string[] {
    return keys.filter((k) => json.includes(`"${k}"`));
  }

  // Global probes to check
  const PROBES: Array<[string, () => unknown]> = [
    ["window.__INITIAL_STATE__",     () => (window as any).__INITIAL_STATE__],
    ["window.store.getState()",      () => { const s = (window as any).store; return typeof s?.getState === "function" ? s.getState() : undefined; }],
    ["window.appStore.getState()",   () => { const s = (window as any).appStore; return typeof s?.getState === "function" ? s.getState() : undefined; }],
    ["window.pageData",              () => (window as any).pageData],
    ["window.builderData",           () => (window as any).builderData],
    ["window.__NEXT_DATA__",         () => (window as any).__NEXT_DATA__],
    ["window.__NUXT__",              () => (window as any).__NUXT__],
    ["window.__STATE__",             () => (window as any).__STATE__],
    ["window.__STORE__",             () => (window as any).__STORE__],
    ["window.vuex",                  () => (window as any).vuex],
    ["window.App",                   () => (window as any).App],
    ["window._pageConfig",           () => (window as any)._pageConfig],
    ["window.funnelConfig",          () => (window as any).funnelConfig],
    ["window.pageConfig",            () => (window as any).pageConfig],
    ["window.__clConfig",            () => (window as any).__clConfig],
    ["window.hl",                    () => (window as any).hl],
    ["window.HLBuilder",             () => (window as any).HLBuilder],
    ["window.__BUILDER_DATA__",      () => (window as any).__BUILDER_DATA__],
  ];

  const results: ReturnType<typeof _probePageState> = [];

  for (const [name, probe] of PROBES) {
    try {
      const val = probe();
      if (val === null || val === undefined) continue;
      if (typeof val !== "object" && typeof val !== "function") continue;

      let json = "";
      try {
        json = JSON.stringify(val);
      } catch {
        json = "[non-serializable]";
      }
      if (json === "{}") continue;

      const matched = matchedBuilderKeys(json, BUILDER_KEYS);
      // Require at least one builder key match to avoid pure noise
      if (matched.length === 0) continue;

      results.push({
        source: name,
        depth: maxDepth(val, 0),
        byteSize: json.length,
        matchedKeys: matched,
        topLevelKeys: typeof val === "object" ? Object.keys(val as object).slice(0, 40) : [],
        json: json.slice(0, 200_000), // cap at 200 KB
      });
    } catch {
      // Probe threw — skip
    }
  }

  return results;
}

// ── Priority scoring (runs in SW context) ─────────────────────────────────────

function scoreCandidateRaw(raw: ReturnType<typeof _probePageState>[0]): number {
  let s = 0;
  // More matched builder keys = better
  s += Math.min(raw.matchedKeys.length * 8, 60);
  // Deeper nesting = likely a real data structure
  s += Math.min(raw.depth * 3, 20);
  // Larger payload = more likely to contain actual page data
  if (raw.byteSize > 10_000) s += 10;
  if (raw.byteSize > 100_000) s += 10;
  // Prefer store.getState() — usually the most complete
  if (raw.source.includes("getState")) s += 15;
  // Prefer known HL-specific keys
  const highValueKeys = ["funnel","funnels","page","pages","site","sections","elements","locationId","draft"];
  const highMatches = raw.matchedKeys.filter((k) => highValueKeys.includes(k)).length;
  s += highMatches * 5;
  return Math.min(s, 100);
}

// ── Public API ─────────────────────────────────────────────────────────────────

export async function runStateExtract(
  tabId: number,
): Promise<{ ok: boolean; result?: StateExtractResult; error?: string }> {
  let tabUrl = "";
  try { const t = await chrome.tabs.get(tabId); tabUrl = t.url ?? ""; } catch {}

  const extractId = `se_${Date.now()}_${Math.random().toString(36).slice(2, 6)}`;

  try {
    const scriptResults = await chrome.scripting.executeScript({
      target: { tabId, allFrames: false },
      world: "MAIN",
      func: _probePageState,
    });

    const raw = (scriptResults?.[0]?.result ?? []) as ReturnType<typeof _probePageState>;

    const candidates: StateCandidate[] = raw.map((r, i) => {
      const score = scoreCandidateRaw(r);
      return {
        id: `${extractId}_${i}`,
        capturedAt: new Date().toISOString(),
        source: r.source,
        depth: r.depth,
        byteSize: r.byteSize,
        matchedKeys: r.matchedKeys,
        score,
        topLevelKeys: r.topLevelKeys,
        preview: r.json.slice(0, 800),
        full: r.json,
      };
    });

    // Sort by score descending
    candidates.sort((a, b) => b.score - a.score);

    const result: StateExtractResult = {
      id: extractId,
      extractedAt: new Date().toISOString(),
      tabId,
      tabUrl,
      candidates,
    };

    await saveStateExtract(result);
    return { ok: true, result };
  } catch (err) {
    const result: StateExtractResult = {
      id: extractId,
      extractedAt: new Date().toISOString(),
      tabId,
      tabUrl,
      candidates: [],
      error: String(err),
    };
    await saveStateExtract(result);
    return { ok: false, result, error: String(err) };
  }
}
