/**
 * Real Tab Tracker
 * Tracks the last non-extension browser tab the user had active.
 * This solves the problem where chrome.tabs.query({ active: true, currentWindow: true })
 * returns the extension inspector tab when the inspector is focused.
 */

const BLOCKED_PREFIXES = [
  "chrome-extension://",
  "chrome://",
  "edge://",
  "about:",
  "devtools://",
  "moz-extension://",
  "file:///",
];

export function isRealUrl(url?: string): boolean {
  if (!url) return false;
  return (url.startsWith("http://") || url.startsWith("https://")) &&
         !BLOCKED_PREFIXES.some((p) => url.startsWith(p));
}

interface TrackedTab {
  tabId:      number;
  url:        string;
  title:      string;
  favIconUrl: string;
  updatedAt:  number;
}

let _lastReal: TrackedTab | null = null;

export function updateRealTab(tab: chrome.tabs.Tab): void {
  if (!tab.id || !tab.url || !isRealUrl(tab.url)) return;
  _lastReal = {
    tabId:      tab.id,
    url:        tab.url,
    title:      tab.title      ?? "",
    favIconUrl: tab.favIconUrl ?? "",
    updatedAt:  Date.now(),
  };
}

export function getLastRealTab(): TrackedTab | null {
  return _lastReal;
}

/** Resolves the best "real" tab to operate on.
 *  Priority: last tracked real tab → any active real tab across all windows. */
export async function resolveRealTab(): Promise<chrome.tabs.Tab | null> {
  // 1. Prefer the tab we last saw the user on
  if (_lastReal) {
    try {
      const tab = await chrome.tabs.get(_lastReal.tabId);
      if (tab?.url && isRealUrl(tab.url)) return tab;
    } catch { /* tab was closed */ }
  }

  // 2. Fall back: search all windows for any active non-extension tab
  const allActive = await chrome.tabs.query({ active: true });
  const real = allActive.find((t) => isRealUrl(t.url));
  if (real) { updateRealTab(real); return real; }

  // 3. Last resort: any non-extension tab in any window
  const allTabs = await chrome.tabs.query({});
  const any = allTabs.find((t) => isRealUrl(t.url));
  if (any) { updateRealTab(any); return any; }

  return null;
}
