import { PageContext } from "../types/page-context";

const tabContexts: Map<number, PageContext> = new Map();

export function setTabContext(tabId: number, context: PageContext): void {
  tabContexts.set(tabId, context);
}

export function getTabContext(tabId: number): PageContext | undefined {
  return tabContexts.get(tabId);
}

export function removeTabContext(tabId: number): void {
  tabContexts.delete(tabId);
}

export function getAllTabContexts(): Map<number, PageContext> {
  return new Map(tabContexts);
}
